                { Key = "Cat_Combat_Graphic", Text = "➠ IPAD VIEW/FPS", Stack =StackCombatGraphic }                
            }
        }
        
        -- Hapus menu ModMenu yang sudah ada (dari mod lain) di SettingCatalog
        for i = #SettingCatalog, 1, -1 do
            if SettingCatalog[i] and SettingCatalog[i].Key == "ModMenu" then
                table.remove(SettingCatalog, i)
            end
        end

        local _szUiUtil = nil
        local function GetSkinIcon(itemId)
            if not itemId or itemId == 0 then return "" end
            if _szUiUtil == nil then
                local ok, m = pcall(require, "client.common.ui_util")
                _szUiUtil = ok and m or false
            end
            if _szUiUtil and _szUiUtil.GetItemSmallIcon then
                local ok2, path = pcall(_szUiUtil.GetItemSmallIcon, itemId)
                if ok2 and type(path) == "string" and path ~= "" then return path end
            end
            return ""
        end
        local SZ_IMG_SWITCHER = nil
        pcall(function()
            local UM = _G.UIManager
            if UM and UM.UI_Config then SZ_IMG_SWITCHER = UM.UI_Config.Setting_Option_ImageSwitcher end
        end)

        local function BuildGroupRows(list, cfgKey, groupPrefix, st)
            st = st or {}
            local perGroup = 4
            local totalGroups = math.ceil(#list / perGroup)
            local siblingKeys = {}
            for gid2 = 1, totalGroups do
                siblingKeys[#siblingKeys + 1] = "SZG_" .. cfgKey .. "_" .. gid2
            end
            local function RefreshSiblingRows(exceptKey, extraKey)
                pcall(function()
                    local tk = require("common.time_ticker")
                    local function doPost()
                        pcall(function()
                            if not (EventSystem and EVENTTYPE_SETTING and EVENTID_SETTING_OPTION_FORCEUPDATE) then return end
                            for _, k2 in ipairs(siblingKeys) do
                                if k2 ~= exceptKey then
                                    EventSystem:postEvent(EVENTTYPE_SETTING, EVENTID_SETTING_OPTION_FORCEUPDATE, k2)
                                end
                            end
                            if extraKey then
                                EventSystem:postEvent(EVENTTYPE_SETTING, EVENTID_SETTING_OPTION_FORCEUPDATE, extraKey)
                            end
                        end)
                    end
                    if tk and tk.AddTimerOnce then tk.AddTimerOnce(0.1, doPost) else doPost() end
                end)
            end
            for gi = 0, totalGroups - 1 do
                local texts = { "Close" }
                local vals  = { 0 }
                local imgs  = { "" }
                for k = 1, perGroup do
                    local it = list[gi * perGroup + k]
                    if it then
                        texts[#texts + 1] = it.name
                        vals[#vals + 1]   = it.id
                        imgs[#imgs + 1]   = GetSkinIcon(it.id)
                    end
                end
                local gid = gi + 1
                local myVals = vals
                st[#st + 1] = {
                    Key = "SZG_" .. cfgKey .. "_" .. gid,
                    UI = SZ_IMG_SWITCHER or AliasMap.Switcher,
                    Text = groupPrefix .. "·Group" .. gid .. "",
                    SwitcherText = texts,
                    SwitcherValue = vals,
                    SwitcherImage = imgs,
                    GetFunc = function()
                        local cur = tonumber(_G.GTLModConfig[cfgKey]) or 0
                        for _, v in ipairs(myVals) do if v == cur then return cur end end
                        return 0
                    end,
                    SetFunc = function(c, v)
                        v = tonumber(v) or 0
                        _G.GTLModConfig[cfgKey] = v
                        if cfgKey == "SkinSuit" then
                            _G.GTLModConfig.CustSuit = v
                        end
                        _G.SaveModSettings()
                        RefreshSiblingRows("SZG_" .. cfgKey .. "_" .. gid, cfgKey == "SkinSuit" and "SZCU_CustSuit" or nil)
                        if _G.SkinZoneApply then _G.SkinZoneApply() end
                        return true
                    end,
                }
            end
            return st
        end

        local function BuildWeaponZoneStack()
            local st = {}
            for _, g in ipairs(_G.SkinZoneGuns) do
                st[#st + 1] = { Key = "SZW_" .. g.key .. "_T", UI = AliasMap.Title, Text = "── " .. g.name .. " ──" }
                local list = {}
                for i, id in ipairs(g.ids) do list[#list + 1] = { id = id, name = g.names[i] } end
                BuildGroupRows(list, "SkinGun_" .. g.key, g.name, st)
            end
            return st
        end

