            local st = { { Key = "SZC_Tip", UI = AliasMap.Title, Text = "── Outfit Sets (One per row, auto-applies) ──" } }
            return BuildGroupRows(_G.SkinZoneSuits, "SkinSuit", "Outfit Sets", st)
