        local function BuildTrailZoneStack()
            local st = { { Key = "SZTR_T", UI = AliasMap.Title, Text = "── Move Trails / Footprints (Auto-applies) ──" } }
            BuildGroupRows(_G.SkinZoneTrails, "SkinTrailID", "Trails & Footprints", st)
            st[#st + 1] = { Key = "SZGL_T", UI = AliasMap.Title, Text = "── Gloves (Auto-applies) ──" }
