            return BuildGroupRows(_G.SkinZonePets, "SkinPetID", "Pets", st)
        end

        local function BuildVehicleZoneStack()
            local st = {}
            for _, v in ipairs(_G.SkinZoneVehicles) do
                st[#st + 1] = { Key = "SZV_" .. v.key .. "_T", UI = AliasMap.Title, Text = "── " .. v.name .. " ──" }
                local list = {}
                for i, id in ipairs(v.ids) do list[#list + 1] = { id = id, name = v.names[i] } end
                BuildGroupRows(list, "SkinVeh_" .. v.key, v.name, st)
            end
            return st
        end

        SettingPageDefine.SkinZone = {
            Key = "SkinZone",
            Text = "❏ Skin Zone",
            UIKey = "Setting_Page_Privacy",
            Category = {
                { Key = "Cat_ZoneCloth",     Text = "Outfit Sets",     Stack = BuildSuitZoneStack() },
                { Key = "Cat_ZoneWeapon",    Text = "Gun Skins",     Stack = BuildWeaponZoneStack() },
                { Key = "Cat_ZoneHelmetBag", Text = "Helmet & Backpack Skins", Stack = BuildHelmetBagZoneStack() },
                { Key = "Cat_ZoneGrenade",   Text = "Grenade Skins",   Stack = BuildGrenadeZoneStack() },
                { Key = "Cat_ZoneVehicle",   Text = "Vehicle Skins",     Stack = BuildVehicleZoneStack() },
            }
        }

        local function BuildCustomZoneStack()
            local st = { { Key = "SZCU_T", UI = AliasMap.Title, Text = "CAN'T USE! WAIT V2 FINAL VERSION...!" } }
            for _, it in ipairs(_G.CustomWearSlots or {}) do
                local cfgKey = it.key
                st[#st + 1] = {
                    Key = "SZCU_" .. cfgKey,
                    UI = AliasMap.OpenWindow,
                    Text = "  └ " .. it.label,
                    GetFunc = function()
                        local cur = tonumber(_G.GTLModConfig[cfgKey]) or 0
                        if cur <= 0 then return "Tap to Enter" end
                        return tostring(cur)
                    end,
                    SetFunc = function()
                        if _G.SZNumInput and _G.SZNumInput.Show then
                            _G.SZNumInput.Show({
                                title = it.label .. " - Enter Skin ID (0=off)",
                                value = tonumber(_G.GTLModConfig[cfgKey]) or 0,
                                min = 0,
                                refreshKey = "SZCU_" .. cfgKey,
                                onConfirm = function(num)
                                    _G.GTLModConfig[cfgKey] = math.floor(tonumber(num) or 0)
                                    _G.SaveModSettings()
                                    if _G.SkinZoneApply then _G.SkinZoneApply() end
                                end,
                            })
                        end
                        return true
                    end,
                }
            end
            return st
        end

        SettingPageDefine.CustomZone = {
            Key = "CustomZone",
            Text = "❏ Custom Zone",
            UIKey = "Setting_Page_Privacy",
            Category = {
                { Key = "Cat_ZoneCustom", Text = "Skin Customization", Stack = BuildCustomZoneStack() },
                { Key = "Cat_ZoneTrail",  Text = "Decoration Zone",   Stack = BuildTrailZoneStack() },
                { Key = "Cat_ZonePet",    Text = "Pet Zone",          Stack = BuildPetZoneStack() },
            }
        }
        for i = #SettingCatalog, 1, -1 do
            local k = SettingCatalog[i] and SettingCatalog[i].Key
            if k == "SkinZone" or k == "CustomZone" then
                table.remove(SettingCatalog, i)
            end
        end
        table.insert(SettingCatalog, 1, SettingPageDefine.ModMenu)
        table.insert(SettingCatalog, 2, SettingPageDefine.SkinZone)
        table.insert(SettingCatalog, 3, SettingPageDefine.CustomZone)
    end

    local UIManager = _G.UIManager
    if UIManager and not UIManager._IsModMenuHooked then
        local old_ShowUI = UIManager.ShowUI
        UIManager.ShowUI = function(config, ...)
            local args = {...}
            local n = select('#', ...)

            if config and config.keyName and (string.find(string.lower(config.keyName), "setting_main") or string.find(string.lower(config.keyName), "setting")) then
                local catalog = args[1]
                if type(catalog) == "table" then
                    for i = #catalog, 1, -1 do
                        if catalog[i] and (catalog[i].Key == "ModMenu" or catalog[i].Key == "SkinZone" or catalog[i].Key == "CustomZone") then
                            table.remove(catalog, i)
                        end
                    end
                    table.insert(catalog, 1, SettingPageDefine.ModMenu)
                    table.insert(catalog, 2, SettingPageDefine.SkinZone)
                    if SettingPageDefine.CustomZone then
                        table.insert(catalog, 3, SettingPageDefine.CustomZone)
                    end
                end
            end
            local table_unpack = table.unpack or unpack
            return old_ShowUI(config, table_unpack(args, 1, n))
        end
        UIManager._IsModMenuHooked = true
    end
end

