                if pm and pc2 then
                    local state = pm.GetState(pc2.ENUM_DownloadType.ODPAK, { itemId })
                    downloaded = (state == pc2.ENUM_DownloadState.Done)
                end
            end)
        end
        if downloaded then
            _G.skinDownloadCache[itemId] = true
        else
