_G.playerAvatarTimerIndex = nil

_G.weaponWatchTimerIndex = TXtime_ticker.AddTimerLoop(0, function()
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc then return end
