_G.CustomWearApply = function()
    local F2 = _G.AddOutfit
    if not F2 then return end
    local cfg = _G.GTLModConfig or {}
    _G.__szCustomWearApplied = _G.__szCustomWearApplied or {}
    local applied = _G.__szCustomWearApplied
    local ent = F2.getEntity and F2.getEntity() or nil
    local inMatch = F2.isInRealMatch and F2.isInRealMatch() or false

    for _, it in ipairs(_G.CustomWearSlots) do
        local res = tonumber(cfg[it.key]) or 0
        local old = tonumber(applied[it.key]) or 0
        if res ~= old and old > 0 then
            pcall(function() if F2.clearEquipCache then F2.clearEquipCache(old) end end)
        end
        applied[it.key] = res > 0 and res or nil
        if res > 0 then
            pcall(F2.ensureSkinDownload, res)
            if not inMatch and ent and ent.bInit and F2.injectOne then
                pcall(function()
                    F2.injectOne(ent, res, F2.szFakeIns and F2.szFakeIns(res) or nil)
                end)
            end
            if it.slot and F2.persistRememberSlot then
                pcall(F2.persistRememberSlot, it.slot, res)
            end
        else
            if it.slot and F2.persistForgetSlot then
                pcall(F2.persistForgetSlot, it.slot)
            end
        end
    end
    if F2.applyPersistSlotsToCache then pcall(F2.applyPersistSlotsToCache) end

    local hair = tonumber(cfg.CustHair) or 0
    if not inMatch then
        if _G.WarehouseCustomInject then pcall(_G.WarehouseCustomInject) end
    else
        local char = F2.getLocalChar and F2.getLocalChar()
        if char then
            if F2.matchApplyAllSlots then pcall(F2.matchApplyAllSlots, char) end
            if hair > 0 and F2.matchApplyWearItem then
                pcall(F2.matchApplyWearItem, char, hair, nil, "Hairstyle")
            end
        end
    end
end

if _G.__szCustomHairLoopVer ~= SZ_SCRIPT_VER then
    _G.__szCustomHairLoopVer = SZ_SCRIPT_VER
    pcall(function()
        local tk = require("common.time_ticker")
        if tk and tk.AddTimerLoop then
            tk.AddTimerLoop(0, function()
                if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
                pcall(function()
                    local hair = tonumber((_G.GTLModConfig or {}).CustHair) or 0
                    if hair <= 0 then return end
                    local F2 = _G.AddOutfit
                    if not F2 then return end
                    if F2.isInRealMatch and F2.isInRealMatch() then
                        local char = F2.getLocalChar and F2.getLocalChar()
                        if char and F2.matchApplyWearItem then
                            pcall(F2.matchApplyWearItem, char, hair, nil, "Hairstyle")
                        end
                    end
                end)
            end, -1, 3.0)
        end
    end)
end

_G.AddOutfitLobbyRestored = false

do
local __szWasInMatch = false
local function AutoRestoreLobbySkin()
    if true then return end
    if _G.AddOutfit and _G.AddOutfit.isInRealMatch and _G.AddOutfit.isInRealMatch() then
        __szWasInMatch = true
        _G.AddOutfitLobbyRestored = false
        return
    end

    pcall(function()
        if GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity() then
            if _G.AddOutfitLobbyRestored and not __szWasInMatch then return end
            if DataMgr and DataMgr.roleData and DataMgr.roleData.uid then
                local LMC = require("client.slua.logic.lobby.Main.Lobby_Main_Control")
                if LMC and LMC.GetCurPage then
                    __szWasInMatch = false
                    _G.AddOutfitLobbyRestored = true
                    pcall(function()
                        if _G.AddOutfit.persistLoadFromDisk then _G.AddOutfit.persistLoadFromDisk() end
                        if _G.AddOutfit.persistApplyLoaded then _G.AddOutfit.persistApplyLoaded() end
                    end)
                    local function reapply()
                        pcall(function()
                            if _G.AddOutfit.reapplyLobbyEquipped then _G.AddOutfit.reapplyLobbyEquipped() end
                            if _G.AddOutfit.injectAll then _G.AddOutfit.injectAll() end
                            if _G.AddOutfit.wearLobbySelectionDirect then pcall(_G.AddOutfit.wearLobbySelectionDirect) end
                            if _G.AddOutfit.forceStandingAvatarWear then pcall(_G.AddOutfit.forceStandingAvatarWear) end
                            if _G.AddOutfit.refreshAllViewsAfterSelection then pcall(_G.AddOutfit.refreshAllViewsAfterSelection) end
                            if _G.AddOutfit.afterInjectApply then pcall(_G.AddOutfit.afterInjectApply, false) end
                        end)
                    end
                    reapply()
                    pcall(function()
                        local tk = require("common.time_ticker")
                        if tk and tk.AddTimerOnce then
                            for _, __d in ipairs({1.5, 3.5, 7.0, 12.0, 20.0}) do tk.AddTimerOnce(__d, reapply) end
                        end
                    end)
                end
            end
        end
    end)
end

pcall(function()
    if _G.__szAutoRestoreStarted == SZ_SCRIPT_VER then return end
    _G.__szAutoRestoreStarted = SZ_SCRIPT_VER
    local ticker = require("common.time_ticker")
    if ticker and ticker.AddTimerLoop then
        ticker.AddTimerLoop(0, function()
            if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
            local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
            if okF and inFight then return end
            pcall(AutoRestoreLobbySkin)
        end, -1, 1.0)
    end
end)
end

pcall(function()
