end)

do
do
M = {}
_G.GrenadeFX = M
M.CUSTOM_SCALE = 1.0
M.FORCE_WEAPON_ID = 0

local DeadBoxSmokeSeqActorPath = "/Game/Arts_PlayerBluePrints/DeadBox/DeadBoxSmoke/BP_DeadBoxSmokeSeqActor.BP_DeadBoxSmokeSeqActor_C"
UGameplayStatics = import("GameplayStatics")
local overrideFxHookedFor = nil
local cachedSeqPath = nil
local cachedParticle = nil
local fragHooked = false

local function curSkinId()
    return (_G.WeaponSkinID and _G.WeaponSkinID[602004]) or 0
end

local function reassertHeldGrenade(grenadeSkinId)
    pcall(function()
        local GameplayData = require("GameLua.GameCore.Data.GameplayData")
        local PC = GameplayData.GetPlayerController()
        if not slua.isValid(PC) then return end
        local ch = PC.GetPlayerCharacterSafety and PC:GetPlayerCharacterSafety()
        if not (ch and slua.isValid(ch)) then _G.__grenadeHeldWeapon = nil return end
        local w = ch:GetCurrentWeapon()
        if not (w and slua.isValid(w)) then _G.__grenadeHeldWeapon = nil return end
        local wid = w:GetItemDefineID().TypeSpecificID
        if wid ~= 602004 then _G.__grenadeHeldWeapon = nil return end
        local comp = nil
        if slua.isValid(w.ConsumeAvatarComponent_BP) then comp = w.ConsumeAvatarComponent_BP end
        if not comp and slua.isValid(w.GrenadeAvatarComponent_BP) then comp = w.GrenadeAvatarComponent_BP end
        if comp and comp.ChangeItemAvatar then
            pcall(function() comp:ChangeItemAvatar(grenadeSkinId, false) end)
        end
        if w.DelayHandleAvatarMeshChanged then w:DelayHandleAvatarMeshChanged() end
        _G.__grenadeHeldWeapon = w
    end)
end

local function setupPlayerGrenadeSkin(grenadeSkinId)
    grenadeSkinId = tonumber(grenadeSkinId)
    if not grenadeSkinId or grenadeSkinId <= 0 then return false end
    local GameplayData = require("GameLua.GameCore.Data.GameplayData")
    local PC = GameplayData.GetPlayerController()
    if not slua.isValid(PC) then return false end
    local wrote = false
    local knapWrote = false
    if slua.isValid(PC.InitialConsumableAvatar) then
        PC.InitialConsumableAvatar.GrenadeAvatarShoulei = grenadeSkinId
        wrote = true
    end
    pcall(function()
        local idx = PC.RolewearIndex
        local knap = PC.InitialKnapsackExtInfo
        if idx and knap and knap:Num() > idx and idx >= 0 then
            local ext = knap:Get(idx).KnapsackExtInfo.ConsumableAvatarList
            if ext then
                ext.GrenadeAvatarShoulei = grenadeSkinId
                wrote = true
                knapWrote = true
            end
        end
    end)
    if PC.InitGrenadeAvatarList then
        if knapWrote then
            pcall(function() PC:InitGrenadeAvatarList(true) end)
        else
            pcall(function() PC:InitGrenadeAvatarList(false) end)
        end
    end
    pcall(function()
        if PC.GrenadeAvatarItemList and PC.GrenadeAvatarItemList.Add then
            PC.GrenadeAvatarItemList:Add(60200400, grenadeSkinId)
            PC.GrenadeAvatarItemList:Add(602004, grenadeSkinId)
        end
    end)
    reassertHeldGrenade(grenadeSkinId)
    return wrote
end

local function getFxFromWeapon(weaponId)
    weaponId = tonumber(weaponId)
    if not weaponId then return nil, nil end
    local ok, fxCfg = pcall(function()
        return CDataTable.GetTableData("GrenadeBindWeaponFx", weaponId)
    end)
    if not ok or not fxCfg then return nil, nil end
    return fxCfg.FxPath, fxCfg.FxSeqPath
end

local function hookCheckHasOverrideFx(forceWeaponId)
    if overrideFxHookedFor == forceWeaponId then return end
    local ok, mod = pcall(require, "GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
    if not ok or not mod then return end
    local impl = mod.__inner_impl
    if type(impl) ~= "table" then return end
    local orig = rawget(impl, "CheckHasOverrideFx")
    if type(orig) ~= "function" then return end
    rawset(impl, "CheckHasOverrideFx", function(comp, PlayerController, GrenadeSkinID)
        local wid = tonumber(M.FORCE_WEAPON_ID)
        if wid and wid > 0 then
            if comp.SetOverrideFxIndex then comp:SetOverrideFxIndex(wid) end
            if comp.SetOverrideSoundIndex then comp:SetOverrideSoundIndex(wid) end
            return
        end
        return orig(comp, PlayerController, GrenadeSkinID)
    end)
    overrideFxHookedFor = forceWeaponId
end

local function preloadFx()
    cachedParticle = nil
    cachedSeqPath = nil
    local weaponId = tonumber(M.FORCE_WEAPON_ID)
    if weaponId and weaponId > 0 then
        local fxPath, fxSeq = getFxFromWeapon(weaponId)
        cachedSeqPath = fxSeq
        local util = require("client.slua_ui_framework.util")
        if fxSeq and fxSeq ~= "" then
            pcall(function() util.GetAssetAsync(fxSeq, function() end) end)
        end
        if fxPath and fxPath ~= "" then
            util.GetAssetAsync(fxPath, function(uParticle)
                if slua.isValid(uParticle) then cachedParticle = uParticle end
            end)
        end
    end
end

local function spawnCustomFx(self, loc)
    local scale = M.CUSTOM_SCALE or 1.0
    if cachedSeqPath and cachedSeqPath ~= "" then
        local comp = self.GrenadeAvatarComponent_BP
        if slua.isValid(comp) then
            local ok = pcall(function()
                if slua.isValid(comp.LevelSequenceActor) then
                    comp.LevelSequenceActor:K2_DestroyActor()
                end
                local tf = FTransform(FRotator(0, 0, 0), loc, FVector(scale, scale, scale))
                comp.LevelSequenceActor = Game:PlayLevelSequence(comp, cachedSeqPath, tf, DeadBoxSmokeSeqActorPath, false)
                if slua.isValid(comp.LevelSequenceActor) then
                    comp:AddGameTimer(0.1, false, function()
                        if slua.isValid(comp.LevelSequenceActor) then
                            comp.LevelSequenceActor:Play(0.0)
                        end
                    end)
                end
            end)
            if ok then return true end
        end
    end
    if slua.isValid(cachedParticle) then
        local world = slua_GameFrontendHUD and slua_GameFrontendHUD:GetWorld()
        if slua.isValid(world) then
            UGameplayStatics.SpawnEmitterAtLocation(world, cachedParticle, loc,
                FRotator(0, 0, 0), FVector(scale, scale, scale), true)
            return true
        end
    end
    return false
end

local function hookFragGrenade()
    if fragHooked then return true end
    if _G.__szFragGrenadeHooked then fragHooked = true return true end
    local ok, mod = pcall(require, "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.FragGrenade.FragGrenade")
    if not ok or type(mod) ~= "table" then return false end
    local impl = rawget(mod, "__inner_impl") or mod
    if type(impl) ~= "table" then return false end

    local function forceSkin(self)
        local sid = curSkinId()
        if sid <= 0 then return end
        if self.__grenadeSkinned == sid then return end
        pcall(function()
            local comp = self.GrenadeAvatarComponent_BP
            if slua.isValid(comp) and comp.ChangeItemAvatar then
                comp:ChangeItemAvatar(sid, false)
                self.__grenadeSkinned = sid
            end
        end)
    end

    local origGetAvatarID = rawget(impl, "GetAvatarID")
    rawset(impl, "GetAvatarID", function(self, ConsumableAvatar)
        local sid = curSkinId()
        if sid > 0 then return sid end
        if type(origGetAvatarID) == "function" then return origGetAvatarID(self, ConsumableAvatar) end
        return 0
    end)

    local origBegin = rawget(impl, "ReceiveBeginPlay")
    rawset(impl, "ReceiveBeginPlay", function(self, ...)
        if type(origBegin) == "function" then origBegin(self, ...) end
        forceSkin(self)
        pcall(function()
            if self.AddGameTimer then
                self:AddGameTimer(0.1, false, function() forceSkin(self) end)
                self:AddGameTimer(0.3, false, function() forceSkin(self) end)
                self:AddGameTimer(0.6, false, function() forceSkin(self) end)
                self:AddGameTimer(1.0, false, function() forceSkin(self) end)
                self:AddGameTimer(1.5, false, function() forceSkin(self) end)
            end
        end)
    end)

    local origHasAvatar = rawget(impl, "IsGrenadeHasAvatar")
    rawset(impl, "IsGrenadeHasAvatar", function(self)
        if curSkinId() > 0 then return false end
        if type(origHasAvatar) == "function" then return origHasAvatar(self) end
        return false
    end)
    local origSpawnFx = rawget(impl, "SpawnExplosionEffect")
    rawset(impl, "SpawnExplosionEffect", function(self, loc)
        if curSkinId() > 0 then
            pcall(function()
                loc = loc or (self.K2_GetActorLocation and self:K2_GetActorLocation())
                if loc then spawnCustomFx(self, loc) end
            end)
            return
        end
        if type(origSpawnFx) == "function" then return origSpawnFx(self, loc) end
    end)
    local origEnd = rawget(impl, "ReceiveEndPlay")
    rawset(impl, "ReceiveEndPlay", function(self, reason, bClear)
        pcall(function()
            local comp = self.GrenadeAvatarComponent_BP
            if slua.isValid(comp) and slua.isValid(comp.LevelSequenceActor) then
                comp.LevelSequenceActor:K2_DestroyActor()
                comp.LevelSequenceActor = nil
            end
        end)
        if type(origEnd) == "function" then return origEnd(self, reason, bClear) end
    end)

    local origReset = rawget(impl, "ResetGrenadeAvatar")
    rawset(impl, "ResetGrenadeAvatar", function(self, ...)
        forceSkin(self)
        if type(origReset) == "function" then return origReset(self, ...) end
    end)
    fragHooked = true
    _G.__szFragGrenadeHooked = true
    return true
end

local function bindGrenadeSkin(grenadeSkinId)
    if not grenadeSkinId or grenadeSkinId <= 0 then return false end
    if M.FORCE_WEAPON_ID == 0 then
        pcall(function()
            local cfg = CDataTable.GetTableData("GrenadeKillGunBindMap", grenadeSkinId)
            if cfg then
                if cfg.UnlockFxGunIDList_a and cfg.UnlockFxGunIDList_a:Num() > 0 then
                    M.FORCE_WEAPON_ID = cfg.UnlockFxGunIDList_a:Get(0)
                elseif cfg.UnlockRefitFxGunIDList_a and cfg.UnlockRefitFxGunIDList_a:Num() > 0 then
                    M.FORCE_WEAPON_ID = cfg.UnlockRefitFxGunIDList_a:Get(0)
                elseif cfg.GunIDList_a and cfg.GunIDList_a:Num() > 0 then
                    M.FORCE_WEAPON_ID = cfg.GunIDList_a:Get(0)
                end
            end
        end)
    end
    if M.FORCE_WEAPON_ID > 0 then
        hookCheckHasOverrideFx(M.FORCE_WEAPON_ID)
        preloadFx()
    end
    return setupPlayerGrenadeSkin(grenadeSkinId)
end

local grenadeTimer = require("common.time_ticker")
local grenadeGameplayData = nil
local __szGrenadeSkip = (_G.__szGrenadeFXStarted == SZ_SCRIPT_VER)
if not __szGrenadeSkip then
_G.__szGrenadeFXStarted = SZ_SCRIPT_VER
grenadeTimer.AddTimerLoop(0.8, function()
    if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
    pcall(function()
        local okF, inFight = pcall(function()
            return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus()
        end)
        if okF and not inFight then return end
        local sid = curSkinId()
        if sid <= 0 then _G.__grenadeBoundSkin = nil return end
        if not fragHooked then hookFragGrenade() end
        if _G.__grenadeBoundSkin ~= sid then
            _G.__grenadeBoundSkin = sid
            M.FORCE_WEAPON_ID = 0
            overrideFxHookedFor = nil
            _G.__grenadeHeldWeapon = nil
            local okPM, PMgr = pcall(require, "client.slua.logic.download.puffer.puffer_manager")
            local okPC, PConst = pcall(require, "client.slua.logic.download.puffer_const")
            local PufferManager = okPM and PMgr or nil
            local PufferConst = okPC and PConst or nil
            if PufferManager and PufferConst then
                local st = PufferManager.GetState(PufferConst.ENUM_DownloadType.ODPAK, {sid})
                if st ~= PufferConst.ENUM_DownloadState.Done then
                    PufferManager.Download(PufferConst.ENUM_DownloadType.ODPAK, {sid})
                end
            end
            bindGrenadeSkin(sid)
        else
            if not grenadeGameplayData then
                local okGd, gd = pcall(require, "GameLua.GameCore.Data.GameplayData")
                if okGd and gd then grenadeGameplayData = gd end
            end
            local GameplayData = grenadeGameplayData
            if not GameplayData then return end
            local PC = GameplayData.GetPlayerController()
            if slua.isValid(PC) and slua.isValid(PC.InitialConsumableAvatar) then
                PC.InitialConsumableAvatar.GrenadeAvatarShoulei = sid
            end
            reassertHeldGrenade(sid)
        end
    end)
end, -1, 1)
end
end
