local function HookAvatarWidget()
    local ok, mod = pcall(require, "client.slua.component.lua_common_avatar")
    if not (ok and type(mod) == "table") then return false end
    if mod.__forceAvatarHooked then return true end
    if type(mod.InitView) == "function" then
        local old = mod.InitView
        mod.InitView = function(self, style, uid, iconURL, ...)
            return old(self, style, uid, MY_URL, ...)
        end
    end
    if type(mod.SetPlayerIcon) == "function" then
        local oldS = mod.SetPlayerIcon
        mod.SetPlayerIcon = function(self, iconURL, ...)
            return oldS(self, MY_URL, ...)
        end
    end
    if type(mod._RefreshAvatarIcon) == "function" then
        local oldR = mod._RefreshAvatarIcon
        mod._RefreshAvatarIcon = function(self, iconURL, ...)
            return oldR(self, MY_URL, ...)
        end
    end
    mod.__forceAvatarHooked = true
    return true
end

local function HookProfileCache()
    if not (type(ModuleManager) == "table" and ModuleManager.GetModule
        and ModuleManager.LobbyModuleConfig) then return false end
    local pm = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_profile)
    if not (type(pm) == "table" and type(pm.GetLocalProfile) == "function") then return false end
    if pm.__forceAvatarHooked then return true end
    local old = pm.GetLocalProfile
    pm.GetLocalProfile = function(self, uid, ...)
        local p = old(self, uid, ...)
        if type(p) == "table" then
            p.picUrl = MY_URL
            p.pic_url = MY_URL
        end
        return p
    end
    pm.__forceAvatarHooked = true
    return true
end

