        if type(ModuleManager) == "table" and ModuleManager.GetModule
            and ModuleManager.CommonModuleConfig then
            local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.image_download_mgr)
            if mgr and mgr.DownloadImageByHttpWrapper then
                mgr:DownloadImageByHttpWrapper(MY_URL, function() end, function() end, {
                    enableCDNCompress = false,
                    isSyncDiskLoad = true,
                    bIsIgnoreCheck = true,
                })
            end
        end
    end)
end

pcall(HookAvatarWidget)
