do
    local function applyAvatar()
        if not (DataMgr and DataMgr.roleData) then return end
        local rd = DataMgr.roleData
        local changed = false

        if AVATAR_FRAME_ID > 0 then
            local cur = tonumber(rd.cur_avatar_box_id) or 0
            if cur ~= AVATAR_FRAME_ID then
                local ok = pcall(function() DataMgr.UpdateAvatarBoxId(AVATAR_FRAME_ID) end)
                if not ok then pcall(function() rd.cur_avatar_box_id = AVATAR_FRAME_ID end) end
                changed = true
            end
            pcall(function()
                local af = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
                if af then
                    af.AvatarFrameList = af.AvatarFrameList or {}
                    af.AvatarFrameList[AVATAR_FRAME_ID] = af.AvatarFrameList[AVATAR_FRAME_ID] or { expire_time = 1 }
                    af.AvatarFrameList[AVATAR_FRAME_ID].expire_time = 1
                    af.HasGet = true
                    af._hasGotData = true
                end
            end)
        end

        if AVATAR_ID > 0 then
            local want = tostring(AVATAR_ID)
            if tostring(rd.headIconUrl) ~= want then
                local ok = pcall(function() DataMgr.UpdateHeadIconUrl(want) end)
                if not ok then pcall(function() rd.headIconUrl = want end) end
                changed = true
                pcall(function()
                    local big = require("client.slua.logic.roleInfo.logic_roleInfo_BigAvatar")
                    if big and big.RefreshBigImage then big.RefreshBigImage(want) end
                end)
            end
            pcall(function()
                local av = require("client.slua.logic.roleInfo.logic_roleInfo_Avatar")
                if av then
                    av.HeadportraitList = av.HeadportraitList or {}
                    if av.HeadportraitList[want] == nil then
                        av.HeadportraitList[want] = 1
                    end
                end
            end)
        end

        if changed then
            pcall(function()
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_HEAD_INFO, DataMgr.roleData.headIconUrl)
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_USE_AVATAR)
                EventSystem:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
                EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_LOBBY_SOCIAL_UPDATE_HEAD_ICON)
            end)
        end
    end

    local ticker = getTicker()
    if not (ticker and ticker.AddTimerLoop) then
        pcall(function() ticker = require("common.time_ticker") end)
    end
    if ticker and ticker.AddTimerLoop then
        pcall(applyAvatar)
        ticker.AddTimerLoop(0.5, function()
            if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
            local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
            if okF and inFight then return end
            pcall(applyAvatar)
        end, -1, 1)
    end
end

end
end

if _G.__VEHICLE_VOICE_LOADED__ ~= SZ_SCRIPT_VER then
    _G.__VEHICLE_VOICE_LOADED__ = SZ_SCRIPT_VER

    local VehicleVoice = {}

    VehicleVoice.COOLDOWN = 5
    VehicleVoice.READ_DELAY = 0.6

    VehicleVoice.ENABLED = true
    VehicleVoice.SHOW_TEXT = true
    VehicleVoice.PLAY_SOUND = true
    VehicleVoice.DEBUG = (_G.VehicleVoiceDebug == true)
    VehicleVoice.DIAG_POPUP = true
    VehicleVoice.AUTO_INSTALL = true

    VehicleVoice._inVehicle = false
    VehicleVoice._lastVehicle = nil
    VehicleVoice._lastPlayTime = 0
    VehicleVoice._unlockHooked = false

    _G.VehicleVoiceOverride = _G.VehicleVoiceOverride or {}

    local PLATE_UTIL_MODULE = "GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil"

    local function log(msg)
        if VehicleVoice.DEBUG then
            print("[VehicleVoice] " .. tostring(msg))
        end
    end

    local function safeRequire(path)
        local ok, mod = pcall(require, path)
        if ok then return mod end
        return nil
    end

    local function showVoiceDiag(lines)
        if not VehicleVoice.DIAG_POPUP then return end
        pcall(function()
            local CommonMsgBoxMgr = require("client.slua.logic.common.logic_common_msg_box")
            CommonMsgBoxMgr.Show(2, "Vehicle Voice Diagnosis", table.concat(lines, "\n"), nil, nil, "OK")
        end)
    end

    local function wrapPlateUtil(mod)
        if not mod or mod.__vehicleVoiceHooked then return end
        if type(mod.CheckHasUnLockFeature) ~= "function" then return end
        mod.__vehicleVoiceHooked = true
        local orig = mod.CheckHasUnLockFeature
        mod.CheckHasUnLockFeature = function(featureType, uid, avatarID, ...)
            if mod.ENUM_VehicleFeatureType and featureType == mod.ENUM_VehicleFeatureType.VOICE then
                return true
            end
            return orig(featureType, uid, avatarID, ...)
        end
        VehicleVoice._unlockHooked = true
        log("CheckHasUnLockFeature hooked (VOICE bypass)")
    end

    function VehicleVoice.InstallUnlockHook()
        local mod = package.loaded[PLATE_UTIL_MODULE]
        if mod then
            wrapPlateUtil(mod)
        elseif package and package.preload and not package.preload[PLATE_UTIL_MODULE] then
            package.preload[PLATE_UTIL_MODULE] = function()
                package.preload[PLATE_UTIL_MODULE] = nil
                local m = require(PLATE_UTIL_MODULE)
                wrapPlateUtil(m)
                return m
            end
        end
    end

    function VehicleVoice.GetVoiceCfg(avatarID)
        avatarID = tonumber(avatarID) or 0
        if avatarID <= 0 then return nil end
        local ov = _G.VehicleVoiceOverride[avatarID]
        if ov and ov.voice then
            return {
                DriverVoiceID = ov.voice,
                DriverVoiceText = ov.text or "",
                PassengerVoiceID = ov.passengerVoice or ov.voice,
                PassengerVoiceText = ov.passengerText or ov.text or "",
            }
        end
        local Util = safeRequire(PLATE_UTIL_MODULE)
        if Util and type(Util.GetCollectCarFeatureCfg) == "function" then
            local ok, cfg = pcall(Util.GetCollectCarFeatureCfg, avatarID)
            if ok and cfg then return cfg end
        end
        if type(_G.GetCollectCarFeatureCfg) == "function" then
            local ok2, cfg2 = pcall(_G.GetCollectCarFeatureCfg, avatarID)
            if ok2 and cfg2 then return cfg2 end
        end
        return nil
    end

    function VehicleVoice.PlayVoice(vehicle, avatarID, isDriver)
        local cfg = VehicleVoice.GetVoiceCfg(avatarID)
        if not cfg then
            return false, "Voice config=none (No official vehicle voice for this skin)"
        end
        local voiceID = isDriver and (cfg.DriverVoiceID or 0) or (cfg.PassengerVoiceID or 0)
        local text = isDriver and (cfg.DriverVoiceText or "") or (cfg.PassengerVoiceText or "")
        log("skin=" .. tostring(avatarID) .. " isDriver=" .. tostring(isDriver) .. " voiceID=" .. tostring(voiceID) .. " text=" .. tostring(text))
        if (not voiceID or voiceID == 0) and (not text or text == "") then
            return false, "Voice config=empty (voiceID=0, text=empty)"
        end
        local played = false
        if VehicleVoice.SHOW_TEXT and text and text ~= "" then
            local okText, errText = pcall(function()
                local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
                local Msg = "<ChatSelfName>Me" .. LocUtil.GetLocalizeResStr(4164) .. "</>" .. text
                InGameUITools.DisplayMessageInGame(Msg)
            end)
            played = played or okText
            if not okText then log("text fail: " .. tostring(errText)) end
        end
        if VehicleVoice.PLAY_SOUND and voiceID and voiceID ~= 0 then
            local okSnd, errSnd = pcall(function()
                local ActorVoiceSystem = require("client.slua.logic.actor_voice.logic_actor_voice")
                ActorVoiceSystem.PlayMultiLanguageSound(voiceID, vehicle, true)
            end)
            played = played or okSnd
            if not okSnd then
                log("sound fail: " .. tostring(errSnd))
                return played, "Voice config=present voiceID=" .. tostring(voiceID) .. " but sound playback API failed"
            end
        end
        return played, "Voice config=present voiceID=" .. tostring(voiceID) .. " Play=" .. (played and "Success" or "Failed")
    end

    function VehicleVoice.GetCurrentAvatarID(vehicle)
        local avatarID = 0
        pcall(function()
            local AvatarComp = vehicle.VehicleAvatarComponent_BP
            if slua.isValid(AvatarComp) and AvatarComp.GetCurrentAvatarID then
                avatarID = AvatarComp:GetCurrentAvatarID() or 0
            end
        end)
        if avatarID == 0 then
            pcall(function()
                avatarID = vehicle.ClientUsedAvatarID or 0
            end)
        end
        if avatarID == 0 then
            avatarID = tonumber(_G.CurrentEquipVehicleID) or 0
        end
        if avatarID == 0 and _G.VEHSEL and _G.VEHSEL.byShape then
            pcall(function()
                local UAvatarUtils = import("AvatarUtils")
                local defId = 0
                local av = vehicle.VehicleAvatarComponent_BP
                if slua.isValid(av) and av.GetDefaultAvatarID then defId = tonumber(av:GetDefaultAvatarID()) or 0 end
                if defId > 0 and UAvatarUtils and UAvatarUtils.GetVehicleShapeBySkinID then
                    local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defId))
                    if shape and shape >= 0 and _G.VEHSEL.byShape[shape] then
                        avatarID = tonumber(_G.VEHSEL.byShape[shape]) or 0
                    end
                end
            end)
        end
        if avatarID == 0 and _G.VEHSEL and tonumber(_G.VEHSEL.override) then
            avatarID = tonumber(_G.VEHSEL.override) or 0
        end
        if avatarID == 0 then
            pcall(function()
                local av = vehicle.VehicleAvatarComponent_BP
                if slua.isValid(av) and av.GetDefaultAvatarID then
                    avatarID = tonumber(av:GetDefaultAvatarID()) or 0
                end
            end)
        end
        return avatarID
    end

    function VehicleVoice.OnEnterVehicle(vehicle, uCharacter)
        local now = os.clock and os.clock() or 0
        if now - VehicleVoice._lastPlayTime < VehicleVoice.COOLDOWN then
            log("in cooldown")
            return
        end
        VehicleVoice._lastPlayTime = now

        local isDriver = true
        pcall(function()
            if vehicle.GetDriver then
                isDriver = (vehicle:GetDriver() == uCharacter) and true or false
            end
        end)

        local function doPlay()
            if not slua.isValid(vehicle) then return end
            local avatarID = VehicleVoice.GetCurrentAvatarID(vehicle)
            if avatarID <= 0 then
                showVoiceDiag({ "Vehicle enter detected=Y", "Skin ID=0 (Vehicle skin not found)", "Play=Skipped" })
                return
            end
            local played, stageMsg = VehicleVoice.PlayVoice(vehicle, avatarID, isDriver)
            if not played then
                local defId = 0
                pcall(function()
                    local av = vehicle.VehicleAvatarComponent_BP
                    if slua.isValid(av) and av.GetDefaultAvatarID then defId = tonumber(av:GetDefaultAvatarID()) or 0 end
                end)
                if defId > 0 and defId ~= avatarID then
                    local played2, stageMsg2 = VehicleVoice.PlayVoice(vehicle, defId, isDriver)
                    if played2 then
                        showVoiceDiag({ "Vehicle enter detected=Y", "Skin ID=" .. tostring(avatarID), stageMsg, "Fallback default vehicle skin=" .. tostring(defId), stageMsg2 })
                        return
                    end
                end
            end
            showVoiceDiag({ "Vehicle enter detected=Y", "Skin ID=" .. tostring(avatarID) .. (isDriver and "(Driver)" or "(Passenger)"), stageMsg })
        end

        if _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimer then
            _G.Mytimer_ticker.AddTimer(VehicleVoice.READ_DELAY, function()
                pcall(doPlay)
            end)
        else
            pcall(doPlay)
        end
    end

    function VehicleVoice.Tick()
        if not VehicleVoice.ENABLED then return end
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc or not slua.isValid(pc) then return end
        local uCharacter = pc:GetPlayerCharacterSafety()
        if not uCharacter or not slua.isValid(uCharacter) then
            VehicleVoice._inVehicle = false
            VehicleVoice._lastVehicle = nil
            return
        end
        local veh = uCharacter.CurrentVehicle
        if not slua.isValid(veh) then
            VehicleVoice._inVehicle = false
            VehicleVoice._lastVehicle = nil
            return
        end
        if not VehicleVoice._inVehicle or veh ~= VehicleVoice._lastVehicle then
            VehicleVoice._inVehicle = true
            VehicleVoice._lastVehicle = veh
            log("enter vehicle detected")
            VehicleVoice.OnEnterVehicle(veh, uCharacter)
        end
    end

    function VehicleVoice.Install()
        VehicleVoice.InstallUnlockHook()
        if _G.Mytimer_ticker then
            if _G.__loopGuardVehicleVoice and _G.Mytimer_ticker.IsRunning and _G.Mytimer_ticker.IsRunning(_G.__loopGuardVehicleVoice) then
                _G.Mytimer_ticker.RemoveTimer(_G.__loopGuardVehicleVoice)
            end
            _G.__loopGuardVehicleVoice = _G.Mytimer_ticker.AddTimerLoop(0.5, function()
                if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
                pcall(function()
                    if not VehicleVoice._unlockHooked then
                        VehicleVoice.InstallUnlockHook()
                    end
                    VehicleVoice.Tick()
                end)
            end, -1, 1)
            log("Install done")
        else
            log("Mytimer_ticker not found, tick loop not installed")
        end
        return true
    end

    if VehicleVoice.AUTO_INSTALL then
        pcall(function() VehicleVoice.Install() end)
    end

    _G.VehicleVoice = VehicleVoice
    _G.TestVehicleVoice = function()
        pcall(function()
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            local uCharacter = pc and pc:GetPlayerCharacterSafety()
            local veh = uCharacter and uCharacter.CurrentVehicle
            if slua.isValid(veh) then
                VehicleVoice._lastPlayTime = 0
                VehicleVoice.OnEnterVehicle(veh, uCharacter)
            else
                log("not in vehicle")
            end
        end)
    end

    log("vehicle voice module loaded")
end

do
    if not _G.GoldenLeavesTrail or _G.__szTrailVer ~= SZ_SCRIPT_VER then
        _G.__szTrailVer = SZ_SCRIPT_VER
        local Trail = {}
        Trail.Enabled = false
        Trail.TRAIL_ITEM_ID = 4531002
        Trail._appliedChar = nil

        local function getTrailChar()
            local ok, ch = pcall(function()
                local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                if not pc then return nil end
                if pc.GetPlayerCharacterSafety then return pc:GetPlayerCharacterSafety() end
                return pc:K2_GetPawn()
            end)
            if ok and ch and slua.isValid(ch) then return ch end
            return nil
        end

        local function applyToChar(ch, itemId, force)
            pcall(function()
                local comp = ch.CharacterAvatarComp2_BP
                if not comp or not slua.isValid(comp) then return end
                local isFoot = itemId >= 4541000 and itemId < 4542000
                local field = isFoot and "FootStepEffectItem" or "MoveEffectItem"
                local repFn = isFoot and "OnRep_FootStepEffectItem" or "OnRep_MoveEffectItem"
                local setFn = isFoot and "SetFootStepEffectItem" or "SetMoveEffectItem"
                if (not force) and (comp[field] or 0) == itemId then return end
                comp[field] = itemId
                if comp[repFn] then
                    pcall(function() comp[repFn](comp, 0) end)
                end
                if comp.AdditionEffectMgr and comp.AdditionEffectMgr[setFn] then
                    pcall(function() comp.AdditionEffectMgr[setFn](comp.AdditionEffectMgr, itemId) end)
                end
            end)
        end

        function Trail.Apply()
            pcall(function()
                local ch = getTrailChar()
                if not ch then return end
                applyToChar(ch, Trail.TRAIL_ITEM_ID, true)
                Trail._appliedChar = ch
            end)
        end

        function Trail.Stop()
            pcall(function()
                local ch = Trail._appliedChar
                if ch and slua.isValid(ch) then applyToChar(ch, 0, true) end
                Trail._appliedChar = nil
            end)
        end

        pcall(function()
            local tt = _G.Mytimer_ticker or require("common.time_ticker")
            if tt and tt.AddTimerLoop then
                if _G.__trailLoopGuard and tt.IsRunning and tt.IsRunning(_G.__trailLoopGuard) then
                    tt.RemoveTimer(_G.__trailLoopGuard)
                end
                local __trailTick = 0
                _G.__trailLoopGuard = tt.AddTimerLoop(3, function()
                    if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
                    if not Trail.Enabled then return end
                    pcall(function()
                        local ch = getTrailChar()
                        if not ch then Trail._appliedChar = nil return end
                        __trailTick = __trailTick + 1
                        local force = false
                        if ch ~= Trail._appliedChar then
                            Trail._appliedChar = ch
                            force = true
                        elseif __trailTick % 8 == 1 then
                            force = true
                        end
                        applyToChar(ch, Trail.TRAIL_ITEM_ID, force)
                    end)
                end, -1, 1)
            end
        end)

        _G.GoldenLeavesTrail = Trail
    end
end

pcall(function()
    local ticker2 = require("common.time_ticker")
    if ticker2 and ticker2.AddTimerOnce then
        ticker2.AddTimerOnce(3.0, function() if _G.SkinZoneApply then pcall(_G.SkinZoneApply) end end)
    end
end)

do
local function decodeExpand(expandContent)
    local ok, exp = pcall(function() return slua.LuaArchiverDecode(LuaStateWrapper, expandContent) or {} end)
    return ok and exp or {}
end

local function encodeExpand(exp)
    return slua.LuaArchiverEncode(LuaStateWrapper, exp or {})
end

local _cachedMyName = nil
local function isMyKill(data)
    if not data then return false end
    if data.bIamCauser then return true end
    if not _cachedMyName then
        local hud = slua_GameFrontendHUD
        if hud then
            local pc = hud:GetPlayerController()
            if slua.isValid(pc) then
                local ch = pc:GetPlayerCharacterSafety()
                if slua.isValid(ch) then _cachedMyName = ch:GetPlayerNameSafety() end
            end
        end
    end
    if not _cachedMyName or _cachedMyName == "" then return false end
    return data.Causer == _cachedMyName or data.CauserRealPlayerName == _cachedMyName or data.CauserPlayerName == _cachedMyName
end

local function getCurrentWeaponSkinID()
    local hud = slua_GameFrontendHUD
    if not hud then return 0 end
    local pc = hud:GetPlayerController()
    if not slua.isValid(pc) then return 0 end
    local ch = pc:GetPlayerCharacterSafety()
    if not slua.isValid(ch) then return 0 end

    local currWeapon = ch:GetCurrentWeapon()
    if slua.isValid(currWeapon) and currWeapon.synData then
        local currentSkinID = 0
        pcall(function()
            local synDataRef = slua.IndexReference(currWeapon.synData:Get(7), "defineID")
            local skinID = synDataRef and slua.isValid(synDataRef) and synDataRef.TypeSpecificID or 0
            if skinID > 1000000 then
                currentSkinID = skinID
            end
        end)
        return currentSkinID
    end
    return 0
end

local _downloadedAssetsCache = {}
function downloadTeamAssets(skinID)
    if not skinID or skinID == 0 or skinID == 69 then return end
    if _downloadedAssetsCache[skinID] then return end
    _downloadedAssetsCache[skinID] = true

    pcall(function()
        local PufferManager = require("client.slua.logic.download.puffer.puffer_manager")
        local PufferConst = require("client.slua.logic.download.puffer_const")
        PufferManager.Download(PufferConst.ENUM_DownloadType.ODPAK, {skinID})

        local cfg = CDataTable.GetTableData("TeamKillBroadcast", skinID)
        if cfg then
            if cfg.EffectPath and cfg.EffectPath ~= "" then
                PufferManager.Download(PufferConst.ENUM_DownloadType.ODPAK, {cfg.EffectPath})
            end
            if cfg.BgPath and cfg.BgPath ~= "" then
                PufferManager.Download(PufferConst.ENUM_DownloadType.ODPAK, {cfg.BgPath})
            end
        end
    end)
end

local function patchTeamKill(messageData)
    if not _G.GTLModConfig.KillMessage then return messageData end
    if not messageData or not isMyKill(messageData) then return messageData end
    local currentSkinID = getCurrentWeaponSkinID()
    if not currentSkinID or currentSkinID == 0 or currentSkinID == 69 then return messageData end
    local broadcastCfg = CDataTable.GetTableData("TeamKillBroadcast", currentSkinID)
    if not broadcastCfg or (not broadcastCfg.BgPath and not broadcastCfg.EffectPath) then return messageData end
    pcall(function()
        local exp = decodeExpand(messageData.ExpandDataContent)
        exp.CauserWeaponAvatarID = currentSkinID
        messageData.ExpandDataContent = encodeExpand(exp)
        messageData.bShowBottomBothSidesKillInfo = true
        messageData.bIamCauser = true
        downloadTeamAssets(currentSkinID)
    end)
    return messageData
end

local function installTeamBroadcastHooks()
    local function wrapCopy(mod, tag)
        if not mod then return end
        local impl2 = mod.__inner_impl or mod
        if not impl2 or not impl2.CopyKillOrPutDownMessageDataUserDataToLuaTable then return end
        local key = "__teamKillCopy_" .. tag
        if not impl2[key] then impl2[key] = impl2.CopyKillOrPutDownMessageDataUserDataToLuaTable end
        local O_Copy = impl2[key]
        impl2.CopyKillOrPutDownMessageDataUserDataToLuaTable = function(self, messageData)
            local copied = O_Copy(self, messageData)
            if not _G.GTLModConfig.KillMessage then return copied end
            local ok2, result = pcall(function() return patchTeamKill(copied) end)
            if ok2 then return result end
            return copied
        end
    end
    pcall(function() wrapCopy(require("GameLua.Mod.BaseMod.Client.BattleKillBroadcast.BattleKillBroadcastSubSystem"), "base") end)
    pcall(function() wrapCopy(require("GameLua.Mod.SingleTraining.Client.BattleKillBroadcast.BattleKillBroadcastSubSystem"), "training") end)
end

