do
pcall(function()
if _G.__szBadgeGoldVer == SZ_SCRIPT_VER then return end
_G.__szBadgeGoldVer = SZ_SCRIPT_VER

local FAKE_LEVEL_BG = 100

function isSelfUid(uid)
    local u = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
    if not u then
        local ok, ret = pcall(function()
            if TeamUpNewSystem and TeamUpNewSystem.GetSelfUID then
                return tonumber(TeamUpNewSystem.GetSelfUID())
            end
        end)
        if ok then u = ret end
    end
    return u and tostring(uid) == tostring(u)
end

local function installWithRetry(tag, installFn)
    local installed = false
    local function try()
        if installed then return true end
        if _G.__szScriptVer ~= SZ_SCRIPT_VER then return true end
        local ok, ret = pcall(installFn)
        if ok and ret then installed = true end
        return installed
    end
    if not try() then
        local ticker = _G.Mytimer_ticker or _G.timer_ticker
        if not (ticker and ticker.AddTimerLoop) then
            pcall(function() ticker = require("common.time_ticker") end)
        end
        if ticker and ticker.AddTimerLoop then
            ticker.AddTimerLoop(3, function()
                if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
                try()
            end, 100, 1)
        end
    end
end

local function refreshCollectUI()
    pcall(function() EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_MAIN_DATA) end)
    pcall(function() EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_SEASON_CHANGE) end)
    pcall(function() EventSystem:postEvent(EVENTTYPE_LOBBY, EVENTID_POST_SWITCH_COLLECT_AVAILABLE_REWARD_POPUP) end)
end

installWithRetry("badgeGold", function()
    if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then return false end
    local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.collect_badge_module)
    if not ok or type(m) ~= "table" then return false end
    if rawget(m, "__badgeGoldHooked") then return true end

    if type(m.CheckCanLightBadge) == "function" then
        local orig = m.CheckCanLightBadge
        m.CheckCanLightBadge = function(self, uid, collect_data, ...)
            if isSelfUid(uid) then return true end
            return orig(self, uid, collect_data, ...)
        end
    end
    if type(m.CheckBadgeActivation) == "function" then
        local orig = m.CheckBadgeActivation
        m.CheckBadgeActivation = function(self, seasonLevel, uid, forceLight, ...)
            if not uid or isSelfUid(uid) then
                return orig(self, seasonLevel, uid, true, ...)
            end
            return orig(self, seasonLevel, uid, forceLight, ...)
        end
    end
    rawset(m, "__badgeGoldHooked", true)
    refreshCollectUI()
    return true
end)

installWithRetry("badgeGoldLevel", function()
    if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then return false end
    local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.collect_module)
    if not ok or type(m) ~= "table" then return false end
    if rawget(m, "__badgeGoldLvHooked") then return true end

    if type(m.GetLevelByScore) == "function" then
        local orig = m.GetLevelByScore
        m.GetLevelByScore = function(self, score)
            if score and score >= 0 then
                return FAKE_LEVEL_BG, FAKE_LEVEL_BG, FAKE_LEVEL_BG, 0, 0
            end
            return orig(self, score)
        end
    end
    rawset(m, "__badgeGoldLvHooked", true)
    refreshCollectUI()
    return true
end)
end)
end

do
pcall(function()

FAKE_LEVEL = 100
FAKE_DAN = 8
FAKE_LEVEL_NAME = "Collection Champion"
FAKE_SCORE = 999999999

if _G.__COLLECT98_LOADED__ then return end
_G.__COLLECT98_LOADED__ = true

patch_collect_module, inject_collect_data = nil

local function isInMatch()
    local inFight = false
    pcall(function()
        if type(GlobalData) == "table" and GlobalData.lastGameStatus then
            local s = string.lower(tostring(GlobalData.lastGameStatus))
            inFight = not (s == "lobby" or s == "login" or s == "createrole" or s == "" or s == "none")
        end
    end)
    return inFight
end

function hook_collect_handler()
    pcall(require, "client.network.Protocol.CollectHandler")
    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.on_get_collect_sys_main_data_rsp and not rawget(mod, "_collection_handler_hooked") then
            rawset(mod, "_collection_handler_hooked", true)
            local orig = mod.on_get_collect_sys_main_data_rsp
            mod.on_get_collect_sys_main_data_rsp = function(err_code, collect_data, param)
                if collect_data and type(collect_data) == "table" then
                    rawset(collect_data, "total_score", FAKE_SCORE)
                    rawset(collect_data, "cur_season_collect_score", FAKE_SCORE)
                    local ss = rawget(collect_data, "season_score")
                    if type(ss) == "table" then
                        for k in pairs(ss) do ss[k] = FAKE_SCORE end
                    else
                        rawset(collect_data, "season_score", { [1] = FAKE_SCORE, [2] = FAKE_SCORE })
                    end
                end
                return orig(err_code, collect_data, param)
            end
            return true
        end
    end
    return false
end

function hook_module_manager()
    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.GetModule and mod.LobbyModuleConfig and mod.LobbyModuleConfig.collect_module and not rawget(mod, "_collection_getmodule_hooked") then
            rawset(mod, "_collection_getmodule_hooked", true)
            local orig_get = mod.GetModule
            local collect_key = mod.LobbyModuleConfig.collect_module
            mod.GetModule = function(self, name)
                local inst = orig_get(self, name)
                if inst and name == collect_key then
                    pcall(function()
                        patch_collect_module(inst)
                        inject_collect_data()
                    end)
                end
                return inst
            end
            return true
        end
    end
    return false
end

function get_collect_module()
    local mm = _G.ModuleManager
    if not mm then
        for _, mod in pairs(package.loaded or {}) do
            if type(mod) == "table" and mod.GetModule and mod.LobbyModuleConfig and mod.LobbyModuleConfig.collect_module then
                mm = mod
                break
            end
        end
    end
    if mm and mm.GetModule and mm.LobbyModuleConfig then
        local ok, cm = pcall(mm.GetModule, mm, mm.LobbyModuleConfig.collect_module)
        if ok and cm then return cm end
    end
    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.GetLevelDataByScore and mod.GetSeasonLevelByScore then
            return mod
        end
    end
    return nil
end

local function getRealMaxSeasonLevel()
    local ok, lv = pcall(function()
        local tbl = CDataTable.GetTable("NewCollectSeasonLevel")
        if not tbl then return nil end
        local sid = _G.DataMgr and tonumber(_G.DataMgr.season_id)
        local maxLv = 0
        for _, v in pairs(tbl) do
            pcall(function()
                local l = tonumber(v.Level)
                local s = tonumber(v.SeasonID)
                if l and (not sid or not s or s == sid) and l > maxLv then maxLv = l end
            end)
        end
        if maxLv > 0 then return maxLv end
        return nil
    end)
    if ok and lv then return lv end
    return FAKE_LEVEL
end

local _cachedLvScore = nil
local function getScoreForLevel(lv)
    if _cachedLvScore then return _cachedLvScore end
    local ok, sc = pcall(function()
        local tbl = CDataTable.GetTable("NewCollectLevel") or CDataTable.GetTable("CollectLevel")
        if not tbl then return nil end
        local best = nil
        for _, v in pairs(tbl) do
            pcall(function()
                local l = tonumber(v.Level)
                local s = tonumber(v.Score or v.NeedScore or v.UpgradeScore or v.LevelScore or v.RequireScore or v.Exp)
                if l and s and l == lv and (not best or s < best) then best = s end
            end)
        end
        return best
    end)
    if ok and sc and sc > 0 then
        _cachedLvScore = sc
        return sc
    end
    return nil
end

patch_collect_module = function(mod)
    if not mod or rawget(mod, "_collection_level_patched") then return false end
    rawset(mod, "_collection_level_patched", true)

    if mod.GetLevelDataByScore then
        rawset(mod, "GetLevelDataByScore", function(self, score, isSeason)
            return FAKE_LEVEL, FAKE_LEVEL_NAME, FAKE_DAN
        end)
    end
    if mod.GetSeasonLevelByScore then
        rawset(mod, "GetSeasonLevelByScore", function(self, score, seasonId)
            return getRealMaxSeasonLevel(), true, FAKE_LEVEL_NAME
        end)
    end
    if mod.GetCollectScoreByCollectData then
        rawset(mod, "GetCollectScoreByCollectData", function(self, collect_data)
            return FAKE_SCORE, FAKE_SCORE
        end)
    end
    if mod.GetCollectTotalScore then
        rawset(mod, "GetCollectTotalScore", function(self, ...) return FAKE_SCORE end)
    end
    if mod.GetCollectScoreByProfile then
        rawset(mod, "GetCollectScoreByProfile", function(self, ...) return FAKE_SCORE end)
    end
    if mod.GetSeasonScoreAndLevelBySeasonID then
        rawset(mod, "GetSeasonScoreAndLevelBySeasonID", function(self, ...)
            return FAKE_SCORE, getRealMaxSeasonLevel()
        end)
    end

    local collect_data = rawget(mod, "collect_data")
    if collect_data and type(collect_data) == "table" then
        rawset(collect_data, "total_score", FAKE_SCORE)
        if not rawget(collect_data, "season_score") then rawset(collect_data, "season_score", {}) end
        local season = (rawget(mod, "GetSeasonId") and mod:GetSeasonId()) or 1
        collect_data.season_score[season] = FAKE_SCORE
        rawset(collect_data, "cur_season_collect_score", FAKE_SCORE)
    end

    if rawget(mod, "OnGetMainData") or mod.OnGetMainData then
        local orig_on_get = rawget(mod, "OnGetMainData") or mod.OnGetMainData
        rawset(mod, "OnGetMainData", function(self, err_code, data, param)
            if data and type(data) == "table" then
                rawset(data, "total_score", FAKE_SCORE)
                if not rawget(data, "season_score") then rawset(data, "season_score", {}) end
                local season = (rawget(self, "GetSeasonId") and self:GetSeasonId()) or 1
                if type(data.season_score) == "table" then
                    data.season_score[season] = FAKE_SCORE
                end
                rawset(data, "cur_season_collect_score", FAKE_SCORE)
            end
            orig_on_get(self, err_code, data, param)
        end)
    end
    return true
end

inject_collect_data = function()
    local cm = get_collect_module()
    if cm then
        local collect_data = rawget(cm, "collect_data")
        if collect_data and type(collect_data) == "table" then
            rawset(collect_data, "total_score", FAKE_SCORE)
            if not rawget(collect_data, "season_score") then rawset(collect_data, "season_score", {}) end
            local season = (rawget(cm, "GetSeasonId") and cm:GetSeasonId()) or 1
            if type(collect_data.season_score) == "table" then
                collect_data.season_score[season] = FAKE_SCORE
            end
            rawset(collect_data, "cur_season_collect_score", FAKE_SCORE)
            for _, k in ipairs({"cloth_count", "weapon_count", "vehicle_count", "pet_count"}) do
                if type(rawget(collect_data, k)) == "number" then rawset(collect_data, k, 999) end
            end
            for _, k in ipairs({"cloth_score", "weapon_score", "vehicle_score", "pet_score"}) do
                if type(rawget(collect_data, k)) == "number" then rawset(collect_data, k, FAKE_SCORE) end
            end
        end
        pcall(function()
            local stats = rawget(cm, "collect_stats_data")
            if type(stats) == "table" then
                for k, v in pairs(stats) do
                    if type(v) == "number" and v < 999 then
                        stats[k] = 999
                    elseif type(v) == "table" then
                        for k2, v2 in pairs(v) do
                            if type(v2) == "number" and v2 < 999 then v[k2] = 999 end
                        end
                    end
                end
            end
        end)
    end
    if _G.DataMgr and _G.DataMgr.roleData then
        if not _G.DataMgr.roleData.brief_collect_data then _G.DataMgr.roleData.brief_collect_data = {} end
        local b = _G.DataMgr.roleData.brief_collect_data
        b.total_score = FAKE_SCORE
        b.cur_season_collect_score = FAKE_SCORE
    end
end

function hook_collect_road_ui()
    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.ShowCollect and mod.ShowSeasonCollect and not rawget(mod, "_collection_road_hooked") then
            rawset(mod, "_collection_road_hooked", true)
            local orig_show = mod.ShowCollect
            if orig_show then
                rawset(mod, "ShowCollect", function(self)
                    pcall(function()
                        local cm = get_collect_module()
                        if cm and rawget(cm, "collect_data") then
                            local cd = rawget(cm, "collect_data")
                            if type(cd) == "table" then
                                rawset(cd, "total_score", FAKE_SCORE)
                                if not rawget(cd, "season_score") then rawset(cd, "season_score", {}) end
                                cd.season_score[(rawget(cm, "GetSeasonId") and cm:GetSeasonId()) or 1] = FAKE_SCORE
                                rawset(cd, "cur_season_collect_score", FAKE_SCORE)
                            end
                        end
                    end)
                    return orig_show(self)
                end)
            end
            return true
        end
    end
    return false
end

function apply_collect_fake()
    hook_collect_handler()
    hook_module_manager()
    hook_collect_road_ui()
    if not _G.AddOutfitCollectModSettled then
        for path, mod in pairs(package.loaded or {}) do
            if type(mod) == "table" and mod.GetLevelDataByScore and mod.GetSeasonLevelByScore and not rawget(mod, "_collection_level_patched") then
                pcall(patch_collect_module, mod)
                _G.AddOutfitCollectModSettled = true
            end
        end
    end
    local cm = get_collect_module()
    if cm then
        pcall(patch_collect_module, cm)
    end
    pcall(inject_collect_data)
end

pcall(apply_collect_fake)

pcall(function()
    local sc = getScoreForLevel(FAKE_LEVEL - 1)
    if sc and sc > 0 then FAKE_SCORE = sc end
end)
pcall(apply_collect_fake)

pcall(function()
    local ticker = _G.Mytimer_ticker or _G.timer_ticker
    if not (ticker and ticker.AddTimerLoop) then
        pcall(function() ticker = require("common.time_ticker") end)
    end
    if ticker and ticker.AddTimerLoop then
        ticker.AddTimerLoop(5, function()
            if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
            if isInMatch() then return end
            pcall(function()
                local sc = getScoreForLevel(FAKE_LEVEL - 1)
                if sc and sc > 0 then FAKE_SCORE = sc end
            end)
            pcall(apply_collect_fake)
        end, 24, 1)
        ticker.AddTimerLoop(30, function()
            if _G.__szScriptVer ~= SZ_SCRIPT_VER then return end
            if isInMatch() then return end
            pcall(inject_collect_data)
        end, -1, 2.6)
    end
end)

print("[Collection Level Spoof] Loaded level=" .. tostring(FAKE_LEVEL))
end)
