function szPMerge(wearData)
    if type(wearData) ~= "table" then return end
    local suit, gun = szPWorn()
    if suit then
        pcall(function()
            local AvatarData = require("client.logic.data.AvatarData")
            local converted = AvatarData and AvatarData.ConvertToAvatarCustom and AvatarData.ConvertToAvatarCustom({ suit, 0, 0 })
            if converted then
                wearData.WearInfoList = wearData.WearInfoList or {}
                local replaced = false
                for i, e in ipairs(wearData.WearInfoList) do
                    local iid = e and (e.ItemID or e.itemId or e.item_id)
                    local isSuit = false
                    if iid then pcall(function() isSuit = F.isSuitRes and F.isSuitRes(iid) end) end
                    if isSuit then
                        wearData.WearInfoList[i] = converted
                        replaced = true
                        break
                    end
                end
                if not replaced then table.insert(wearData.WearInfoList, converted) end
            end
        end)
    end
    if gun then
        local wid = 0
        pcall(function()
            if F and F.weaponIdFromSkin then wid = tonumber(F.weaponIdFromSkin(gun)) or 0 end
        end)
        wearData.mainWeaponInfo = wearData.mainWeaponInfo or {
            weaponResId = 0, weaponSkinId = 0,
            diyInfo = { diyWeaponId = 0, diyDefaultScheme = false, diyScheme = nil },
        }
        wearData.mainWeaponInfo.weaponSkinId = gun
        wearData.mainWeaponInfo.weaponResId = wid
        wearData.depot_show_info = wearData.depot_show_info or {}
        if wearData.depot_show_info.weapon == nil then wearData.depot_show_info.weapon = true end
        if wearData.depot_show_info.hand == nil then wearData.depot_show_info.hand = true end
    end
