function szFakeRes70(n)
    n = tonumber(n)
    if not n or n < 900000000 then return nil end
    local resId = n - 900000000
    if resId <= 0 or resId >= 1e12 then return nil end
    local LSI = _G.LobbySkinInjector
    if LSI and LSI.customSet and LSI.customSet[resId] then return resId end
    local p2 = tostring(resId):sub(1, 2)
    if p2 == "11" or p2 == "21" or p2 == "14" or p2 == "15" then return resId end
    return nil
end

