    local suit, gun = nil, nil
    local LSI = _G.LobbySkinInjector
    if LSI and LSI.customWorn then
        for rawId, _ in pairs(LSI.customWorn) do
            local resId = tonumber(rawId)
            if resId then
                local p2 = tostring(resId):sub(1, 2)
                if p2 == "14" then
                    suit = resId
                elseif p2 == "11" or p2 == "21" then
                    gun = resId
                end
            end
        end
    end
    pcall(function()
        local AS = rawget(_G, "ArmorySystem")
        if type(AS) ~= "table" then
            local paths = { "client.logic.armory.logic_armory", "Client.logic.armory.logic_armory" }
            for _, pth in ipairs(paths) do
                if type(AS) ~= "table" then
                    pcall(function() AS = require(pth) end)
                end
            end
        end
        local il = type(AS) == "table" and AS.rsp_list and AS.rsp_list.install_list
        if type(il) == "table" then
            for wid, entry in pairs(il) do
                local sid = nil
                if type(entry) == "table" then
                    sid = tonumber(entry.skin_id or entry.skinId or entry.instanceID or entry.ins_id)
                else
                    sid = tonumber(entry)
                end
                local resId = szFakeRes70(sid)
                if resId then
                    local p2 = tostring(resId):sub(1, 2)
                    if p2 == "11" or p2 == "21" then
                        gun = resId
                        D.gunWid = tonumber(wid)
                    end
                end
            end
        end
        D.armoryFound = il and "Y" or "N"
    end)
    if not gun and D.gunSkin70 then
        gun = tonumber(D.gunSkin70)
    end
    D.suit = suit
    D.gun = gun
    return suit, gun
