do
    local function __wrapShowNotice9920302(origFunc)
        return function(noticeId, ...)
            local s = tostring(noticeId)
            if s:find("9920302") or s:find("Parameter error") then
                return
            end
            return origFunc(noticeId, ...)
        end
    end
    local function __installBlock9920302()
        local done = true
        if _G.ShowNotice and not _G.__block9920302_ShowNotice then
            _G.__block9920302_ShowNotice = true
            _G.ShowNotice = __wrapShowNotice9920302(_G.ShowNotice)
        elseif not _G.ShowNotice then
            done = false
        end
        local okLoc, Loc = pcall(require, "client.slua.logic.common.logic_common_loc_util")
        if okLoc and Loc and Loc.ShowNotice then
            if not Loc.__block9920302 then
                Loc.__block9920302 = true
                Loc.ShowNotice = __wrapShowNotice9920302(Loc.ShowNotice)
            end
        end
        if _G.LocUtil and _G.LocUtil.ShowNotice and not _G.LocUtil.__block9920302 then
            _G.LocUtil.__block9920302 = true
            _G.LocUtil.ShowNotice = __wrapShowNotice9920302(_G.LocUtil.ShowNotice)
        end
        if not (_G.__block9920302_ShowNotice and (Loc and Loc.__block9920302 or not okLoc)) then
            done = false
        end
        return done
    end
    pcall(__installBlock9920302)
    if not _G.__block9920302_retry then
        _G.__block9920302_retry = true
        pcall(function()
            local t = require("common.time_ticker")
            local n = 0
            local function retry()
                n = n + 1
                if n > 10 then return end
                local ok, done = pcall(__installBlock9920302)
                if not (ok and done) then
                    pcall(function() t.AddTimerOnce(1.0, retry) end)
                end
            end
            t.AddTimerOnce(1.0, retry)
        end)
    end
end

