function _G.FeatureSwitch(key, defaultOn)
    local ok, v = pcall(function()
        if _G.MS_CONFIG_VIP_Config and _G.MS_CONFIG_VIP_Config.Get then
            return _G.MS_CONFIG_VIP_Config.Get(key, defaultOn and 1 or 0)
