function _G.RestoreSuitDefault()
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc then return end
        local uCharacter = pc:GetPlayerCharacterSafety()
        if not uCharacter or not slua.isValid(uCharacter) or not uCharacter.AvatarComponent2 then return end
        local ApplyData = uCharacter.AvatarComponent2.NetAvatarData and uCharacter.AvatarComponent2.NetAvatarData.SlotSyncData
        if not ApplyData or not slua.isValid(ApplyData) then return end
        local orig = _G._origSlotItemId
        if orig then
            for i = 0, ApplyData:Num() - 1 do
                local equipment = ApplyData:Get(i)
                if equipment and equipment.SlotID and orig[equipment.SlotID] ~= nil
                    and equipment.ItemId ~= orig[equipment.SlotID] then
                    equipment.ItemId = orig[equipment.SlotID]
                    ApplyData:Set(i, equipment)
                end
            end
            _G._origSlotItemId = nil
        end
        _G._charAvatarFp = nil
        _G._lastAvatarChar = nil
        uCharacter.AvatarComponent2:OnRep_BodySlotStateChanged()
    end)
end

function _G.RestoreWeaponDefault()
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc then return end
        local uCharacter = pc:GetPlayerCharacterSafety()
        if not uCharacter or not slua.isValid(uCharacter) then return end
        local WeaponManager = uCharacter:GetWeaponManager()
        if not WeaponManager or not slua.isValid(WeaponManager) then return end
        local uWeaponList = WeaponManager:GetAllInventoryWeaponList(false)
        if not uWeaponList or not slua.isValid(uWeaponList) then return end
        for i = 0, uWeaponList:Num() - 1 do
            local w = uWeaponList:Get(i)
            if slua.isValid(w) and w.synData and slua.isValid(w.synData) then
                local wroteAny = false
                local realId = 0
                pcall(function()
                    local def = w:GetItemDefineID()
                    if def then realId = def.TypeSpecificID or 0 end
                end)

                local sd7 = w.synData:Get(7)
                if sd7 and realId > 0 then
                    local cur = slua.IndexReference(sd7, "defineID").TypeSpecificID
                    if cur and cur ~= realId then
                        sd7.defineID.TypeSpecificID = realId
                        w.synData:Set(7, sd7)
                        wroteAny = true
                    end
                end

                for idx = 0, 5 do
                    local okG, Data = pcall(function() return w.synData:Get(idx) end)
                    if okG and Data then
                        local okI, itemid = pcall(function()
                            return slua.IndexReference(Data, "defineID").TypeSpecificID
                        end)
                        if okI and itemid and itemid >= 10000000 then
                            local baseId = (_G._attachSkinToBase and _G._attachSkinToBase[itemid]) or nil
                            if baseId and baseId ~= itemid then
                                Data.defineID.TypeSpecificID = baseId
                                w.synData:Set(idx, Data)
                                wroteAny = true
                            end
                        end
                    end
                end
                if wroteAny and w.DelayHandleAvatarMeshChanged then
                    pcall(function() w:DelayHandleAvatarMeshChanged() end)
                end
            end
        end
        _G.WeaponSkinID = {}
        _G.WeaponAttachmentSkins = {}
        _G._weaponSyncCache = {}
    end)
end

function _G.RestoreVehicleDefault()
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc then return end
        local uCharacter = pc:GetPlayerCharacterSafety()
        if not uCharacter or not slua.isValid(uCharacter) then return end
        local v = uCharacter.CurrentVehicle
        if v and slua.isValid(v) and v.VehicleAvatar then
            local defId = v.VehicleAvatar:GetDefaultAvatarID()
            if defId and v:GetAvatarId() ~= defId then
                v.VehicleAvatar:ChangeItemAvatar(defId, true)
            end
        end
        _G.CurrentEquipVehicleID = nil
    end)
end

end

