        avatarFrames = {},
    }
    CFG = _G.AddOutfitCfg
end

INS_BASE = 2000000000
_G.AddOutfitR = _G.AddOutfitR or { insToRes = {}, resToIns = {}, byWeapon = {} }
R = _G.AddOutfitR

M.later = M.later or function(sec, fn)
    pcall(function()
        local t = require("common.time_ticker")
        if t and t.AddTimerOnce then t.AddTimerOnce(sec, fn) end
    end)
