function ensureBagInject()

    M.getEntity = function()
        local ok, dc = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_data_center")
        if not ok or not dc then return nil end
        local ok2, e = pcall(dc.GetWardrobeData)
        return (ok2 and e) or nil
    end

    M.firstIns = M.firstIns or function(entity, resID)
        local arr = entity and entity.ResIDToIndexArrayMap and entity.ResIDToIndexArrayMap[resID]
        if not arr then return nil end
        for _, idx in pairs(arr) do
            local d = entity._data and entity._data[idx]
            if d and d.count and d.count > 0 then return d.insID end
        end
        return nil
    end

    M.allocIns = M.allocIns or function(entity, resID, preferred)
        preferred = tonumber(preferred)
        if R.resToIns[resID] then return R.resToIns[resID] end
        local owned = M.firstIns(entity, resID)
        if owned then return owned end
        if preferred and preferred > 0 and entity.InsIDToIndexMap and not entity.InsIDToIndexMap[preferred] then
            return preferred
        end
        for off = 1, 8000 do
            local id = INS_BASE + off
            if not entity.InsIDToIndexMap or not entity.InsIDToIndexMap[id] then return id end
        end
        return INS_BASE + (os.time() % 100000)
    end

    M.clearItemExpire = M.clearItemExpire or function(itemData, insID, resID, heavy)
        insID = tonumber(insID or (itemData and (itemData.ins_id or itemData.insID or itemData.instid)))
        resID = tonumber(resID or (itemData and (itemData.res_id or itemData.resID or itemData.resId)))
        if itemData then
            itemData.expireTS = 0
            itemData.expire_ts = 0
            itemData.validHours = 999999
            itemData.valid_hours = 999999
            itemData.obtain_time = os.time()
            itemData.obtainTime = os.time()
            if itemData.hasLimitTime ~= nil then itemData.hasLimitTime = false end
            if itemData.LimitTimeEnd ~= nil then itemData.LimitTimeEnd = 0 end
        end
        local entity = M.getEntity and M.getEntity()
        local d = entity and insID and entity.GetDataByInsID and entity:GetDataByInsID(insID)
        if d then
            d.expireTS = 0
            d.validHours = 999999
            d.expire_ts = 0
            d.valid_hours = 999999
            d.obtain_time = os.time()
            d.obtainTime = os.time()
            if (tonumber(d.count) or 0) < 1 then d.count = 1 end
            if heavy and resID then
                pcall(function() entity:LoadConfigForData(d, CDataTable.GetTableData) end)
                d.expireTS = 0
                d.validHours = 999999
                d.valid_hours = 999999
                d.obtain_time = os.time()
            end
        end
    end

    M.unexpireAllDepot = M.unexpireAllDepot or function()
        local entity = M.getEntity and M.getEntity()
        if not entity or not entity._data then return end
        for i = 1, entity._DataCount or 0 do
            local d = entity._data[i]
            if d and (d.count or 0) > 0 then
                d.expireTS = 0
                d.validHours = 999999
                d.expire_ts = 0
                d.valid_hours = 999999
                d.obtain_time = os.time()
                d.obtainTime = os.time()
            end
        end
    end

    M.ensureItem = M.ensureItem or function(entity, insID, resID)
        insID, resID = tonumber(insID), tonumber(resID)
        if not entity or not insID then return end
        local d = entity.GetDataByInsID and entity:GetDataByInsID(insID)
        if not d then return end
        d.count = math.max(tonumber(d.count) or 0, 1)
        pcall(function()
            entity:LoadConfigForData(d, CDataTable.GetTableData)
        end)

        d.expireTS = 0
        d.validHours = 999999
        d.expire_ts = 0
        d.valid_hours = 999999
        d.obtain_time = os.time()
        d.obtainTime = os.time()
        if d.hasLimitTime ~= nil then d.hasLimitTime = false end
    end

    M.isAvatarFrame = M.isAvatarFrame or function(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        local ok = false
        pcall(function()
            if CDataTable.GetTableData("AvatarFrame", resID) then ok = true end
        end)
        if ok then return true end
        pcall(function()
            local cfg = CDataTable.GetTableData("Item", resID)
            if cfg and tonumber(cfg.ItemSubType) == 2002 then ok = true end
        end)
        return ok
    end

    M.injectAvatarFrame = M.injectAvatarFrame or function(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return false end
        pcall(function()
            local RoleInfoAvatarFrameSystem = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
            RoleInfoAvatarFrameSystem.AvatarFrameList = RoleInfoAvatarFrameSystem.AvatarFrameList or {}
            RoleInfoAvatarFrameSystem.AvatarFrameList[resID] = RoleInfoAvatarFrameSystem.AvatarFrameList[resID] or {}
            RoleInfoAvatarFrameSystem.AvatarFrameList[resID].expire_time = 1
            pcall(function() RoleInfoAvatarFrameSystem.OnHeadFrameNotify(resID, 1) end)
        end)
        CFG.avatarFrames = CFG.avatarFrames or {}
        local found = false
        for _, id in ipairs(CFG.avatarFrames) do
            if tonumber(id) == resID then found = true break end
        end
        if not found then table.insert(CFG.avatarFrames, resID) end
        return true
    end

    M.notifyDepotNew = M.notifyDepotNew or function(insID, resID, count)
        insID, resID = tonumber(insID), tonumber(resID)
        if not insID or not resID then return end
        count = math.max(1, tonumber(count) or 1)
        pcall(function()
            local changeList = {
                [insID] = {
                    instid = insID, res_id = resID, count = count, isnew = 1,
                    lock_cnt = 0, valid_hours = 0, expire_ts = 0,
                }
            }
            if EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_HALL_DEPOT_ADD then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_ADD, changeList)
            elseif EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_HALL_DEPOT_DATA then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_DATA, changeList)
            end
        end)
    end

    M.weaponIdFromSkin = M.weaponIdFromSkin or function(resID)
        local wid
        pcall(function()
            local cfg = CDataTable.GetTableData("WeaponSkin", resID)
                or CDataTable.GetTableData("WeaponAvatar", resID)
            if cfg then
                wid = tonumber(cfg.WeaponID or cfg.weapon_id or cfg.WeaponId)
            end
        end)
        return wid
    end

    M.injectArmory = M.injectArmory or function(resID, insID)
        resID, insID = tonumber(resID), tonumber(insID)
        if not resID or not insID then return end
        local wid = M.weaponIdFromSkin(resID)
        if not wid then return end
        pcall(function()
            local Arm = require("client.logic.armory.logic_armory")
            Arm.rsp_list = Arm.rsp_list or {}
            Arm.rsp_list.skin_list = Arm.rsp_list.skin_list or {}
            Arm.rsp_list.skin_list[wid] = Arm.rsp_list.skin_list[wid] or {}
            Arm.rsp_list.skin_list[wid][resID] = insID
            if Arm.ContructResIdToWardrobeInsID then Arm.ContructResIdToWardrobeInsID() end
        end)
    end

    M.refreshWardrobe = M.refreshWardrobe or function(force)
        pcall(function()
            if not EventSystem or not EVENTTYPE_WARDROBE then return end
            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
            end
        end)
    end

    M.loadConfig = M.loadConfig or function() end
    M.saveConfigNow = M.saveConfigNow or function()

        pcall(function()
            CFG.extraItems = CFG.extraItems or {}
            CFG.itemCounts = CFG.itemCounts or {}
            _G.GTLModConfig = _G.GTLModConfig or {}
            local bag = { extraItems = {}, itemCounts = {} }
            for i, id in ipairs(CFG.extraItems) do
                bag.extraItems[i] = tonumber(id) or 0
            end
            for k, v in pairs(CFG.itemCounts) do
                bag.itemCounts[tostring(k)] = tonumber(v) or 1
            end
            _G.GTLModConfig.LizardVipCrateBag = bag
            if _G.SaveModSettings then _G.SaveModSettings() end
        end)
    end
    M.persistMarkDirty = M.persistMarkDirty or function()
        if M.later then
            M.later(0.4, function() pcall(M.saveConfigNow) end)
        else
            pcall(M.saveConfigNow)
        end
    end

    M.rememberBagItem = M.rememberBagItem or function(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return end
        CFG.extraItems = CFG.extraItems or {}
        CFG.itemCounts = CFG.itemCounts or {}
        local found = false
        for _, id in ipairs(CFG.extraItems) do
            if tonumber(id) == resID then found = true break end
        end
        if not found then
            table.insert(CFG.extraItems, resID)
        end
        if (tonumber(CFG.itemCounts[resID]) or 0) < 1 then
            CFG.itemCounts[resID] = 1
        end
        M.persistMarkDirty()
    end

    if type(M.injectOne) ~= "function" then
        M.injectOne = function(entity, resID, insID, opts)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return false end
            opts = type(opts) == "table" and opts or {}
            local markNew = opts.markNew == true
            local addCount = tonumber(opts.addCount) or 1
            if addCount < 1 then addCount = 1 end
            local forceCount = tonumber(opts.forceCount)

            if M.isAvatarFrame(resID) then
                M.injectAvatarFrame(resID)
            end
            if not entity then
                return M.isAvatarFrame(resID)
            end

            CFG.itemCounts = CFG.itemCounts or {}
            CFG.newItems = CFG.newItems or {}

            insID = M.allocIns(entity, resID, insID)
            local owned = M.firstIns(entity, resID)
            if owned then
                R.resToIns[resID], R.insToRes[owned] = owned, resID
                local d = entity.GetDataByInsID and entity:GetDataByInsID(owned)
                if d then
                    local cur = tonumber(d.count) or 0
                    local newCount = forceCount or (cur + addCount)
                    d.count = newCount
                    d.expireTS = 0
                    d.validHours = 999999
                    d.valid_hours = 999999
                    d.expire_ts = 0
                    d.obtain_time = os.time()
                    d.obtainTime = os.time()
                    CFG.itemCounts[resID] = newCount
                    if markNew then
                        d.isNew = true
                        CFG.newItems[resID] = true
                        M.notifyDepotNew(owned, resID, newCount)
                    end
                end
                M.ensureItem(entity, owned, resID)
                M.clearItemExpire(nil, owned, resID, false)
                if M.weaponIdFromSkin(resID) then M.injectArmory(resID, owned) end
                M.persistMarkDirty()
                return true
            end

            if entity.InsIDToIndexMap and entity.InsIDToIndexMap[insID] then
                insID = M.allocIns(entity, resID, nil)
            end
            entity:AddData({
                instid = insID, res_id = resID, count = addCount, lock_cnt = 0,
                isnew = markNew and 1 or 0, valid_hours = 999999, expire_ts = 0,
                obtain_time = os.time(),
            })
            M.ensureItem(entity, insID, resID)
            M.clearItemExpire(nil, insID, resID, false)
            local d2 = entity.GetDataByInsID and entity:GetDataByInsID(insID)
            if d2 then
                d2.count = addCount
                d2.isNew = markNew
                d2.expireTS = 0
                d2.validHours = 999999
                d2.expire_ts = 0
                d2.valid_hours = 999999
                d2.obtain_time = os.time()
                d2.obtainTime = os.time()
            end
            CFG.itemCounts[resID] = addCount
            R.resToIns[resID], R.insToRes[insID] = insID, resID
            if M.weaponIdFromSkin(resID) then M.injectArmory(resID, insID) end
            if markNew then
                CFG.newItems[resID] = true
                M.notifyDepotNew(insID, resID, addCount)
            end
            M.persistMarkDirty()
            return true
        end
    end

    M.syncCollectFromMemory = M.syncCollectFromMemory or function() end
    M.reapplyAvatarFrames = M.reapplyAvatarFrames or function() end
    M.buildSavePayload = M.buildSavePayload or function()
        return {
            extraItems = CFG.extraItems,
            itemCounts = CFG.itemCounts,
            luckyTotalDraw = CFG.luckyTotalDraw,
            luckyClaimed = CFG.luckyClaimed,
            avatarFrames = CFG.avatarFrames,
        }
    end
    M.applyConfigTable = M.applyConfigTable or function(data)
        if type(data) ~= "table" then return end
        if type(data.extraItems) == "table" then CFG.extraItems = data.extraItems end
        if type(data.itemCounts) == "table" then CFG.itemCounts = data.itemCounts end
        if type(data.luckyTotalDraw) == "table" then CFG.luckyTotalDraw = data.luckyTotalDraw end
        if type(data.luckyClaimed) == "table" then CFG.luckyClaimed = data.luckyClaimed end
        if type(data.avatarFrames) == "table" then CFG.avatarFrames = data.avatarFrames end
    end
end

ensureBagInject()

NET_OK = NetErrorCode_NONE or "ok"

function installExpireAndWear()

    if not _G.__LocalCrateExpireHooked then
        _G.__LocalCrateExpireHooked = true
        pcall(function()
            if DataMgr then
                DataMgr.IsValidTime = function() return true end
            end
        end)
        pcall(function()
            local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
            wl.IsWearValid = function() return true end
            local oPage = wl.IsValidCurrentPageItem
            wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, serverTime)
                if v then
                    v.expireTS = 0; v.validHours = 999999
                    v.expire_ts = 0; v.valid_hours = 999999
                    v.obtain_time = os.time(); v.obtainTime = os.time()
                end
                if oPage then return oPage(self, mainTab, subTab, v, serverTime) end
                return true
            end
            local oGroup = wl.IsValidCurrentPageItemBySubTabGroup
            wl.IsValidCurrentPageItemBySubTabGroup = function(self, mainTab, subTabGroup, v, serverTime)
                if v then
                    v.expireTS = 0; v.validHours = 999999
                    v.expire_ts = 0; v.valid_hours = 999999
                    v.obtain_time = os.time(); v.obtainTime = os.time()
                end
                if oGroup then return oGroup(self, mainTab, subTabGroup, v, serverTime) end
                return true
            end
            if wl.IsItemExpire then wl.IsItemExpire = function() return false end end
            if wl.IsExpire then wl.IsExpire = function() return false end end
            if wl.CheckItemExpire then wl.CheckItemExpire = function() return false end end
        end)
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local oGet = wd.GetHallDepotItemDataByInsID
            if type(oGet) == "function" then
                wd.GetValidHallDepotItemDataByInsID = function(self, insID)
                    local d = oGet(self, insID)
                    if not d then return d end
                    d.expireTS = 0
                    d.validHours = 999999
                    d.expire_ts = 0
                    d.valid_hours = 999999
                    d.obtain_time = os.time()
                    d.obtainTime = os.time()
                    return d
                end

                if not wd.__localExpireGetHooked then
                    wd.__localExpireGetHooked = true
                    wd.GetHallDepotItemDataByInsID = function(self, insID)
                        local d = oGet(self, insID)
                        if d then
                            d.expireTS = 0
                            d.validHours = 999999
                            d.expire_ts = 0
                            d.valid_hours = 999999
                            d.obtain_time = os.time()
                            d.obtainTime = os.time()
                        end
                        return d
                    end
                end
            end
        end)
    end

    if not _G.__LocalCrateWearHooked then
        _G.__LocalCrateWearHooked = true
        pcall(function()
            local WRH = require("client.network.Protocol.WardRobeHandler")
            if not WRH or WRH.__localCratePutOn then return end
            WRH.__localCratePutOn = true
            local oSend = WRH.send_depot_put_on_req
            WRH.send_depot_put_on_req = function(insID, extra)
                insID = tonumber(insID)
                if not insID then
                    return oSend(insID, extra)
                end
                local itemData
                pcall(function()
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    itemData = wd:GetHallDepotItemDataByInsID(insID)
                end)
                if not itemData and R and R.insToRes and R.insToRes[insID] then
                    itemData = { resID = R.insToRes[insID], res_id = R.insToRes[insID], count = 1 }
                end

                if not itemData and insID >= 900000000 then
                    local rid = insID - 900000000
                    local okRid = false
                    pcall(function() okRid = (M.weaponIdFromSkin and M.weaponIdFromSkin(rid)) ~= nil end)
                    if not okRid and CFG and CFG.itemCounts and CFG.itemCounts[rid] then okRid = true end
                    if okRid then
                        itemData = { resID = rid, res_id = rid, count = 1 }
                    end
                end
                if itemData then
                    M.clearItemExpire(itemData, insID, itemData.resID or itemData.res_id, true)
                    local resID = tonumber(itemData.resID or itemData.res_id) or 0
                    local ours = (insID >= INS_BASE)
                        or (R.insToRes and R.insToRes[insID] ~= nil)
                        or (resID > 0 and R.resToIns and R.resToIns[resID] ~= nil)
                        or (CFG.extraItems and (function()
                            for _, id in ipairs(CFG.extraItems) do
                                if tonumber(id) == resID then return true end
                            end
                            return false
                        end)())
                    if ours then
                        local item = { res_id = resID, count = itemData.count or 1 }
                        pcall(function()
                            WRH.on_depot_put_on_rsp(NET_OK, item, nil, 3, insID, 0, extra)
                        end)
                        return
                    end
                end
                return oSend(insID, extra)
            end

            local oPutDown = WRH.send_depot_put_down_req
            if type(oPutDown) == "function" then
                WRH.send_depot_put_down_req = function(insID)
                    insID = tonumber(insID)
                    if not insID then return oPutDown(insID) end
                    local itemData
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        itemData = wd:GetHallDepotItemDataByInsID(insID)
                    end)
                    if not itemData and insID >= 900000000 then
                        local rid = insID - 900000000
                        local okRid = false
                        pcall(function() okRid = (M.weaponIdFromSkin and M.weaponIdFromSkin(rid)) ~= nil end)
                        if not okRid and CFG and CFG.itemCounts and CFG.itemCounts[rid] then okRid = true end
                        if okRid then
                            itemData = { resID = rid, res_id = rid, count = 1 }
                        end
                    end
                    if itemData then
                        local resID = tonumber(itemData.resID or itemData.res_id) or 0
                        local ours = (insID >= INS_BASE)
                            or (R.insToRes and R.insToRes[insID] ~= nil)
                            or (resID > 0 and CFG.itemCounts and CFG.itemCounts[resID])
                        if ours then
                            local item = { res_id = resID, count = itemData.count or 1 }
                            pcall(function() WRH.on_depot_put_down_rsp(NET_OK, item, insID) end)
                            return
                        end
                    end
                    return oPutDown(insID)
                end
            end
        end)
    end

    pcall(function() M.unexpireAllDepot() end)
end

installExpireAndWear()
M.later(1.0, installExpireAndWear)
M.later(3.0, installExpireAndWear)

pcall(function()
    local avatarClass = require("client.slua.umg.Wardrobe.subtab_avatar")
    local gunClass = require("client.slua.umg.Wardrobe.subtab_gun")
    local function wrapClick(classMod, key)
        if not classMod or not classMod.__inner_impl or not classMod.__inner_impl[key] then return end
        local impl = classMod.__inner_impl
        if impl["_LocalWrap_" .. key] then return end
        impl["_LocalWrap_" .. key] = true
        local orig = impl[key]
        impl[key] = function(self, widget, index)
            local grid = self.LoopScrollGrid_Normal or self.LoopScrollGridSkins
            local itemData = grid and grid.GetItemData and grid:GetItemData(index)
            if itemData then
                pcall(M.clearItemExpire, itemData, itemData.ins_id or itemData.insID, itemData.res_id or itemData.resID, true)
            end
            return orig(self, widget, index)
        end
    end
    wrapClick(avatarClass, "OnClickItem")
    wrapClick(gunClass, "OnClickItem")
end)

pcall(function()
    local Arm = require("client.logic.armory.logic_armory")
    if Arm and not Arm.__localSkinChangeHooked then
        Arm.__localSkinChangeHooked = true
        local oInstall = Arm.install_weapon_skin
        if type(oInstall) == "function" then
            Arm.install_weapon_skin = function(client_data, weapon_id, instanceID)
                instanceID = tonumber(instanceID)
