function Spin_AddDropsToBag(dropList)
    if not dropList then return end
    ensureBagInject()

    local collectIds = {}

    for _, v in pairs(dropList) do
        local resID = tonumber(v.res_id or v.resid or v.itemId or v.itemid)
        if resID and resID > 0 then
            pcall(function() M.rememberBagItem(resID) end)
            table.insert(collectIds, resID)
        end
    end

    local entity = M.getEntity and M.getEntity() or nil

    local function doInject(ent)
        if not ent then return 0 end
        local n = 0
        for _, v in pairs(dropList) do
            local resID = tonumber(v.res_id or v.resid or v.itemId or v.itemid)
            local count = tonumber(v.count or v.itemCount or 1) or 1
            if resID and resID > 0 then
                pcall(function()
                    if M.isAvatarFrame and M.isAvatarFrame(resID) then
                        M.injectAvatarFrame(resID)
                    end
                end)

                local ok = false
                pcall(function()
                    ok = M.injectOne(ent, resID, nil, { addCount = count, markNew = true }) == true
                end)
                if ok then
                    n = n + 1
                elseif M.isAvatarFrame and M.isAvatarFrame(resID) then
                    n = n + 1
                else
                end
            end
        end
        if n > 0 then
            pcall(function() M.refreshWardrobe(true) end)
            pcall(function() if M.saveConfigNow then M.saveConfigNow() end end)
        end
        return n
    end

    if entity and entity.bInit then
        doInject(entity)
    else
    end
    if M.later then
        for _, sec in ipairs({ 0.5, 1.5, 3.0, 6.0 }) do
            M.later(sec, function()
                ensureBagInject()
                local e = M.getEntity and M.getEntity()
                if e and e.bInit then doInject(e) end
            end)
        end
    end

    addCollectorPoints(collectIds)
end

pcall(function()
    local WARDROBE_FAKE_BASE = 900000000

    local armoryOwnedSet = {}
    for _, resID in ipairs(CUSTOM_ITEM_IDS) do
        resID = tonumber(resID)
        if resID and resID >= 1101000000 and resID < 1102000000 then
            armoryOwnedSet[resID] = true
        end
    end

    local function getArmoryModules(out)
        out = out or {}
        local paths = {
            "client.logic.armory.logic_armory",
            "client.slua.logic.armory.logic_armory",
            "Client.logic.armory.logic_armory",
            "Client.slua.logic.armory.logic_armory",
        }
        for _, path in ipairs(paths) do
            pcall(function()
                local mod = require(path)
                if type(mod) == "table" then out[#out + 1] = mod end
            end)
            pcall(function()
                local mod = package.loaded[path]
                if type(mod) == "table" then out[#out + 1] = mod end
            end)
        end

        pcall(function()
            if ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig then
                for _, name in pairs(ModuleManager.LobbyModuleConfig) do
                    if type(name) == "string" and name:lower():find("armory") then
                        local mod = ModuleManager.GetModule(name)
                        if type(mod) == "table" then out[#out + 1] = mod end
                    end
                end
            end
        end)

        local seen, ret = {}, {}
        for _, mod in ipairs(out) do
            if not seen[mod] then seen[mod] = true ret[#ret + 1] = mod end
        end
        return ret
    end

    local function ownArmorySkin(resID)
        if not M or not M.weaponIdFromSkin then return end
        local wid = M.weaponIdFromSkin(resID)
        if not wid then return end
        local fakeIns = WARDROBE_FAKE_BASE + resID
        for _, Arm in ipairs(getArmoryModules()) do

        pcall(function()
            if Arm and Arm.install_weapon_skin_rsp then
                Arm.install_weapon_skin_rsp(nil, 0, wid, fakeIns)
            end
        end)
        pcall(function()
            Arm.rsp_list = Arm.rsp_list or {}
            local rl = Arm.rsp_list

            local realIns = R and R.resToIns and R.resToIns[resID]
            rl.skin_list = rl.skin_list or {}
            rl.skin_list[wid] = rl.skin_list[wid] or {}
            rl.skin_list[wid][resID] = realIns or fakeIns

            rl.install_list = rl.install_list or {}
            local cur = rl.install_list[wid]
            if type(cur) ~= "table" then cur = {} end
            cur.skin_id = fakeIns
            cur.skinId = fakeIns
            cur.insID = fakeIns
            cur.instid = fakeIns
            cur.res_id = resID
            cur.resID = resID
            cur.skin_res_id = resID
            cur.level = 8
            rl.install_list[wid] = cur

            rl.skin_level = rl.skin_level or {}
            rl.skin_level[resID] = 8
            rl.skinLevel = rl.skinLevel or {}
            rl.skinLevel[resID] = 8
            rl.gun_list = rl.gun_list or {}
            if not rl.gun_list[wid] then
                rl.gun_list[wid] = {
                    gun_id = wid, gunId = wid, weapon_id = wid, weaponId = wid,
                    level = 8, skin_id = resID, skinId = resID, skin_res_id = resID,
                }
            end
            rl.gun_level = rl.gun_level or {}
            rl.gun_level[wid] = 8
            if Arm.ContructResIdToWardrobeInsID then pcall(Arm.ContructResIdToWardrobeInsID) end
        end)
        end
    end

    local armoryFnsWrapped = false
    local function wrapArmoryFns()
        if armoryFnsWrapped then return end
        for _, Arm in ipairs(getArmoryModules()) do
        pcall(function()

            for _, fnName in ipairs({ "IsSkinOwned", "IsOwnSkin", "HasSkin", "HasGunSkin", "IsGunSkinOwned", "CheckSkinOwned", "GetSkinOwned", "IsOwned" }) do
                local orig = Arm[fnName]
                if type(orig) == "function" then
                    Arm[fnName] = function(self, a, b, ...)
                        local id = tonumber(b) or tonumber(a)
                        if id and armoryOwnedSet[id] then return true end
                        return orig(self, a, b, ...)
                    end
                end
            end

            for _, fnName in ipairs({ "GetSkinLevel", "GetGunSkinLevel", "GetOwnedSkinLevel", "GetSkinLv", "GetLevel" }) do
                local orig = Arm[fnName]
                if type(orig) == "function" then
                    Arm[fnName] = function(self, a, b, ...)
                        local id = tonumber(b) or tonumber(a)
                        if id and armoryOwnedSet[id] then return 8 end
                        return orig(self, a, b, ...)
                    end
                end
            end
        end)
        end
        armoryFnsWrapped = true
    end

    local function registerArmoryGuns()
        if not M or not M.injectArmory then return end
        local ent = M.getEntity and M.getEntity() or nil
        local bagReady = ent and ent.bInit and type(M.injectOne) == "function"
        for resID in pairs(armoryOwnedSet) do

            local realIns = nil
            if bagReady then
                pcall(M.injectOne, ent, resID, nil, { addCount = 1, forceCount = 1, markNew = false })
                realIns = R and R.resToIns and R.resToIns[resID]
            end

            pcall(M.injectArmory, resID, realIns or (WARDROBE_FAKE_BASE + resID))
            pcall(ownArmorySkin, resID)
        end
        wrapArmoryFns()
        pcall(function() if bagReady and M.refreshWardrobe then M.refreshWardrobe(true) end end)
    end

    registerArmoryGuns()
    if M and M.later then
        M.later(2.0, registerArmoryGuns)
        M.later(6.0, registerArmoryGuns)
        M.later(12.0, registerArmoryGuns)
        M.later(20.0, registerArmoryGuns)
        M.later(30.0, registerArmoryGuns)
    end
end)

