function lizardvipAccountBridgePayload()
    local acc = _G.LizardVipFakeAccount or {}
    local uid = ""

    local liveUc, liveBp, liveSilver, liveAg, liveLevel
    pcall(function()
        if DataMgr then
            liveUc = tonumber(DataMgr.ticket) or 0
            liveBp = tonumber(DataMgr.gold) or 0
            liveSilver = tonumber(DataMgr.diamond) or 0
            liveAg = tonumber(DataMgr.eternal_diamond) or 0
            if DataMgr.roleData then
                liveLevel = tonumber(DataMgr.roleData.level) or 0
                if uid == "" then uid = tostring(DataMgr.roleData.uid or "") end
            end
        end
    end)
    pcall(function()
        if uid == "" and M and M.resolveUid then uid = tostring(M.resolveUid() or "") end
    end)
    return {
        t = "account",
        uid = tostring(uid or ""),
        uc = lizardvipNum(liveUc or acc.uc or 0),
        bp = lizardvipNum(liveBp or acc.bp or 0),
        silver = lizardvipNum(liveSilver or acc.silver or 0),
        ag = lizardvipNum(liveAg or acc.ag or 0),
        level = math.max(0, lizardvipNum(liveLevel or acc.level or 0)),
    }
end

