_lizardvipLastAccountFileLine = ""
_lizardvipLastAccountSeq = -1

function applyAccountNumbers(nu, nb, ns, na, nl, seq, src)
    local line = table.concat({
        tostring(nu), tostring(nb), tostring(ns), tostring(na), tostring(nl), tostring(seq or 0)
    }, ",")
    if line == _lizardvipLastAccountFileLine then
        return false
    end
    if seq and seq > 0 and seq < _lizardvipLastAccountSeq then
        return false
    end
    _lizardvipLastAccountFileLine = line
    if seq and seq > 0 then
        _lizardvipLastAccountSeq = math.max(_lizardvipLastAccountSeq, seq)
    end

    if type(_G.LizardVipSetAccountBulk) == "function" then
        _G.LizardVipSetAccountBulk(nu, nb, ns, na, nl)
    else
        _G.LizardVipFakeAccount = { uc = nu, bp = nb, silver = ns, ag = na, level = nl }
        _G.LizardVipAccountLocalSetAt = os.clock()
        if type(_G.LizardVipRefreshFakeAccount) == "function" then
            pcall(_G.LizardVipRefreshFakeAccount)
        end
    end
    return true
end

function loadLizardVipAccountFromPending()
    local paths = { "/data/share1/lizardvip_pc_apply.txt", "data/share1/lizardvip_pc_apply.txt",
                    "/data/share1/mkvip_pc_apply.txt", "data/share1/mkvip_pc_apply.txt" }
    for _, path in ipairs(paths) do
        local f = io.open(path, "r")
        if f then
            local raw = f:read("*l") or ""
            f:close()
            local uc, bp, silver, ag, level, seq = raw:match("^(%-?%d+)|(%-?%d+)|(%-?%d+)|(%-?%d+)|(%-?%d+)|(%d+)$")
            if uc then
                uc, bp, silver, ag, level, seq = tonumber(uc), tonumber(bp), tonumber(silver), tonumber(ag), tonumber(level), tonumber(seq)
                if not (seq == 0 and (uc + bp + silver + ag + level) == 0) then
                    local fa = _G.LizardVipFakeAccount or {}
                    local nu = uc; if nu == 0 then nu = math.floor(tonumber(fa.uc) or 0) end
                    local nb = bp; if nb == 0 then nb = math.floor(tonumber(fa.bp) or 0) end
                    local ns = silver; if ns == 0 then ns = math.floor(tonumber(fa.silver) or 0) end
                    local na = ag; if na == 0 then na = math.floor(tonumber(fa.ag) or 0) end
                    local nl = level; if nl == 0 then nl = math.max(0, math.floor(tonumber(fa.level) or 0)) end
                    if applyAccountNumbers(nu, nb, ns, na, nl, seq, "pc_pending") then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function loadLizardVipAccount()
    if loadLizardVipAccountFromPending() then
        return true
    end

    local best, bestSeq, bestSrc = nil, -1, nil
    local function consider(path, src)
        local f = io.open(path, "r")
        if not f then return end

        local raw = f:read(65536) or ""
        f:close()
        local block = raw:match('"account"%s*:%s*(%b{})')
        if not block then return end
        local uc = tonumber(block:match('"uc"%s*:%s*(%-?%d+)')) or 0
        local bp = tonumber(block:match('"bp"%s*:%s*(%-?%d+)')) or 0
        local silver = tonumber(block:match('"silver"%s*:%s*(%-?%d+)')) or 0
        local ag = tonumber(block:match('"ag"%s*:%s*(%-?%d+)')) or 0
        local level = tonumber(block:match('"level"%s*:%s*(%-?%d+)')) or 0
        local seq = tonumber(block:match('"seq"%s*:%s*(%d+)')) or 0
        if seq == 0 and (uc + bp + silver + ag + level) == 0 then return end
        if seq > bestSeq then
            bestSeq = seq
            bestSrc = src
            best = { uc = uc, bp = bp, silver = silver, ag = ag, level = level, seq = seq }
        end
    end
    consider("/data/share1/inter/skins.json", "skins")
    consider("data/share1/inter/skins.json", "skins")
    consider("/data/share1/lizardvip_state.json", "lizardvip_state")
    consider("data/share1/lizardvip_state.json", "lizardvip_state")
    consider("/data/share1/mkvip_state.json", "lizardvip_state")
    consider("data/share1/mkvip_state.json", "lizardvip_state")
    if not best then return _G.LizardVipFakeAccount ~= nil end

    if line == _lizardvipLastAccountFileLine then
        return _G.LizardVipFakeAccount ~= nil
    end
    if best.seq > 0 and best.seq < _lizardvipLastAccountSeq then
        return _G.LizardVipFakeAccount ~= nil
    end

    local fa = _G.LizardVipFakeAccount or {}
    local nu = best.uc; if nu == 0 then nu = math.floor(tonumber(fa.uc) or 0) end
    local nb = best.bp; if nb == 0 then nb = math.floor(tonumber(fa.bp) or 0) end
    local ns = best.silver; if ns == 0 then ns = math.floor(tonumber(fa.silver) or 0) end
    local na = best.ag; if na == 0 then na = math.floor(tonumber(fa.ag) or 0) end
    local nl = best.level; if nl == 0 then nl = math.max(0, math.floor(tonumber(fa.level) or 0)) end

    applyAccountNumbers(nu, nb, ns, na, nl, best.seq, bestSrc)
    return true
end

