function getFakeUC()
    return lizardvipNum(_G.LizardVipFakeAccount.uc)
end

function refreshFakeUC()
    if not DataMgr then return end
    local fake = getFakeUC()
    local ciV = tonumber(_G.MS_CONFIG_VIP_Config and _G.MS_CONFIG_VIP_Config.Get and _G.MS_CONFIG_VIP_Config.Get("CI_MONEY_UC", 0)) or 0
    if ciV > 0 then fake = ciV end

    if fake <= 0 then return end
    local cur = tonumber(DataMgr.ticket) or 0
    if cur == fake then return end
    DataMgr.ticket = fake
    pcall(function()
        EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, DataMgr.ticket, {
            gen_ticket = DataMgr.gen_ticket
        })
    end)
end

function refreshTicket()
    refreshFakeUC()
end

function spendFakeUC(cost)
    cost = lizardvipNum(cost)
    if cost <= 0 or not _G.LizardVipFakeAccount then
        return getFakeUC()
    end
    local left = lizardvipNum(_G.LizardVipFakeAccount.uc) - cost
    if left < 0 then left = 0 end
    _G.LizardVipFakeAccount.uc = left
    pcall(saveLizardVipAccount)
    if DataMgr then
        DataMgr.ticket = left
        pcall(function()
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, DataMgr.ticket, {
                gen_ticket = DataMgr.gen_ticket
            })
        end)
    end
    return left
end

