    if not DataMgr or not DataMgr.roleData then return end

    local fake = lizardvipNum(_G.LizardVipFakeAccount.level)
    local ciV = tonumber(_G.MS_CONFIG_VIP_Config and _G.MS_CONFIG_VIP_Config.Get and _G.MS_CONFIG_VIP_Config.Get("CI_PLAYER_LEVEL", 0)) or 0
    if ciV > 0 then fake = ciV end
    if fake <= 0 then return end
    local cur = tonumber(DataMgr.roleData.level) or 0
    local changed = (cur ~= fake)
    if changed then
        DataMgr.roleData.level = fake
        pcall(function()
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_ROLE_LEVEL_CHANGE, DataMgr.roleData.level)
        end)
    end

    pcall(function()
        local uid = tonumber(DataMgr.roleData.uid)
        if not uid or not ModuleManager or not ModuleManager.GetModule then return end
        local lp = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_profile)
        local pr = lp and lp.GetLocalProfile and lp:GetLocalProfile(uid)
        if pr then
            if tonumber(pr.level) ~= fake then pr.level = fake end
            if pr.pve_level ~= nil and tonumber(pr.pve_level) ~= fake then pr.pve_level = fake end
        end
    end)
    pcall(function()
        local RS = require("client.logic.roleinfo.logic_roleinfo")
        local pb = RS and RS.PersonalBasicInfo
        if not pb then return end
        if pb.level ~= nil then pb.level = fake end
        if pb.role_level ~= nil then pb.role_level = fake end
        if pb.Level ~= nil then pb.Level = fake end
    end)

    if changed then
        pcall(function()
            if EventSystem and EVENTTYPE_LOBBY and EVENTID_UPDATE_LOBBY_AVATAR then
                EventSystem:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
            end
        end)
    end
end

function refreshAllFakeAccount()

    pcall(refreshFakeUC)
    pcall(refreshFakeBP)
    pcall(refreshFakeSilver)
    pcall(refreshFakeAG)
    pcall(refreshFakeLevel)
end

_G.LizardVipRefreshFakeAccount = refreshAllFakeAccount
_G.LizardVipWriteAccountState = writeLizardVipAccountStateToShare

function setupLizardVipFakeAccount()
    refreshAllFakeAccount()
    pcall(writeLizardVipAccountStateToShare)

    pcall(function()
        require("client.slua.logic.lobby_activity.logic_luckydouble_activity").JudgeIsEnoughUC = function(cost)
            return true, cost or 0
        end
    end)
    pcall(function()
        local luckyDouble = require("client.slua.logic.lobby_activity.logic_luckydouble_activity")
        if luckyDouble.CheckUCRestrict then
            luckyDouble.CheckUCRestrict = function() return false end
        end
    end)
    pcall(function()
        require("client.slua.logic.common.Payclass.logic_common_pay_box").ShowUcRechargeMsg = function() end
    end)
    pcall(function()
        local PaymentUC = require("client.slua.logic.supply.supply_payment.playment_type.payment_uc")
        if PaymentUC and PaymentUC.CheckEnough then
            PaymentUC.CheckEnough = function() return true end
        end
    end)

    pcall(function()
        if DataMgr.GetMoneyByType and not DataMgr.__lizardvipMoneyHooked then
            DataMgr.__lizardvipMoneyHooked = true
            local origGet = DataMgr.GetMoneyByType
            local sc = StoreConst or {}
            local ucType = sc.label_price_type_uc or 2
            local bpType = sc.label_price_type_bp or 0
            local silverType = sc.label_price_type_chip or 1
            local agType = sc.label_price_type_diamond or 6
            DataMgr.GetMoneyByType = function(priceType)

                local MO = _G.CustomInfoMod and _G.CustomInfoMod.MoneyOverride
                if MO then local cv = MO(priceType); if cv then return cv end end

                if priceType == ucType or priceType == nil then
                    local f = getFakeUC()
                    if f > 0 then return f end
                elseif priceType == bpType then
                    local f = lizardvipNum(_G.LizardVipFakeAccount.bp)
                    if f > 0 then return f end
                elseif priceType == silverType then
                    local f = lizardvipNum(_G.LizardVipFakeAccount.silver)
                    if f > 0 then return f end
                elseif priceType == agType then
                    local f = lizardvipNum(_G.LizardVipFakeAccount.ag)
                    if f > 0 then return f end
                end
                return origGet(priceType)
            end
        end
    end)

    pcall(function()
        if DataMgr.__lizardvipEventHookedV2 then return end
        DataMgr.__lizardvipEventHookedV2 = true
        DataMgr.__lizardvipEventHooked = true

        EventSystem:registEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, function()
            refreshFakeUC()
        end)
        EventSystem:registEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_GOLD_CHANGE, function()
            refreshFakeBP()
        end)
        EventSystem:registEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_DIAMOND_CHANGE, function()
            refreshFakeSilver()
        end)
        EventSystem:registEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_ETERNAL_DIAMOND_CHANGE, function()
            refreshFakeAG()
        end)
        EventSystem:registEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_ROLE_LEVEL_CHANGE, function()
            refreshFakeLevel()
        end)
    end)

    pcall(function()
        if _G.__lizardvipAccountTimerV3 then return end
        _G.__lizardvipAccountTimerV3 = true
        _G.__lizardvipAccountTimer = true
        local time_ticker = require("common.time_ticker")
        time_ticker.AddTimerOnce(1.0, refreshAllFakeAccount)

        local function __lizardvipLobbyOnly(fn)
            return function()
                local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
                if okF and inFight then return end
                pcall(fn)
            end
        end
        time_ticker.AddTimerLoop(0, __lizardvipLobbyOnly(refreshAllFakeAccount), -1, 60.0)
        local ACC_POLL_SEC = 5.0
        local LIVE_SNAP_SEC = 3.0
        time_ticker.AddTimerOnce(0.05, function() pcall(loadLizardVipAccount) end)
        time_ticker.AddTimerLoop(0, __lizardvipLobbyOnly(loadLizardVipAccount), -1, ACC_POLL_SEC)
        local __lastAccSnap = nil
        local function writeAccSnap()
            pcall(function()
                local uid = ""
                local uc, bp, silver, ag, level = 0, 0, 0, 0, 0
                if DataMgr then
                    uc = lizardvipNum(DataMgr.ticket)
                    bp = lizardvipNum(DataMgr.gold)
                    silver = lizardvipNum(DataMgr.diamond)
                    ag = lizardvipNum(DataMgr.eternal_diamond)
                    if DataMgr.roleData then
                        level = lizardvipNum(DataMgr.roleData.level)
                        uid = tostring(DataMgr.roleData.uid or "")
                    end
                end
                local fa = _G.LizardVipFakeAccount
                if type(fa) == "table" then
                    if lizardvipNum(fa.uc) > 0 then uc = lizardvipNum(fa.uc) end
                    if lizardvipNum(fa.bp) > 0 then bp = lizardvipNum(fa.bp) end
                    if lizardvipNum(fa.silver) > 0 then silver = lizardvipNum(fa.silver) end
                    if lizardvipNum(fa.ag) > 0 then ag = lizardvipNum(fa.ag) end
                    if lizardvipNum(fa.level) > 0 then level = lizardvipNum(fa.level) end
                end
                local snap = string.format("%s|%d|%d|%d|%d|%d|", uid, uc, bp, silver, ag, level)

                if snap == __lastAccSnap then return end
                __lastAccSnap = snap

                _G.GTLModConfig = _G.GTLModConfig or {}
                _G.GTLModConfig.LizardVipAccSnap = snap
                if _G.SaveModSettings then pcall(_G.SaveModSettings) end
            end)
        end
        time_ticker.AddTimerOnce(0.08, writeAccSnap)
        time_ticker.AddTimerLoop(0, __lizardvipLobbyOnly(writeAccSnap), -1, LIVE_SNAP_SEC)
    end)

end

_G.LizardVipSetAccountField = function(field, n)
    field = string.lower(tostring(field or ""))
    n = lizardvipNum(n)
    if n < 0 then n = 0 end
    _G.LizardVipFakeAccount = _G.LizardVipFakeAccount or { uc = 0, bp = 0, silver = 0, ag = 0, level = 0 }
    if field == "uc" then
        _G.LizardVipFakeAccount.uc = n
    elseif field == "bp" then
        _G.LizardVipFakeAccount.bp = n
    elseif field == "silver" then
        _G.LizardVipFakeAccount.silver = n
    elseif field == "ag" or field == "gg" then
        _G.LizardVipFakeAccount.ag = n
    elseif field == "level" or field == "lvl" then
        _G.LizardVipFakeAccount.level = math.max(0, n)
    else
        return
    end
    _G.LizardVipAccountLocalSetAt = os.clock()
    pcall(refreshAllFakeAccount)
end

_G.LizardVipSetAccountBulk = function(uc, bp, silver, ag, level)
    _G.LizardVipFakeAccount = _G.LizardVipFakeAccount or { uc = 0, bp = 0, silver = 0, ag = 0, level = 0 }
    local fa = _G.LizardVipFakeAccount
    uc, bp, silver, ag, level = lizardvipNum(uc), lizardvipNum(bp), lizardvipNum(silver), lizardvipNum(ag), lizardvipNum(level)
    if (uc + bp + silver + ag + level) <= 0 then
        if type(_G.LizardVipClearFakeAccount) == "function" then pcall(_G.LizardVipClearFakeAccount) end
        return
    end

    if uc == 0 then uc = lizardvipNum(fa.uc) end
    if bp == 0 then bp = lizardvipNum(fa.bp) end
    if silver == 0 then silver = lizardvipNum(fa.silver) end
    if ag == 0 then ag = lizardvipNum(fa.ag) end
    if level == 0 then level = lizardvipNum(fa.level) end
    fa.uc = uc
    fa.bp = bp
    fa.silver = silver
    fa.ag = ag
    fa.level = math.max(0, level)
    _G.LizardVipAccountLocalSetAt = os.clock()
    pcall(refreshAllFakeAccount)
    pcall(function()
        local tt = require("common.time_ticker")
        if tt and tt.AddTimerOnce then
            tt.AddTimerOnce(0.05, function() pcall(refreshAllFakeAccount) end)
        end
    end)

    pcall(function()
        local tt = require("common.time_ticker")
        if tt and tt.AddTimerOnce then
            tt.AddTimerOnce(0.02, function() pcall(writeLizardVipAccountStateToShare) end)
        else
            pcall(writeLizardVipAccountStateToShare)
        end
    end)
end

_G.LizardVipSetFakeUC = function(n)
    _G.LizardVipSetAccountField("uc", n)
end

_G.LizardVipFakeAccount.uc = math.max(tonumber(_G.LizardVipFakeAccount.uc) or 0, DEFAULT_FAKE_UC)
setupLizardVipFakeAccount()
if M and M.later then
    M.later(0.5, setupLizardVipFakeAccount)
    M.later(2.0, setupLizardVipFakeAccount)
end
pcall(function()
    if type(_G.LizardVipSetFakeUC) == "function" then
        _G.LizardVipSetFakeUC(DEFAULT_FAKE_UC)
    end
end)

pcall(function()
    local RareMod = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.rare_item_get_module)
    if not RareMod or RareMod.__forceCongrats then return end
    RareMod.__forceCongrats = true
    RareMod.NeedShare = function(self, itemData)
        if not itemData then return false end
        local itemId = itemData.res_id or itemData.resid or itemData.itemid or 0
        if itemId == 0 then return false end
        local itemTb = CDataTable.GetTableData("Item", itemId)
        if not itemTb then return false end
        if (itemTb.NeedShare and itemTb.NeedShare ~= 0)
            or (itemTb.ItemQuality and itemTb.ItemQuality >= 6) then
            return true
        end
        return false
    end
end)

pcall(function()
    local LS = require("client.slua.logic.lobby_activity.logic_luckyback_activity")
    LS.SetIsShowAnimation(true)

    local function Spin_GetPersistDrawKey()
        return tostring(LS.activityId or 0)
    end

    local function Spin_LoadPersistedDraw()
        if not (M and M.loadConfig) then return 0, {} end
        M.loadConfig()
        CFG.luckyTotalDraw = CFG.luckyTotalDraw or {}
        CFG.luckyClaimed = CFG.luckyClaimed or {}
        local key = Spin_GetPersistDrawKey()
        local claimed = CFG.luckyClaimed[key] or {}
        return tonumber(CFG.luckyTotalDraw[key]) or 0, claimed
    end

    local function Spin_SavePersistedDraw(total, claimed)
        if not (M and M.loadConfig) then return end
        M.loadConfig()
        CFG.luckyTotalDraw = CFG.luckyTotalDraw or {}
        CFG.luckyClaimed = CFG.luckyClaimed or {}
        local key = Spin_GetPersistDrawKey()
        CFG.luckyTotalDraw[key] = tonumber(total) or 0
        CFG.luckyClaimed[key] = claimed or {}
        if M.saveConfigNow then M.saveConfigNow() end
    end

    local function Spin_SetTotalDrawTime(num)
        num = tonumber(num) or 0
        local pd = LS.playerData
        if not pd then return end
        pd.totalDrawTime = num
        LS.TotalSnatchTimes = LS.TotalSnatchTimes or {}
        if LS.activityId and LS.activityId ~= 0 then
            LS.TotalSnatchTimes[LS.activityId] = num
        end
    end

    local function Spin_CollectMilestoneDrops(box, outList)
        if not box or not box.AwardItems then return end
        for itemId, itemCount in pairs(box.AwardItems) do
            itemId = tonumber(itemId)
            itemCount = tonumber(itemCount) or 1
            if itemId and itemId > 0 then
                table.insert(outList, {
                    res_id = itemId,
                    resid = itemId,
                    count = itemCount,
                    valid_hours = tonumber(box.valid_hours) or 0,
                    expire_ts = 0,
                })
            end
        end
    end

    local function Spin_ClaimMilestones(autoShow, force)
        local pd = LS.playerData
        if not pd then return end
        local total = tonumber(pd.totalDrawTime) or 0
        local _, claimed = Spin_LoadPersistedDraw()
        claimed = claimed or {}
        local drops = {}
        local newly = {}

        local function scan(cfgList)
            if type(cfgList) ~= "table" then return end
            for _, box in ipairs(cfgList) do
                local need = tonumber(box.timesCount) or 0
                if need > 0 and total >= need then
                    local already = box.hasGet or claimed[tostring(need)]
                    if force or not already then
                        box.hasGet = true
                        claimed[tostring(need)] = true
                        Spin_CollectMilestoneDrops(box, drops)
                        table.insert(newly, need)
                    else
                        box.hasGet = true
                    end
                end
            end
        end

        scan(LS.totalDrawAwardConfig)
        scan(LS.newtotalDrawAwardConfig)

        Spin_SavePersistedDraw(total, claimed)

        if #drops > 0 then

            for _, d in ipairs(drops) do
                local id = tonumber(d.res_id or d.resid)
                if id and M.isAvatarFrame and M.isAvatarFrame(id) then
                    M.injectAvatarFrame(id)
                end
            end
            Spin_AddDropsToBag(drops)
            if autoShow then
                pcall(function()
                    local Logic_CommonItemGet = require("client.slua.logic.common.CommonItemGet.Logic_CommonItemGet")
                    Logic_CommonItemGet.ShowPanel_FullCustom(drops, { bSkipAnim = true })
                end)
            end
            pcall(function() LS.CloseRewardBox() end)
            EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_TAKE_CUMULATIVE_AWARD)
        end
        return drops
    end

    local function Spin_BumpTotalDraw(addCount, autoClaim)
        addCount = tonumber(addCount) or 0
        if addCount <= 0 then return end
        local pd = LS.playerData
        if not pd then return end

        local savedTotal = Spin_LoadPersistedDraw()
        local cur = math.max(tonumber(pd.totalDrawTime) or 0, savedTotal)
        local newTotal = cur + addCount
        Spin_SetTotalDrawTime(newTotal)

        pcall(function()
            local maxLuck = tonumber(LS.globalConfig and LS.globalConfig.maxLuckyValue) or 100
            local luck = tonumber(pd.curLuckyValue) or 0
            pd.curLuckyValue = math.min(maxLuck, luck + addCount)
            LS.curLuckyValue = pd.curLuckyValue
        end)

        local _, claimed = Spin_LoadPersistedDraw()
        Spin_SavePersistedDraw(newTotal, claimed)

        if autoClaim ~= false then
            Spin_ClaimMilestones(false)
        end

        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_STATUS_CHANGE)
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_REFRESH)
    end

    local function Spin_ReapplyPersistedProgress()
        local saved, claimed = Spin_LoadPersistedDraw()
        if saved > 0 then
            local cur = tonumber(LS.playerData and LS.playerData.totalDrawTime) or 0
            if saved > cur then
                Spin_SetTotalDrawTime(saved)
            end
        end
        local function mark(cfgList)
            if type(cfgList) ~= "table" then return end
            for _, box in ipairs(cfgList) do
                local need = tostring(box.timesCount or 0)
                if claimed[need] then box.hasGet = true end
            end
        end
        mark(LS.totalDrawAwardConfig)
        mark(LS.newtotalDrawAwardConfig)

        pcall(function() Spin_ClaimMilestones(false, true) end)
        pcall(function() if M and M.reapplyAvatarFrames then M.reapplyAvatarFrames() end end)

        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_STATUS_CHANGE)
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_REFRESH)
    end

    _G.AddOutfitSpinBumpTotalDraw = Spin_BumpTotalDraw
    _G.AddOutfitSpinReapplyProgress = Spin_ReapplyPersistedProgress

    LS.do_one_draw_back_by_activity_req = function(draw_type, coupon_id)
        local playerData = LS.playerData
        local price = (draw_type == 1) and (playerData.oneDrawFinalPrice or 40) or (playerData.tenDrawFinalPrice or 400)
        local itemCount = (draw_type == 1) and 1 or 10
        price = lizardvipNum(price)

        refreshTicket()
        spendFakeUC(price)
        Spin_ReapplyPersistedProgress()

        local pool = LS.poolItemConfig
        if not pool or #pool == 0 then
            return
        end

        local totalWeight = 0
        for _, v in ipairs(pool) do
            totalWeight = totalWeight + (v.award_weight or 1)
        end

        LS.dropList = {}
        LS.decomposeList = {}

        for i = 1, itemCount do
            local rand = math.random(1, math.max(1, totalWeight))
            local cumulative = 0
            local selected
            for _, v in ipairs(pool) do
                cumulative = cumulative + (v.award_weight or 1)
                if rand <= cumulative then
                    selected = v
                    break
                end
            end
            if not selected then selected = pool[#pool] end

            table.insert(LS.dropList, {
                res_id = selected.itemId,
                count = selected.itemCount or 1,
                valid_hours = 0,
                expire_ts = 0,
                pos_id = selected.posId,
                rankTitleType = 0,
                recommend_level = selected.recommendLevel or 0,
                chief_event_share_count_bak = 0,
                king_event_share_count_bak = 0,
            })
        end

        Spin_BumpTotalDraw(itemCount, true)

        Spin_AddDropsToBag(LS.dropList)

        if draw_type == 1 or #LS.dropList == 1 then
            EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_DARW_ONE_ANIMATION)
        else
            EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_DARW_TEN_ANIMATION)
        end

        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_STATUS_CHANGE)
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_REFRESH)

    end

    LS.get_sum_draw_award_by_activity_req = function(times)
        Spin_ReapplyPersistedProgress()
        local drops = Spin_ClaimMilestones(true)
        if not drops or #drops == 0 then

            local pd = LS.playerData
            local total = tonumber(pd and pd.totalDrawTime) or 0
            times = tonumber(times)
            if times and total >= times then
                for _, box in ipairs(LS.totalDrawAwardConfig or {}) do
                    if tonumber(box.timesCount) == times then
                        box.hasGet = false
                    end
                end
                Spin_ClaimMilestones(true)
            end
        end
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_STATUS_CHANGE)
        EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_LUCKYBACK_REFRESH)
    end

    if not LS.__persistProgressHooked then
        LS.__persistProgressHooked = true
        local origRsp = LS.get_lucky_draw_back_activity_rsp
        if type(origRsp) == "function" then
            LS.get_lucky_draw_back_activity_rsp = function(rs, cfg, myData, activityData)
                local r = origRsp(rs, cfg, myData, activityData)
                pcall(Spin_ReapplyPersistedProgress)
                return r
            end
        end
        local origDrawRsp = LS.do_one_draw_back_by_activity_rsp
        if type(origDrawRsp) == "function" then
            LS.do_one_draw_back_by_activity_rsp = function(...)
                local r = origDrawRsp(...)
                pcall(Spin_ReapplyPersistedProgress)
                return r
            end
        end
    end

    pcall(function()
        if M and M.later then
            M.later(2.0, Spin_ReapplyPersistedProgress)
            M.later(5.0, Spin_ReapplyPersistedProgress)
        end
    end)

    pcall(function()
        local Logic_CommonItemGet = require("client.slua.logic.common.CommonItemGet.Logic_CommonItemGet")
        if Logic_CommonItemGet.__spinBagHooked then return end
        Logic_CommonItemGet.__spinBagHooked = true
        local orig = Logic_CommonItemGet.ShowPanel_FullCustom
        Logic_CommonItemGet.ShowPanel_FullCustom = function(tAllItemData, tShowConfig)
            pcall(function()
                if type(tAllItemData) ~= "table" then return end
                local flat = {}
                local function collect(list)
                    if type(list) ~= "table" then return end
                    for _, v in pairs(list) do
                        if type(v) == "table" then
                            if v.res_id or v.resid or v.itemId then
                                table.insert(flat, v)
                            else
                                collect(v)
                            end
                        end
                    end
                end
                collect(tAllItemData)
                if next(flat) then Spin_AddDropsToBag(flat) end
            end)
            return orig(tAllItemData, tShowConfig)
        end
    end)

    pcall(function()
        if not M or M.__luckyPersistPayloadHooked then return end
        M.__luckyPersistPayloadHooked = true
        local oldBuild = M.buildSavePayload
        M.buildSavePayload = function()
            local out = oldBuild()
            M.loadConfig()
            if CFG.luckyTotalDraw and next(CFG.luckyTotalDraw) then
                out.luckyTotalDraw = CFG.luckyTotalDraw
            end
            if CFG.luckyClaimed and next(CFG.luckyClaimed) then
                out.luckyClaimed = CFG.luckyClaimed
            end
            if CFG.avatarFrames and #CFG.avatarFrames > 0 then
                out.avatarFrames = CFG.avatarFrames
            end
            return out
        end
        local oldApply = M.applyConfigTable
        M.applyConfigTable = function(data)
            local r = oldApply(data)
            if type(data) == "table" then
                if type(data.luckyTotalDraw) == "table" then
                    CFG.luckyTotalDraw = data.luckyTotalDraw
                end
                if type(data.luckyClaimed) == "table" then
                    CFG.luckyClaimed = data.luckyClaimed
                end
                if type(data.avatarFrames) == "table" then
                    CFG.avatarFrames = {}
                    for _, id in ipairs(data.avatarFrames) do
                        id = tonumber(id)
                        if id and id > 0 then table.insert(CFG.avatarFrames, id) end
                    end
                end
            end
            return r
        end
    end)

end)

pcall(function()

    if _G.__CrateFakeUCSpendVer == 2 then return end
    _G.__CrateFakeUCSpendVer = 2
    _G.__CrateFakeHooked = true
    pcall(function()
        local m = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
        if m then m.__crateFake = nil end
    end)
    pcall(function()
        local StoreHandler = require("client.network.Protocol.StoreHandler")
        StoreHandler.__crateFake = nil
    end)

    local function getCratePool(tabId)
        local pool = {}
        local info = StoreConst and StoreConst.supply_data and StoreConst.supply_data[tabId]
        if not info then

            if StoreConst and StoreConst.supply_data then
                for _, v in pairs(StoreConst.supply_data) do
                    if type(v) == "table" and v[StoreConst.label_shop_index_item_list] then
                        info = v
                        break
                    end
                end
            end
        end
        if not info then return pool end
        local rawList = info[StoreConst.label_shop_index_item_list]
        if not rawList then return pool end
        for _, v in pairs(rawList) do
            local itemId = tonumber(v[StoreConst.label_drop_index_item_id]) or 0
            if itemId > 0 then
                local chance = tonumber(v[StoreConst.label_drop_index_chance]) or 1
                if chance < 1 then chance = 1 end
                table.insert(pool, {
                    itemId = itemId,
                    count = tonumber(v[StoreConst.label_drop_index_item_num]) or 1,
                    weight = chance,
                })
            end
        end
        return pool
    end

    local function pickFromPool(pool)
        local total = 0
        for _, v in ipairs(pool) do
            total = total + (v.weight or 1)
        end
        if total < 1 then return pool[1] end
        local rand = math.random(1, total)
        local c = 0
        for _, v in ipairs(pool) do
            c = c + (v.weight or 1)
            if rand <= c then return v end
        end
        return pool[#pool]
    end

    local function extractUCCostFromObj(obj, depth)
        if type(obj) ~= "table" or (depth or 0) > 3 then return 0 end
        local preferKeys = {
            "needMoney", "need_money", "NeedMoney", "finalPrice", "final_price",
            "discountPrice", "discount_price", "realPrice", "real_price",
            "ucPrice", "uc_price", "payPrice", "pay_price", "afterCouponPrice",
            "couponPrice", "costMoney", "CostMoney", "price", "Price", "cost",
            "uc", "money", "Money", "onePrice", "one_price", "tenPrice", "ten_price",
            "price1", "price10", "buyPrice", "BuyPrice", "m_NeedMoney", "_needMoney",
            "m_price", "_price", "nPrice", "nNeedMoney",
        }
        for _, k in ipairs(preferKeys) do
            local v = tonumber(obj[k])
            if v and v > 0 and v < 1000000 then return lizardvipNum(v) end
        end
        for _, m in ipairs({ "GetNeedMoney", "GetPrice", "GetCost", "GetFinalPrice", "GetUCPrice", "GetPayPrice" }) do
            if type(obj[m]) == "function" then
                local ok, v = pcall(obj[m], obj)
                v = tonumber(v)
                if ok and v and v > 0 and v < 1000000 then return lizardvipNum(v) end
            end
        end

        for k, v in pairs(obj) do
            local ks = string.lower(tostring(k))
            local n = tonumber(v)
            if n and n > 0 and n < 1000000 then
                if ks:find("need", 1, true) or ks:find("price", 1, true)
                    or ks:find("cost", 1, true) or ks:find("money", 1, true)
                    or ks:find("uc", 1, true) or ks:find("pay", 1, true) then
                    return lizardvipNum(n)
                end
            end
        end
        if type(obj.paymentData) == "table" then
            local c = extractUCCostFromObj(obj.paymentData, (depth or 0) + 1)
            if c > 0 then return c end
        end
        if type(obj.buyInfo) == "table" then
            local c = extractUCCostFromObj(obj.buyInfo, (depth or 0) + 1)
            if c > 0 then return c end
        end
        if type(obj.priceInfo) == "table" then
            local c = extractUCCostFromObj(obj.priceInfo, (depth or 0) + 1)
            if c > 0 then return c end
        end
        return 0
    end

    local function captureSupplyUCCost(obj, ...)
        local cost = extractUCCostFromObj(obj, 0)
        if cost <= 0 then
            for i = 1, select("#", ...) do
                local a = select(i, ...)
                if type(a) == "number" and a > 0 and a < 1000000 then
                    cost = lizardvipNum(a)
                    break
                elseif type(a) == "table" then
                    cost = extractUCCostFromObj(a, 0)
                    if cost > 0 then break end
                end
            end
        end
        if cost > 0 then
            _G.__LastSupplyUCCost = cost
        end
        return cost
    end

    local function priceFromSupplyData(tabId, openCount)
        local cost = 0
        pcall(function()
            if not StoreConst or not StoreConst.supply_data then return end
            local info = StoreConst.supply_data[tabId]
            if type(info) ~= "table" then return end
            local sc = StoreConst
            local one = tonumber(
                info[sc.label_shop_index_price]
                or info[sc.label_shop_index_one_price]
                or info.one_price or info.onePrice or info.price
                or info.uc_price or info.discount_price or info.finalPrice
            ) or 0
            local ten = tonumber(
                info[sc.label_shop_index_ten_price]
                or info[sc.label_shop_index_price_ten]
                or info.ten_price or info.tenPrice or info.price10
                or info.ten_uc_price or info.tenDiscountPrice
            ) or 0
            if openCount == 10 then
                cost = ten > 0 and ten or (one > 0 and one * 10 or 0)
            else
                cost = one > 0 and one or 0
            end
            if cost <= 0 then
                cost = extractUCCostFromObj(info, 0)
            end
        end)
        return lizardvipNum(cost)
    end

    local function getSupplyUI()
        local ui = nil
        pcall(function()
            local cfg = UIManager and UIManager.UI_Config
            if not cfg then return end
            local names = {
                "SupplyGeneralPage", "NewSupplyGeneralPage", "SupplyCratePage",
                "StoreSupplyPage", "SupplyMainPage", "NewStoreSupplyPage",
            }
            for _, name in ipairs(names) do
                if cfg[name] then
                    local u = UIManager.GetUI(cfg[name])
                    if u then ui = u return end
                end
            end
            if cfg.SupplyGeneralPage then
                ui = UIManager.GetUI(cfg.SupplyGeneralPage)
            end
        end)
        return ui
    end

    local function collectPricesFromNode(node, depth, oneRef, tenRef)
        if depth > 5 or node == nil then return end
        local t = type(node)
        if t ~= "table" and t ~= "userdata" then return end

        local function takeText(keyName, obj)
            if type(obj) ~= "table" and type(obj) ~= "userdata" then return end
            if type(obj.GetText) ~= "function" then return end
            local ok, text = pcall(obj.GetText, obj)
            if not ok or type(text) ~= "string" then return end
            local n = tonumber((tostring(text):gsub(",", ""):gsub("%s", ""):match("(%d+)")))
            if not n or n <= 0 or n >= 100000 then return end
            local ks = string.lower(tostring(keyName or ""))

            if ks:find("ticket", 1, true) or ks:find("balance", 1, true)
                or ks:find("own", 1, true) or ks:find("have", 1, true)
                or ks:find("total", 1, true) or ks:find("account", 1, true)
                or ks:find("diamond", 1, true) then
                return
            end
            local bal = getFakeUC()
            if n == bal or (DataMgr and n == tonumber(DataMgr.ticket)) then return end

            if (ks:find("ten", 1, true) or ks:find("10", 1, true) or ks:find("multi", 1, true))
                and (ks:find("price", 1, true) or ks:find("cost", 1, true) or ks:find("money", 1, true) or ks:find("uc", 1, true)) then
                if tenRef[1] <= 0 then tenRef[1] = lizardvipNum(n) end
            elseif (ks:find("one", 1, true) or ks:find("once", 1, true) or ks:find("single", 1, true))
                and (ks:find("price", 1, true) or ks:find("cost", 1, true) or ks:find("money", 1, true) or ks:find("uc", 1, true)) then
                if oneRef[1] <= 0 then oneRef[1] = lizardvipNum(n) end
            elseif ks:find("price", 1, true) or ks:find("cost", 1, true) then
                if n >= 50 and tenRef[1] <= 0 then
                    tenRef[1] = lizardvipNum(n)
                elseif oneRef[1] <= 0 then
                    oneRef[1] = lizardvipNum(n)
                end
            end
        end

        if t == "table" then
            for k, v in pairs(node) do
                local ks = string.lower(tostring(k))
                local n = tonumber(v)
                if n and n > 0 and n < 1000000 then
                    if ks:find("ten", 1, true) and (ks:find("price", 1, true) or ks:find("uc", 1, true) or ks:find("cost", 1, true)) then
                        if tenRef[1] <= 0 then tenRef[1] = lizardvipNum(n) end
                    elseif (ks:find("one", 1, true) or ks:find("once", 1, true) or ks:find("single", 1, true))
                        and (ks:find("price", 1, true) or ks:find("uc", 1, true) or ks:find("cost", 1, true) or ks == "price") then
                        if oneRef[1] <= 0 then oneRef[1] = lizardvipNum(n) end
                    end
                end
                takeText(k, v)
                if type(v) == "table" or type(v) == "userdata" then
                    pcall(collectPricesFromNode, v, depth + 1, oneRef, tenRef)
                end
            end
        end
    end

    local function priceFromSupplyUI(openCount)
        local cost = 0
        pcall(function()
            local ui = getSupplyUI()
            if not ui then return end

            local one = lizardvipNum(ui.onePrice or ui.oneBuyPrice or ui.price1 or ui.one_price
                or ui.curOnePrice or ui.oncePrice or ui.price)
            local ten = lizardvipNum(ui.tenPrice or ui.tenBuyPrice or ui.price10 or ui.ten_price
                or ui.curTenPrice or ui.multiPrice)

            if type(ui.data) == "table" then
                local d = ui.data
                if one <= 0 then one = lizardvipNum(d.onePrice or d.one_price or d.price1 or d.price or extractUCCostFromObj(d, 0)) end
                if ten <= 0 then ten = lizardvipNum(d.tenPrice or d.ten_price or d.price10 or 0) end
            end

            local oneRef, tenRef = { one }, { ten }
            pcall(collectPricesFromNode, ui, 0, oneRef, tenRef)
            one, ten = oneRef[1], tenRef[1]

            if openCount == 10 then
                cost = ten > 0 and ten or (one > 0 and one * 10 or 0)
            else
                cost = one > 0 and one or 0
            end
            if cost <= 0 then
                cost = extractUCCostFromObj(ui, 0)
            end
        end)
        return lizardvipNum(cost)
    end

    local function resolveCrateUCCost(buyInfo, openCount, tabId)
        local cost = lizardvipNum(_G.__LastSupplyUCCost)
        if cost > 0 then return cost end

        cost = extractUCCostFromObj(buyInfo, 0)
        if cost > 0 then return cost end

        pcall(function()
            if type(buyInfo) ~= "table" or not StoreConst then return end
            local keys = {
                StoreConst.label_buy_param_price,
                StoreConst.label_buy_param_uc,
                StoreConst.label_buy_param_cost,
                StoreConst.label_buy_param_money,
                StoreConst.label_buy_param_final_price,
                "price", "uc", "cost", "needMoney", "finalPrice", "money",
            }
            for _, k in ipairs(keys) do
                if k ~= nil then
                    local v = tonumber(buyInfo[k])
                    if v and v > 0 then cost = lizardvipNum(v) break end
                end
            end
        end)
        if cost > 0 then return cost end

        cost = priceFromSupplyData(tabId, openCount)
        if cost > 0 then return cost end

        cost = priceFromSupplyUI(openCount)
        return cost
    end

    local function fakeCrateOpen(buyInfo, isTenBuy)
        pcall(refreshTicket)
        buyInfo = buyInfo or {}

        local tabId = buyInfo[StoreConst.label_buy_param_tab_id]
            or buyInfo[StoreConst.label_buy_param_id]
            or buyInfo[1]
        local openCount = tonumber(buyInfo[StoreConst.label_buy_param_count]) or 1
        if isTenBuy == true or openCount == 10 then
            openCount = 10
        else
            openCount = 1
        end

        local pool = getCratePool(tabId)
        if not pool or #pool == 0 then

            pcall(function()
                local ui = UIManager.GetUI(UIManager.UI_Config.SupplyGeneralPage)
                if ui and ui.itemDataList then
                    for _, it in pairs(ui.itemDataList) do
                        if it.itemId then
                            table.insert(pool, {
                                itemId = it.itemId,
                                count = it.num or 1,
                                weight = it.rate or 1,
                            })
                        end
                    end
                end
            end)
        end

        if not pool or #pool == 0 then
            return
        end

        local cost = resolveCrateUCCost(buyInfo, openCount, tabId)
        if cost > 0 then
            spendFakeUC(cost)
            _G.__LastSupplyUCCost = 0
        else
            local dump = {}
            pcall(function()
                for k, v in pairs(buyInfo) do
                    dump[#dump + 1] = tostring(k) .. "=" .. tostring(v)
                    if #dump >= 12 then break end
                end
            end)
        end

        local item_list = {}
        local bagList = {}
        for i = 1, openCount do
            local sel = pickFromPool(pool)
            table.insert(item_list, {
                itemid = sel.itemId,
                count = sel.count or 1,
                valid_hours = 0,
            })
            table.insert(bagList, {
                res_id = sel.itemId,
                count = sel.count or 1,
            })
        end

        Spin_AddDropsToBag(bagList)

        pcall(function()
            local ShopSystem = require("client.logic.shop.logic_shop")
            ShopSystem.on_open_pandora_chest_rsp(item_list, {}, { shop_count = openCount })
        end)

        pcall(function()
            EventSystem:postEvent(EVENTTYPE_STORE_DATA, EVENTID_SUPPLY_BUY, tabId, {}, nil)
        end)

    end

    pcall(function()
        local payment_uc = require("client.slua.logic.supply.supply_payment.playment_type.payment_uc")
        payment_uc.CheckEnough = function(self, ...)
            captureSupplyUCCost(self, ...)
            return true
        end
        payment_uc.PopupPaymentTips = function(self, ...)
            captureSupplyUCCost(self, ...)

            self:ExecutionPayment()
        end
        if not payment_uc.__lizardvipExecHooked and type(payment_uc.ExecutionPayment) == "function" then
            payment_uc.__lizardvipExecHooked = true
            local origExec = payment_uc.ExecutionPayment
            payment_uc.ExecutionPayment = function(self, ...)
                captureSupplyUCCost(self, ...)
                return origExec(self, ...)
            end
        end
    end)

    pcall(function()
        local store_supply_manager = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
        if not store_supply_manager or store_supply_manager.__crateFake then return end
        store_supply_manager.__crateFake = true
        local orig = store_supply_manager.buy_shop_by_id_req
        store_supply_manager.buy_shop_by_id_req = function(self, params, isTenBuy)
            refreshTicket()
            fakeCrateOpen(params or {}, isTenBuy)

        end
    end)

    pcall(function()
        local StoreHandler = require("client.network.Protocol.StoreHandler")
        if StoreHandler.__crateFake then return end
        StoreHandler.__crateFake = true
        StoreHandler.send_buy_shop_by_id_req = function(params, isTenBuy)
            refreshTicket()
            fakeCrateOpen(params or {}, isTenBuy)
        end
    end)

end)

function rebindAddOutfit()
    local A = rawget(_G, "AddOutfit")
    if type(A) ~= "table" or type(A.injectOne) ~= "function" then return false end
    M = A
    if type(rawget(_G, "AddOutfitCfg")) == "table" then
        CFG = _G.AddOutfitCfg
    end
    return true
end
if type(M.injectOne) ~= "function" then
    M.later(1.0, rebindAddOutfit)
    M.later(3.0, rebindAddOutfit)
    M.later(8.0, rebindAddOutfit)
end

_G.__LOCAL_CRATE_SPIN_FROM_SKINS__ = true

end)

end

do

pcall(function()

_G.FAKE_LEVEL = 99999
_G.FAKE_DAN = 99999
_G.FAKE_LEVEL_NAME = _G.FAKE_LEVEL_NAME or "Collection Champion"
_G.FAKE_SCORE = 999999999999

if _G.__COLLECT_FAKE_LOADED then
    return
end
_G.__COLLECT_FAKE_LOADED = true

function hook_collect_handler()
    local handler = package.loaded["client.network.Protocol.CollectHandler"] or package.loaded["CollectHandler"]
    if not handler and not rawget(package.loaded, "client.network.Protocol.CollectHandler") then
        pcall(require, "client.network.Protocol.CollectHandler")
    end

    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.on_get_collect_sys_main_data_rsp and not rawget(mod, "_collection_handler_hooked") then
            rawset(mod, "_collection_handler_hooked", true)
            local orig = mod.on_get_collect_sys_main_data_rsp

            mod.on_get_collect_sys_main_data_rsp = function(err_code, collect_data, param)
                if collect_data and type(collect_data) == "table" then
                    rawset(collect_data, "total_score", _G.FAKE_SCORE)
                    rawset(collect_data, "cur_season_collect_score", _G.FAKE_SCORE)
                    local ss = rawget(collect_data, "season_score")
                    if type(ss) == "table" then
                        for k in pairs(ss) do ss[k] = _G.FAKE_SCORE end
                    else
                        rawset(collect_data, "season_score", { [1] = _G.FAKE_SCORE, [2] = _G.FAKE_SCORE })
                    end
                end
                return orig(err_code, collect_data, param)
            end
            return true
        end
    end
    return false
end

function hook_module_manager()
    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.GetModule and mod.LobbyModuleConfig and mod.LobbyModuleConfig.collect_module and not rawget(mod, "_collection_getmodule_hooked") then
            rawset(mod, "_collection_getmodule_hooked", true)
            local orig_get = mod.GetModule
            local collect_key = mod.LobbyModuleConfig.collect_module

            mod.GetModule = function(self, name)
                local inst = orig_get(self, name)
                if inst and name == collect_key then
                    patch_collect_module(inst)
                    inject_collect_data()
                end
                return inst
            end
            return true
        end
    end
    return false
end

function get_collect_module()
    local ModuleManager = _G.ModuleManager
    if not ModuleManager then
        for _, mod in pairs(package.loaded or {}) do
            if type(mod) == "table" and mod.GetModule and mod.LobbyModuleConfig and mod.LobbyModuleConfig.collect_module then
                ModuleManager = mod
                break
            end
        end
    end

    if ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig then
        local ok, cm = pcall(ModuleManager.GetModule, ModuleManager, ModuleManager.LobbyModuleConfig.collect_module)
        if ok and cm then return cm end
    end

    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.GetLevelDataByScore and mod.GetSeasonLevelByScore then
            return mod
        end
    end
    return nil
end

function patch_collect_module(mod)
    if not mod or rawget(mod, "_collection_level_patched") then return false end
    rawset(mod, "_collection_level_patched", true)

    if mod.GetLevelDataByScore then
        rawset(mod, "GetLevelDataByScore", function(self, score, isSeason)
            return _G.FAKE_LEVEL, _G.FAKE_LEVEL_NAME, _G.FAKE_DAN
        end)
    end

    if mod.GetSeasonLevelByScore then
        rawset(mod, "GetSeasonLevelByScore", function(self, score, seasonId)
            return _G.FAKE_LEVEL, true, _G.FAKE_LEVEL_NAME
        end)
    end

    if mod.GetCollectScoreByCollectData then
        rawset(mod, "GetCollectScoreByCollectData", function(self, collect_data)
            return _G.FAKE_SCORE, _G.FAKE_SCORE
        end)
    end

    local collect_data = rawget(mod, "collect_data")
    if collect_data and type(collect_data) == "table" then
        rawset(collect_data, "total_score", _G.FAKE_SCORE)
        if not rawget(collect_data, "season_score") then rawset(collect_data, "season_score", {}) end
        local season = (rawget(mod, "GetSeasonId") and mod:GetSeasonId()) or 1
        collect_data.season_score[season] = _G.FAKE_SCORE
        rawset(collect_data, "cur_season_collect_score", _G.FAKE_SCORE)
    end

    if rawget(mod, "OnGetMainData") or mod.OnGetMainData then
        local orig_on_get = rawget(mod, "OnGetMainData") or mod.OnGetMainData
        rawset(mod, "OnGetMainData", function(self, err_code, data, param)
            if data and type(data) == "table" then
                rawset(data, "total_score", _G.FAKE_SCORE)
                if not rawget(data, "season_score") then rawset(data, "season_score", {}) end
                local season = (rawget(self, "GetSeasonId") and self:GetSeasonId()) or 1
                if type(data.season_score) == "table" then
                    data.season_score[season] = _G.FAKE_SCORE
                end
                rawset(data, "cur_season_collect_score", _G.FAKE_SCORE)
            end
            orig_on_get(self, err_code, data, param)
        end)
    end

    return true
end

function inject_collect_data()
    pcall(function()
        local cm = get_collect_module()
        if cm then
            local collect_data = rawget(cm, "collect_data")
            if collect_data and type(collect_data) == "table" then
                rawset(collect_data, "total_score", _G.FAKE_SCORE)
                if not rawget(collect_data, "season_score") then rawset(collect_data, "season_score", {}) end
                local season = (rawget(cm, "GetSeasonId") and cm:GetSeasonId()) or 1
                if type(collect_data.season_score) == "table" then
                    collect_data.season_score[season] = _G.FAKE_SCORE
                end
                rawset(collect_data, "cur_season_collect_score", _G.FAKE_SCORE)
            end
        end
    end)

    pcall(function()
        if _G.DataMgr and _G.DataMgr.roleData then
            if not _G.DataMgr.roleData.brief_collect_data then _G.DataMgr.roleData.brief_collect_data = {} end
            _G.DataMgr.roleData.brief_collect_data.total_score = _G.FAKE_SCORE
            _G.DataMgr.roleData.brief_collect_data.cur_season_collect_score = _G.FAKE_SCORE
        end
    end)
end

function hook_collect_road_ui()
    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.ShowCollect and mod.ShowSeasonCollect and not rawget(mod, "_collection_road_hooked") then
            rawset(mod, "_collection_road_hooked", true)
            local orig_show = mod.ShowCollect

            if orig_show then
                rawset(mod, "ShowCollect", function(self)
                    local mm = _G.ModuleManager
                    if not mm then
                        for _, m in pairs(package.loaded or {}) do
                            if type(m) == "table" and m.GetModule and m.LobbyModuleConfig then
                                mm = m
                                break
                            end
                        end
                    end

                    if mm and mm.LobbyModuleConfig and mm.LobbyModuleConfig.collect_module then
                        local ok, cm = pcall(mm.GetModule, mm, mm.LobbyModuleConfig.collect_module)
                        if ok and cm and rawget(cm, "collect_data") then
                            local cd = rawget(cm, "collect_data")
                            if type(cd) == "table" then
                                rawset(cd, "total_score", _G.FAKE_SCORE)
                                if not rawget(cd, "season_score") then rawset(cd, "season_score", {}) end
                                cd.season_score[(rawget(cm, "GetSeasonId") and cm:GetSeasonId()) or 1] = _G.FAKE_SCORE
                                rawset(cd, "cur_season_collect_score", _G.FAKE_SCORE)
                            end
                        end
                    end
                    return orig_show(self)
                end)
            end
            return true
        end
    end
    return false
end

function install_collect_hooks()
    hook_collect_handler()
    hook_module_manager()
    hook_collect_road_ui()

    for path, mod in pairs(package.loaded or {}) do
        if type(mod) == "table" and mod.GetLevelDataByScore and mod.GetSeasonLevelByScore and not rawget(mod, "_collection_level_patched") then
            patch_collect_module(mod)
        end
    end

    local cm = get_collect_module()
    if cm then
        patch_collect_module(cm)
    end
    inject_collect_data()

end

_G.CollectFake = {
    Apply = function()
        install_collect_hooks()
    end,
    SetLevel = function(n)
        _G.FAKE_LEVEL = tonumber(n) or _G.FAKE_LEVEL
        install_collect_hooks()
        return _G.FAKE_LEVEL
    end,
    SetName = function(name)
        _G.FAKE_LEVEL_NAME = tostring(name) or _G.FAKE_LEVEL_NAME
    end,
    SetScore = function(n)
        _G.FAKE_SCORE = tonumber(n) or _G.FAKE_SCORE
        install_collect_hooks()
        return _G.FAKE_SCORE
    end,
    SetDan = function(n)
        _G.FAKE_DAN = tonumber(n) or _G.FAKE_DAN
    end,
}

if _G.Mytimer_ticker then

    _G.Mytimer_ticker.AddTimer(3, function()
        install_collect_hooks()
    end)

    if _G.__loopGuard28011 and _G.Mytimer_ticker.IsRunning and _G.Mytimer_ticker.IsRunning(_G.__loopGuard28011) then _G.Mytimer_ticker.RemoveTimer(_G.__loopGuard28011) end
    _G.__loopGuard28011 =     _G.Mytimer_ticker.AddTimerLoop(3, function()

        local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
        if okF and inFight then return end
        pcall(inject_collect_data)
    end, -1, 10)

    if _G.__loopGuard28016 and _G.Mytimer_ticker.IsRunning and _G.Mytimer_ticker.IsRunning(_G.__loopGuard28016) then _G.Mytimer_ticker.RemoveTimer(_G.__loopGuard28016) end
    _G.__loopGuard28016 =     _G.Mytimer_ticker.AddTimerLoop(5, function()

        local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
        if okF and inFight then return end
        pcall(install_collect_hooks)
    end, -1, 1)
else

    install_collect_hooks()
end

end)

end

do

if not _G.__PHOENIXTRA_SUMMON_LOADED__ then
    _G.__PHOENIXTRA_SUMMON_LOADED__ = true

    local PhoenixtraSummon = {}

    PhoenixtraSummon.XSUIT_ID = 1407856

    PhoenixtraSummon.PERIOD = 6

    PhoenixtraSummon.FALLBACK_TEMPLATE_ID = 1407841

    PhoenixtraSummon.CALL_ACTION_ID = 12219843

    PhoenixtraSummon.CALL_STATUE_SEQ = nil

    PhoenixtraSummon.CALL_TIME = 7

    PhoenixtraSummon.BYPASS_7STAR_CHECK = true

    PhoenixtraSummon.FORCE_WEAR_IN_MATCH = true

    PhoenixtraSummon.PLAY_LOCAL_SEQUENCE = true

    PhoenixtraSummon.DEBUG = false

    PhoenixtraSummon.AUTO_INSTALL = true

    PhoenixtraSummon._dataHooked = false
    PhoenixtraSummon._menuHooked = false
    PhoenixtraSummon._platformHooked = false
    PhoenixtraSummon._tipsHooked = false
    PhoenixtraSummon._gameTipsHooked = false
    PhoenixtraSummon._resolvedEffect = nil
    PhoenixtraSummon._origGetTableData = nil
    PhoenixtraSummon._origGetTable = nil
    PhoenixtraSummon._origRequire = nil
    PhoenixtraSummon._lastSummonParam = nil
    PhoenixtraSummon._eventsHooked = false
    PhoenixtraSummon._summonCooldownUntil = 0
    PhoenixtraSummon._lastInstallState = nil

    local PLATFORM_MODULE = "GameLua.Activity.Commercialize.Actor.InteractActor.XSuitPlatform"

    local XSUIT_ALIAS = {
        [1405870] = 1407895,
    }
    local function resolveXSuitAlias(id)
        id = tonumber(id)
        if id and XSUIT_ALIAS[id] then return XSUIT_ALIAS[id] end
        return id
    end

    local readBattleEffect

    function PhoenixtraSummon.DetectWornXSuit()
        local found = nil
        pcall(function()
            local ModuleManager = require("client.module_framework.ModuleManager")
            local myUid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
            if not (ModuleManager and myUid) then return end
            local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
            local d = BD and BD.GetCacheData and BD:GetCacheData(myUid)
            local list = d and d.WearInfoList
            if type(list) ~= "table" then return end
            for _, e in ipairs(list) do
                local id = e and tonumber(e.ItemID)
                if id and id > 0 and readBattleEffect(id) then
                    found = id
                    break
                end
            end
        end)
        return found
    end

    function PhoenixtraSummon.UpdateFromConfig()

        if _G.SuitSkin and _G.SuitSkin ~= 0 then
            local targetId = resolveXSuitAlias(_G.SuitSkin)
            if PhoenixtraSummon.XSUIT_ID ~= targetId then
                PhoenixtraSummon.XSUIT_ID = targetId
                PhoenixtraSummon._resolvedEffect = nil
                log("XSUIT_ID updated from SuitSkin: " .. tostring(PhoenixtraSummon.XSUIT_ID))
            end

        elseif lastConfig and lastConfig.SHIRT then
            local targetId = resolveXSuitAlias(lastConfig.SHIRT)
            if PhoenixtraSummon.XSUIT_ID ~= targetId then
                PhoenixtraSummon.XSUIT_ID = targetId
                PhoenixtraSummon._resolvedEffect = nil
                log("XSUIT_ID updated from lastConfig.SHIRT: " .. tostring(PhoenixtraSummon.XSUIT_ID))
            end
        else

            local wornId = PhoenixtraSummon.DetectWornXSuit()
            wornId = wornId and resolveXSuitAlias(wornId) or nil
            if wornId and PhoenixtraSummon.XSUIT_ID ~= wornId then
                PhoenixtraSummon.XSUIT_ID = wornId
                PhoenixtraSummon._resolvedEffect = nil
                log("XSUIT_ID updated from worn suit: " .. tostring(PhoenixtraSummon.XSUIT_ID))
            end
        end
        return PhoenixtraSummon.XSUIT_ID
    end

    local function hasMethod(obj, name)
        if not obj then return false end
        local v = obj[name]
        if v == nil then return false end
        local t = type(v)
        return t == "function" or t == "userdata" or t == "table"
    end

    local function getOwnerName(owner)
        local ok, name = pcall(function()
            local KismetSystemLibrary = import("KismetSystemLibrary")
            return KismetSystemLibrary.GetObjectName(owner)
        end)
        if ok and name then
            return tostring(name)
        end
        return tostring(owner)
    end

    local function isReadyState()
        local gs = slua_GameFrontendHUD and slua_GameFrontendHUD.GetGameState and slua_GameFrontendHUD:GetGameState()
        if slua.isValid(gs) and gs.GetGameModeState then
            return gs:GetGameModeState() == "ReadyState"
        end
        return false
    end

    local function log(msg)
        if PhoenixtraSummon.DEBUG then
        end
    end

    local function safeRequire(path)
        local ok, mod = pcall(require, path)
        if ok then return mod end
        return nil
    end

    local function shallowCopy(src)
        if type(src) ~= "table" then return src end
        local dst = {}
        for k, v in pairs(src) do dst[k] = v end
        return dst
    end

    local function rawGetTableData(tableName, key)
        if PhoenixtraSummon._origGetTableData then
            return PhoenixtraSummon._origGetTableData(tableName, key)
        end
        if CDataTable and CDataTable.GetTableData then
            return CDataTable.GetTableData(tableName, key)
        end
        return nil
    end

    local function rawGetTable(tableName)
        if PhoenixtraSummon._origGetTable then
            return PhoenixtraSummon._origGetTable(tableName)
        end
        if CDataTable and CDataTable.GetTable then
            return CDataTable.GetTable(tableName)
        end
        return nil
    end

    readBattleEffect = function(itemID)
        itemID = tonumber(itemID)
        if not itemID or itemID <= 0 then return nil end
        local row = rawGetTableData("GoldClothBattleEffect", itemID)
        if row and row.CallStatue and row.CallStatue ~= "" then
            return row
        end
        return nil
    end

    function PhoenixtraSummon.ResolveEffectConfig()
        if PhoenixtraSummon._resolvedEffect then
            return PhoenixtraSummon._resolvedEffect
        end
        local native = readBattleEffect(PhoenixtraSummon.XSUIT_ID)
        if native then
            PhoenixtraSummon._resolvedEffect = shallowCopy(native)
            PhoenixtraSummon._resolvedEffect.ID = PhoenixtraSummon.XSUIT_ID
            log("native CallStatue ok for " .. tostring(PhoenixtraSummon.XSUIT_ID))
            return PhoenixtraSummon._resolvedEffect
        end
        local template = readBattleEffect(PhoenixtraSummon.FALLBACK_TEMPLATE_ID)
        if not template then
            local tbl = rawGetTable("GoldClothBattleEffect")
            if tbl then
                for _, row in pairs(tbl) do
                    if row and row.CallStatue and row.CallStatue ~= "" then
                        template = row
                        break
                    end
                end
            end
        end
        PhoenixtraSummon._resolvedEffect = template and shallowCopy(template) or {}
        PhoenixtraSummon._resolvedEffect.ID = PhoenixtraSummon.XSUIT_ID
        PhoenixtraSummon._resolvedEffect.Level = 7
        PhoenixtraSummon._resolvedEffect.CallTime = PhoenixtraSummon._resolvedEffect.CallTime or PhoenixtraSummon.CALL_TIME
        if PhoenixtraSummon.CALL_STATUE_SEQ and PhoenixtraSummon.CALL_STATUE_SEQ ~= "" then
            PhoenixtraSummon._resolvedEffect.CallStatue = PhoenixtraSummon.CALL_STATUE_SEQ
        end
        log("CallStatue=" .. tostring(PhoenixtraSummon._resolvedEffect.CallStatue or ""))
        return PhoenixtraSummon._resolvedEffect
    end

    function PhoenixtraSummon.BuildInjectedBattleEffectRow(existing)
        local cfg = PhoenixtraSummon.ResolveEffectConfig()
        local row = shallowCopy(existing or cfg)
        row.ID = PhoenixtraSummon.XSUIT_ID
        row.Level = 7
        row.CallStatue = cfg.CallStatue or row.CallStatue or ""
        row.CallTime = cfg.CallTime or row.CallTime or PhoenixtraSummon.CALL_TIME
        return row
    end

    function PhoenixtraSummon.InstallDataTableHooks()
        if PhoenixtraSummon._dataHooked or not CDataTable or not CDataTable.GetTableData then
            return PhoenixtraSummon._dataHooked
        end
        PhoenixtraSummon._origGetTableData = CDataTable.GetTableData
        PhoenixtraSummon._origGetTable = CDataTable.GetTable
        function CDataTable.GetTableData(tableName, key, ...)
            local row = PhoenixtraSummon._origGetTableData(tableName, key, ...)
            if tableName == "GoldClothBattleEffect" and tonumber(key) == PhoenixtraSummon.XSUIT_ID then
                return PhoenixtraSummon.BuildInjectedBattleEffectRow(row)
            end

            return row
        end
        PhoenixtraSummon._dataHooked = true
        log("CDataTable hooked")
        return true
    end

    function PhoenixtraSummon.RegisterLogicXSuitItem()
        local LogicXSuit = safeRequire("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return false end
        pcall(function()
            if LogicXSuit.InitXSuitItemList and not LogicXSuit.bItemInfoInited then
                LogicXSuit.InitXSuitItemList()
            end
        end)
        LogicXSuit.itemInfoList = LogicXSuit.itemInfoList or {}

        LogicXSuit.itemInfoList[PhoenixtraSummon.XSUIT_ID] = {period = PhoenixtraSummon.PERIOD, level = 7}
        LogicXSuit.bItemInfoInited = true
        log("LogicXSuit registered for ID " .. tostring(PhoenixtraSummon.XSUIT_ID))
        return true
    end

    function PhoenixtraSummon.IsXSuitPlatformActor(owner)
        if not owner or not slua.isValid(owner) then return false end

        if hasMethod(owner, "TriggerCallShowSequence") and hasMethod(owner, "GetStatue") then
            return true
        end
        if hasMethod(owner, "Wearing7StarXSuit") and hasMethod(owner, "TrySetCurrentCaller") then
            return true
        end
        local name = getOwnerName(owner):lower()
        if name:find("xsuitplatform") or name:find("xsuit_platform") or name:find("goldsuitplatform") then
            return true
        end
        return false
    end

    function PhoenixtraSummon.ForceWearNow()

        if not PhoenixtraSummon.FORCE_WEAR_IN_MATCH then return false end

        local okF, inFight = pcall(function()
            return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus()
        end)
        if not (okF and inFight) then return false end
        local GameplayData = safeRequire("GameLua.GameCore.Data.GameplayData")
        if not GameplayData then return false end
        local character = GameplayData.GetPlayerCharacter and GameplayData.GetPlayerCharacter()
        if not slua.isValid(character) then return false end
        if slua.isValid(character.CharacterAvatarComp2_BP) then
            character.CharacterAvatarComp2_BP.GoldenSuitItemID = PhoenixtraSummon.XSUIT_ID
            character.CharacterAvatarComp2_BP.XSuitItemID = PhoenixtraSummon.XSUIT_ID
        end
        return true
    end

    function PhoenixtraSummon.BlockTip49553(tipsID)

        return PhoenixtraSummon.BYPASS_7STAR_CHECK and tonumber(tipsID) == 49553
    end

    function PhoenixtraSummon.InstallTipsHooks()

        if not PhoenixtraSummon._tipsHooked then
            local tips = safeRequire("GameLua.Mod.BaseMod.Common.UI.InGameTipsTools")
            if tips and type(tips.BattleNormalTipsByTextID) == "function" and not tips.__phoenixtra_patched then
                local orig = tips.BattleNormalTipsByTextID
                tips.BattleNormalTipsByTextID = function(tipsID, ...)
                    if PhoenixtraSummon.BlockTip49553(tipsID) then
                        log("blocked BattleNormalTips 49553")
                        return
                    end
                    return orig(tipsID, ...)
                end
                tips.__phoenixtra_patched = true
                PhoenixtraSummon._tipsHooked = true
                log("IngameTipsTools hooked")
            end
        end
        if not PhoenixtraSummon._gameTipsHooked and Game and type(Game.UIShowTips) == "function" and not Game.__phoenixtra_patched then
            local orig = Game.UIShowTips
            Game.UIShowTips = function(self, playerKey, textID, ...)
                if PhoenixtraSummon.BlockTip49553(textID) then
                    log("blocked Game:UIShowTips 49553")
                    return
                end
                return orig(self, playerKey, textID, ...)
            end
            Game.__phoenixtra_patched = true
            PhoenixtraSummon._gameTipsHooked = true
            log("Game:UIShowTips hooked")
        end
    end

    function PhoenixtraSummon.PatchPlatformInstance(actor)

        if not actor or actor.__phoenixtra_inst_patched then return false end
        if not PhoenixtraSummon.IsXSuitPlatformActor(actor) then return false end

        local origClick = actor.OnClientClickInteractiveButton
        actor.OnClientClickInteractiveButton = function(self, character, component)
            if PhoenixtraSummon.BYPASS_7STAR_CHECK then
                PhoenixtraSummon.ForceWearNow()
                return true
            end
            if origClick then return origClick(self, character, component) end
            return true
        end

        if hasMethod(actor, "Wearing7StarXSuit") then
            actor.Wearing7StarXSuit = function(self, character)
                if PhoenixtraSummon.BYPASS_7STAR_CHECK then return true end
                return false
            end
        end

        if hasMethod(actor, "GetWearingXSuitID") then
            actor.GetWearingXSuitID = function(self, character)
                PhoenixtraSummon.ForceWearNow()
                return PhoenixtraSummon.XSUIT_ID
            end
        end

        actor.__phoenixtra_inst_patched = true
        log("patched live platform " .. getOwnerName(actor))
        return true
    end

    function PhoenixtraSummon.PatchLivePlatformActors()

        local world = slua_GameFrontendHUD and slua_GameFrontendHUD.GetWorld and slua_GameFrontendHUD:GetWorld()
        if not slua.isValid(world) then return 0 end
        local count = 0
        pcall(function()
            local ActorTools = safeRequire("GameLua.Mod.BaseMod.Common.ActorTools")
            if not ActorTools or not ActorTools.GetAllActorsWithTag then return end
            local tags = {"XSuitPlatform", "GoldSuitPlatform", "SummonPlatform"}
            for _, tag in ipairs(tags) do
                local arr = ActorTools.GetAllActorsWithTag(world, tag)
                if arr then
                    for _, actor in pairs(arr) do
                        if PhoenixtraSummon.PatchPlatformInstance(actor) then
                            count = count + 1
                        end
                    end
                end
            end
        end)
        if count > 0 then log("PatchLivePlatformActors count=" .. tostring(count)) end
        return count
    end

    function PhoenixtraSummon.FindPlatformModule()
        local cls = safeRequire(PLATFORM_MODULE)
        if cls then return cls end
        if package and package.loaded then
            for name, mod in pairs(package.loaded) do
                if type(name) == "string" and name:find("XSuitPlatform", 1, true) and type(mod) == "table" then
                    return mod
                end
            end
        end
        return nil
    end

    function PhoenixtraSummon.PatchXSuitPlatformImpl(impl)

        if type(impl) ~= "table" or impl.__phoenixtra_patched then return false end

        local origGetWear = impl.GetWearingXSuitID
        local origGetStatue = impl.GetStatue
        local origWear = impl.Wearing7StarXSuit
        local origClientClick = impl.OnClientClickInteractiveButton

        impl.GetWearingXSuitID = function(self, character)
            if PhoenixtraSummon.FORCE_WEAR_IN_MATCH then
                PhoenixtraSummon.ForceWearNow()
                return PhoenixtraSummon.XSUIT_ID
            end
            if origGetWear then return origGetWear(self, character) end
            return 0
        end

        impl.GetStatue = function(self, suitID)
            if tonumber(suitID) == PhoenixtraSummon.XSUIT_ID then
                local cfg = PhoenixtraSummon.ResolveEffectConfig()
                return cfg.CallStatue or ""
            end
            if origGetStatue then return origGetStatue(self, suitID) end
            return ""
        end

        impl.Wearing7StarXSuit = function(self, character)
            if PhoenixtraSummon.BYPASS_7STAR_CHECK then
                local cfg = PhoenixtraSummon.ResolveEffectConfig()
                if cfg.CallStatue and cfg.CallStatue ~= "" then return true end
                return true
            end
            if origWear then return origWear(self, character) end
            return false
        end

        impl.OnClientClickInteractiveButton = function(self, character, component)
            if PhoenixtraSummon.BYPASS_7STAR_CHECK then
                PhoenixtraSummon.ForceWearNow()
                return true
            end
            if origClientClick then return origClientClick(self, character, component) end
            return true
        end

        impl.__phoenixtra_patched = true
        log("XSuitPlatform impl patched")
        return true
    end

    function PhoenixtraSummon.InstallPlatformHooks()
        if PhoenixtraSummon._platformHooked then
            PhoenixtraSummon.PatchLivePlatformActors()
            return true
        end
        local cls = PhoenixtraSummon.FindPlatformModule()
        if not cls then
            PhoenixtraSummon.PatchLivePlatformActors()
            return false
        end
        local impl = cls.__inner_impl or cls
        local ok = PhoenixtraSummon.PatchXSuitPlatformImpl(impl)
        if cls ~= impl then
            ok = PhoenixtraSummon.PatchXSuitPlatformImpl(cls) or ok
        end
        if ok then PhoenixtraSummon._platformHooked = true end
        PhoenixtraSummon.PatchLivePlatformActors()
        return PhoenixtraSummon._platformHooked
    end

    function PhoenixtraSummon.PatchBasicSkillsMenuTable(BP)

        if not BP or type(BP.Action_InteractiveComponent) ~= "function" then return false end
        if BP.__phoenixtra_patched then return true end

        local orig = BP.Action_InteractiveComponent
        BP.Action_InteractiveComponent = function(self, Param, ExtraParam)
            local Component = Param and Param.Component
            PhoenixtraSummon._lastSummonParam = {Component = Component, Param = Param, ExtraParam = ExtraParam}

            if PhoenixtraSummon.BYPASS_7STAR_CHECK and Component and Component.GetOwner then
                local owner = Component:GetOwner()
                if slua.isValid(owner) and PhoenixtraSummon.IsXSuitPlatformActor(owner) then
                    log("Action_InteractiveComponent bypass summon")
                    PhoenixtraSummon.ForceWearNow()
                    if PhoenixtraSummon.PLAY_LOCAL_SEQUENCE then
                        local cfg = PhoenixtraSummon.ResolveEffectConfig()
                        if cfg.CallStatue and cfg.CallStatue ~= "" and hasMethod(owner, "TriggerCallShowSequence") then
                            pcall(function() owner:TriggerCallShowSequence(cfg.CallStatue) end)
                        end
                    end
                    if self.HideNormalBtn then
                        pcall(function() self:HideNormalBtn("Type_InteractiveComponent", Param) end)
                    end
                    return
                end
            end

            return orig(self, Param, ExtraParam)
        end

        BP.__phoenixtra_patched = true
        log("BasicSkillsMenu Action_InteractiveComponent hooked")
        return true
    end

    function PhoenixtraSummon.InstallBasicSkillsMenuHook()
        safeRequire("GameLua.Mod.BaseMod.Client.Skill.BasicSkillsMenuBP_Actions")
        local BP = safeRequire("GameLua.Mod.BaseMod.Client.Skill.BasicSkillsMenuBP_Config")
        if not BP then return false end
        if not PhoenixtraSummon.PatchBasicSkillsMenuTable(BP) then return false end
        PhoenixtraSummon._menuHooked = true
        return true
    end

    function PhoenixtraSummon.InstallMatchEvents()

        if PhoenixtraSummon._eventsHooked then return end
        if type(EventSystem) ~= "table" or not EventSystem.AddCommonEvent then return end
        pcall(function()
            EventSystem:AddCommonEvent(EVENTTYPE_INGAME_NORMAL, EVENTID_GAME_MODE_STATE_CHANGE, function(_, _, state)
                if state == "ReadyState" then
                    PhoenixtraSummon.PatchLivePlatformActors()
                    PhoenixtraSummon.ForceWearNow()
                    log("ReadyState refresh platform")
                end
            end)
            PhoenixtraSummon._eventsHooked = true
            log("match events hooked")
        end)
    end

    function PhoenixtraSummon.InstallRequireHook()

        if PhoenixtraSummon._origRequire then return end
        PhoenixtraSummon._origRequire = require
        _G.require = function(modname)
            local result = PhoenixtraSummon._origRequire(modname)
            if modname == "GameLua.Mod.BaseMod.Common.UI.InGameTipsTools" then
                PhoenixtraSummon.InstallTipsHooks()
            elseif modname == "GameLua.Mod.BaseMod.Client.Skill.BasicSkillsMenuBP_Actions" then
                PhoenixtraSummon.InstallBasicSkillsMenuHook()
            elseif modname == PLATFORM_MODULE then
                PhoenixtraSummon.InstallPlatformHooks()
            end
            return result
        end
        log("require hook installed")
    end

    function PhoenixtraSummon.PreloadAssets()

        local cfg = PhoenixtraSummon.ResolveEffectConfig()
        local PufferConst = safeRequire("client.slua.logic.download.puffer_const")
        local PufferManager = safeRequire("client.slua.logic.download.puffer.puffer_manager")
        if not PufferConst or not PufferManager then return end
        local list = {PhoenixtraSummon.XSUIT_ID, PhoenixtraSummon.FALLBACK_TEMPLATE_ID, PhoenixtraSummon.CALL_ACTION_ID}
        if cfg.CallStatue and cfg.CallStatue ~= "" then
            table.insert(list, cfg.CallStatue)
        end
        pcall(function()
            PufferManager.Download(PufferConst.ENUM_DownloadType.ODPAK, list)
        end)
    end

    function PhoenixtraSummon.Install()

        PhoenixtraSummon.UpdateFromConfig()
        PhoenixtraSummon.InstallTipsHooks()
        PhoenixtraSummon.InstallRequireHook()
        PhoenixtraSummon.InstallDataTableHooks()
        PhoenixtraSummon.ResolveEffectConfig()
        PhoenixtraSummon.RegisterLogicXSuitItem()
        PhoenixtraSummon.InstallPlatformHooks()
        PhoenixtraSummon.InstallBasicSkillsMenuHook()
        PhoenixtraSummon.InstallMatchEvents()
        PhoenixtraSummon.PreloadAssets()
        PhoenixtraSummon.ForceWearNow()
        log("Install done with XSUIT_ID=" .. tostring(PhoenixtraSummon.XSUIT_ID))
        return true
    end

    if PhoenixtraSummon.AUTO_INSTALL then
        if _G.Mytimer_ticker then

            _G.Mytimer_ticker.AddTimer(2, function()
                pcall(function() PhoenixtraSummon.Install() end)
            end)

            if _G.__loopGuard24891 and _G.Mytimer_ticker.IsRunning and _G.Mytimer_ticker.IsRunning(_G.__loopGuard24891) then _G.Mytimer_ticker.RemoveTimer(_G.__loopGuard24891) end
            _G.__loopGuard24891 =             _G.Mytimer_ticker.AddTimerLoop(2, function()

                local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
                if okF and inFight then return end
                pcall(function()
                    if PhoenixtraSummon.UpdateFromConfig then
                        local newID = PhoenixtraSummon.UpdateFromConfig()
                        if newID then

                            if PhoenixtraSummon.XSUIT_ID ~= newID then
                                PhoenixtraSummon._resolvedEffect = nil
                                PhoenixtraSummon.Install()
                            end
                        end
                    end
                    if not PhoenixtraSummon._platformHooked then
                        PhoenixtraSummon.InstallPlatformHooks()
                    end
                    PhoenixtraSummon.ForceWearNow()
                end)
            end, -1, 1)
        else

            pcall(function() PhoenixtraSummon.Install() end)
        end
    end

    _G.PhoenixtraSummon = PhoenixtraSummon
end
end

do

if not _G.__XSUIT_FAKE_DRAW_LOADED__ then
    _G.__XSUIT_FAKE_DRAW_LOADED__ = true

    local function XSuitNormalizePool(raw)
        local pool = {}
        local function push(v)
            if type(v) ~= "table" then return end
            local id = tonumber(v.itemid or v.itemId or v.resid or v.res_id)
            if not id or id <= 0 then return end
            pool[#pool + 1] = {
                itemId = id,
                count = tonumber(v.count or v.item_num or 1) or 1,
                weight = tonumber(v.weight or v.award_weight or 1) or 1,
                posId = tonumber(v.pos_id or v.posId or v.display_sort) or (#pool + 1),
            }
        end
        if type(raw) ~= "table" then return pool end
        if raw[1] ~= nil then
            for _, v in ipairs(raw) do push(v) end
            if #pool > 0 then return pool end
        end
        for _, v in pairs(raw) do
            if type(v) == "table" then
                if v.itemid or v.itemId or v.resid then
                    push(v)
                else
                    for _, vv in pairs(v) do
                        if type(vv) == "table" then
                            if vv.itemid or vv.itemId or vv.resid then
                                push(vv)
                            else
                                for _, vvv in pairs(vv) do
                                    if type(vvv) == "table" then push(vvv) end
                                end
                            end
                        end
                    end
                end
            end
        end
        return pool
    end

    local function XSuitAddDropsToBag(dropList)
        if type(dropList) ~= "table" then return end
        pcall(function()
            local AM = rawget(_G, "AddOutfit")
            if not AM or not AM.getEntity or not AM.injectOne then return end
            local ent = AM.getEntity()
            if not ent then return end
            local n = 0
            for _, v in pairs(dropList) do
                local resID = tonumber(v.res_id or v.resid or v.itemId or v.itemid)
                local count = tonumber(v.count or 1) or 1
                if resID and resID > 0 then
                    local ok = false
                    pcall(function()
                        ok = AM.injectOne(ent, resID, nil, { addCount = count, markNew = true }) == true
                    end)
                    if ok then n = n + 1 end
                end
            end
            if n > 0 then
                pcall(function() if AM.refreshWardrobe then AM.refreshWardrobe(true) end end)
            end
        end)
    end

    local function XSuitBumpDrawProgress(addCount, pool_id)
        addCount = tonumber(addCount) or 0
        if addCount <= 0 then return end
        pcall(function()
            local act = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
            if not act or not act.DrawActivityInfo then return end
            local info = act.DrawActivityInfo
            info.pool_draw_times = info.pool_draw_times or {}
            info.pool_accumulate_info = info.pool_accumulate_info or {}
            local sid = pool_id or (act.GetSelectPoolID and act:GetSelectPoolID()) or act.SelectPoolID or 1001
            local TOTAL = 10000
            local times = info.pool_draw_times
            times[sid] = (tonumber(times[sid]) or 0) + addCount
            if info.accumulate_info and info.accumulate_info[TOTAL] then
                times[TOTAL] = (tonumber(times[TOTAL]) or 0) + addCount
            end
            local awardInfo = info.accumulate_info or {}
            local stateInfo = info.pool_accumulate_info
            local function unlockPool(pid)
                if not awardInfo[pid] then return end
                stateInfo[pid] = stateInfo[pid] or {}
                local drawn = tonumber(times[pid]) or 0
                for targetNum, _ in pairs(awardInfo[pid]) do
                    local t = tonumber(targetNum) or targetNum
                    stateInfo[pid][t] = stateInfo[pid][t] or { state = 0 }
                    local st = tonumber(stateInfo[pid][t].state) or 0

                    if st ~= 2 and drawn >= (tonumber(t) or 0) then
                        stateInfo[pid][t].state = 1
                    end
                end
            end
            unlockPool(sid)
            unlockPool(TOTAL)
            pcall(function() act:SetAccumulateDrawTime(times) end)
            pcall(function() act:SetAccumulateStateInfo(stateInfo) end)
        end)
    end

    local function FakeXSuitDrawNow(cost_times, pool_id)
        pcall(function() if DataMgr then DataMgr.ticket = 99999 end end)
        local count = tonumber(cost_times) or 10
        if count ~= 1 and count ~= 10 then
            count = (count > 1) and 10 or 1
        end
        local pool = {}
        pcall(function()
            local act = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
            if not act then return end
            local info = act.GetDrawPoolInfo and act:GetDrawPoolInfo()
            local sid = pool_id or (act.GetSelectPoolID and act:GetSelectPoolID()) or act.SelectPoolID
            if sid and type(info) == "table" then
                pool = XSuitNormalizePool(info[sid])
            end
            if #pool == 0 then
                pool = XSuitNormalizePool(info)
            end
            if #pool == 0 and act.GetDrawActivityInfo then
                local di = act:GetDrawActivityInfo() or {}
                pool = XSuitNormalizePool(di.pool_info)
                if #pool == 0 then pool = XSuitNormalizePool(di.probability_info) end
                if #pool == 0 then pool = XSuitNormalizePool(di.award_pool) end
            end
        end)
        if #pool == 0 then
            pcall(function()
                EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_SPIN_SHOWORHIDE_MASK, false)
            end)
            return false
        end
        local totalW = 0
        for i = 1, #pool do totalW = totalW + (pool[i].weight or 1) end
        if totalW < 1 then totalW = #pool end
        local item_list = {}
        local bag = {}
        for i = 1, count do
            local r = math.random(1, totalW)
            local c = 0
            local sel = pool[#pool]
            for j = 1, #pool do
                c = c + (pool[j].weight or 1)
                if r <= c then sel = pool[j] break end
            end
            local id = sel.itemId
            item_list[#item_list + 1] = {
                itemid = id, resid = id, res_id = id,
                count = sel.count or 1, valid_hours = 0, expire_ts = 0, pos_id = sel.posId,
            }
            bag[#bag + 1] = { res_id = id, count = sel.count or 1, valid_hours = 0 }
        end
        XSuitAddDropsToBag(bag)
        XSuitBumpDrawProgress(count, pool_id)
        pcall(function()
            local act = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
            if act then pcall(function() act:SetIsFirstDiscount(false) end) end
            EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_SPIN_STOP_COIN_UPDATE)
            EventSystem:postEvent(EVENTTYPE_ACTIVITY, EVENTID_SPIN_STOP_COIN_UPDATE_TIMER)
            EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_SPIN_DRAW_RSP, item_list, {})
            EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_SPIN_SHOWORHIDE_MASK, false)
            EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_DRAW_ACTIVITY_UPDATE)
        end)
        return true
    end
    _G.FakeXSuitDrawNow = FakeXSuitDrawNow

    local function HookXSuitAccumulateClaim()
        local ok, XSuitHandler = pcall(require, "client.network.Protocol.XSuitHandler")
        if not ok or not XSuitHandler then return false end
        if XSuitHandler.__xsuitClaimLocalHooked then return true end
        XSuitHandler.__xsuitClaimLocalHooked = true
        XSuitHandler.send_get_accumulate_pool_reward_req = function(pid, times, opt_flag, is_take_all)
            pcall(function()
                local act = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
                if not act then return end
                local awardInfo = act.GetAccumulateAwardInfo and act:GetAccumulateAwardInfo() or {}
                local stateInfo = act.GetAccumulateStateInfo and act:GetAccumulateStateInfo() or {}
                stateInfo = stateInfo or {}
                stateInfo[pid] = stateInfo[pid] or {}
                local item_list = {}
                local function takeTarget(ppid, target)
                    local conf = awardInfo[ppid] and awardInfo[ppid][target]
                    if not conf then return end
                    for _, v in pairs(conf) do
                        if type(v) == "table" then
                            local id = tonumber(v.resid or v.res_id or v.itemid)
                            if id and id > 0 then
                                item_list[#item_list + 1] = {
                                    resid = id, res_id = id, itemid = id,
                                    count = tonumber(v.count) or 1,
                                    valid_hours = tonumber(v.valid_hours) or 0,
                                }
                            end
                        end
                    end
                    stateInfo[ppid][target] = stateInfo[ppid][target] or {}
                    stateInfo[ppid][target].state = 2
                end
                takeTarget(pid, times)
                if is_take_all and awardInfo[pid] then
                    local drawn = 0
                    pcall(function()
                        local t = act:GetAccumulateDrawTime()
                        drawn = tonumber(t and t[pid]) or 0
                    end)
                    for target, _ in pairs(awardInfo[pid]) do
                        local st = stateInfo[pid][target] and stateInfo[pid][target].state
                        if (tonumber(st) or 0) == 1 or (drawn >= (tonumber(target) or 0) and (tonumber(st) or 0) ~= 2) then
                            takeTarget(pid, target)
                        end
                    end
                end
                if #item_list > 0 then XSuitAddDropsToBag(item_list) end
                pcall(function() act:SetAccumulateStateInfo(stateInfo) end)
                pcall(function()
                    XSuitHandler.on_get_accumulate_pool_reward_rsp(0, item_list, stateInfo, {})
                end)
                pcall(function()
                    EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_DRAW_ACTIVITY_UPDATE)
                end)
            end)
        end
        return true
    end

    local function HookXSuitDrawRequests()
        local anyOk = false
        pcall(function()
            local XSuitHandler = require("client.network.Protocol.XSuitHandler")
            if XSuitHandler and not XSuitHandler.__xsuitFakeDrawHooked then
                XSuitHandler.__xsuitFakeDrawHooked = true
                XSuitHandler.send_draw_gold_dress_req = function(cost_times, currency_id, voucher_id, pool_id)
                    pcall(function()
                        EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_SPIN_SHOWORHIDE_MASK, true)
                    end)
                    FakeXSuitDrawNow(cost_times, pool_id)
                end
            end
            if XSuitHandler then anyOk = true end
        end)
        pcall(function()
            local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
            if LogicXSuit and not LogicXSuit.__xsuitFakeDrawHooked then
                LogicXSuit.__xsuitFakeDrawHooked = true
                LogicXSuit.draw_gold_dress_req = function(cost_times, currency_id, coupon_id, pool_id)
                    pcall(function()
                        EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_SPIN_SHOWORHIDE_MASK, true)
                    end)
                    FakeXSuitDrawNow(cost_times, pool_id)
                end
            end
            if LogicXSuit then anyOk = true end
        end)
        return anyOk
    end

    pcall(function()
        local tt = require("common.time_ticker")
        local function tryInstall()
            HookXSuitDrawRequests()
            HookXSuitAccumulateClaim()
        end
        pcall(tryInstall)
        if tt and tt.AddTimerLoop then
            tt.AddTimerLoop(3, function()
                pcall(tryInstall)
            end, 20, 3)
        end
    end)
end

end

do

pcall(function()
    local SELF_BG_ID    = 61510002
    local SELF_CARTE_ID = 61100039

    local PROFILE_SWAP_LIST = {
        [61510000] = 61510002,
        [61100001] = 61100039,
        [61300001] = 61300002,
    }

    local function isSelfUid(uid)
        local l = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
        return l and tostring(uid) == tostring(l)
    end

    do
        local H = { installed = false, orig = nil, wrapped = nil }
        local PROFILE_SWAP_GATE = {
            [61510000] = "PROFILE_BG",
            [61100001] = "PROFILE_CARD",
        }
        local function install()
            if H.installed then return true end
            if type(CDataTable) ~= "table" or type(CDataTable.GetTableData) ~= "function" then
                return false
            end
            if not H.orig then H.orig = CDataTable.GetTableData end
            if not H.wrapped then
                local orig = H.orig
                H.wrapped = function(tblName, id, ...)
                    local nid = tonumber(id)
                    local gate = PROFILE_SWAP_GATE[nid]
                    if gate and not _G.FeatureSwitch(gate, true) then
                        return orig(tblName, id, ...)
                    end
                    local swapTo = PROFILE_SWAP_LIST[nid]
                    if swapTo then
                        local ok, cfg = pcall(orig, tblName, swapTo, ...)
                        if ok and cfg then return cfg end
                    end
                    return orig(tblName, id, ...)
                end
            end
            CDataTable.GetTableData = H.wrapped
            H.installed = true
            return true
        end
        local function uninstall()
            if H.installed and H.orig and CDataTable.GetTableData == H.wrapped then
                CDataTable.GetTableData = H.orig
            end
            H.installed = false
        end
        if not install() and _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimerLoop then
            _G.Mytimer_ticker.AddTimerLoop(3, function()
                if not H.installed then install() end
            end, 100, 1)
        end

        if _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimerLoop then
            _G.Mytimer_ticker.AddTimerLoop(3, function()
                pcall(function()
                    local okF, inFight = pcall(function()
                        return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus()
                    end)
                    if okF and inFight then uninstall() else install() end
                end)
            end, -1, 3)
        end
    end

    do
        local installed = false
        local function install()
            if installed then return true end
            if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then return false end
            local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.logic_roleInfo_background)
            if not ok or type(m) ~= "table" then return false end
            if type(m.GetSelfRoleInfoBGID) == "function" and not m.__bgHooked then
                local origSelf = m.GetSelfRoleInfoBGID
                m.GetSelfRoleInfoBGID = function(self, ...)
                    if not _G.FeatureSwitch("PROFILE_BG", true) then return origSelf(self, ...) end
                    return SELF_BG_ID
                end
                m.__bgHooked = true
            end
            if type(m.GetPlayerRoleInfoBGID) == "function" and not m.__bgHooked2 then
                local orig = m.GetPlayerRoleInfoBGID
                m.GetPlayerRoleInfoBGID = function(self, uid, ...)
                    if isSelfUid(uid) and _G.FeatureSwitch("PROFILE_BG", true) then return SELF_BG_ID end
                    return orig(self, uid, ...)
                end
                m.__bgHooked2 = true
            end
            installed = m.__bgHooked == true
            return installed
        end
        if not install() and _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimerLoop then
            _G.Mytimer_ticker.AddTimerLoop(3, function()
                if not installed then install() end
            end, 100, 1)
        end
    end

    do
        local installed = false
        local function install()
            if installed then return true end
            local ok, sc = pcall(require, "client.slua.logic.lobby.Left.logic_social_card")
            if not ok or type(sc) ~= "table" or type(sc.GetCarteFrameEquipIdByProfile) ~= "function" then return false end
            if sc.__carteHooked then installed = true return true end
            local orig = sc.GetCarteFrameEquipIdByProfile
            sc.GetCarteFrameEquipIdByProfile = function(profile, ...)
                if profile and type(profile) == "table" and isSelfUid(profile.uid)
                    and _G.FeatureSwitch("PROFILE_CARD", true) then
                    return SELF_CARTE_ID
                end
                return orig(profile, ...)
            end
            sc.__carteHooked = true
            installed = true
            return true
        end
        if not install() and _G.Mytimer_ticker and _G.Mytimer_ticker.AddTimerLoop then
            _G.Mytimer_ticker.AddTimerLoop(3, function()
                if not installed then install() end
            end, 100, 1)
        end
    end
end)

end

do

_G.CustomInfoMod = _G.CustomInfoMod or {}
do
    local M = _G.CustomInfoMod

    local function CI_GetTicker()
        return _G.Mytimer_ticker or _G.timer_ticker
    end

    local CI_lobbyTickFns = nil
    local function CI_RegisterLobbyTick(fn)
        if not CI_lobbyTickFns then
            CI_lobbyTickFns = {}
            local ticker = CI_GetTicker()
            if not (ticker and ticker.AddTimerLoop) then
                pcall(function() ticker = require("common.time_ticker") end)
            end
            if ticker and ticker.AddTimerLoop then
                ticker.AddTimerLoop(3, function()
                    local okF, inFight = pcall(function() return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus() end)
                    if okF and inFight then return end
                    for _, f in ipairs(CI_lobbyTickFns) do pcall(f) end
                end, -1, 1)
            end
        end
        table.insert(CI_lobbyTickFns, fn)
    end

    local function CI_IsSelfUid(uid)
        local u = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
        if not u then
            local ok, ret = pcall(function()
                if TeamUpNewSystem and TeamUpNewSystem.GetSelfUID then
                    return tonumber(TeamUpNewSystem.GetSelfUID())
                end
            end)
            if ok then u = ret end
        end
        return u and tostring(uid) == tostring(u)
    end
    M.IsSelfUid = CI_IsSelfUid

    local function CfgNum(key, def)
        local ok, v = pcall(function()
            if _G.MS_CONFIG_VIP_Config and _G.MS_CONFIG_VIP_Config.Get then
                return _G.MS_CONFIG_VIP_Config.Get(key, def or 0)
            end
        end)
        if ok then return tonumber(v) or (def or 0) end
        return def or 0
    end
    local function CfgOn(key) return CfgNum(key, 0) == 1 end
    M.CfgNum = CfgNum
    M.CfgOn = CfgOn

    M._textCache = M._textCache or nil

    local function CI_TextFilePath()
        local paths = (_G.MS_CONFIG_VIP_Config and _G.MS_CONFIG_VIP_Config.PATHS) or {}
        for _, p in ipairs(paths) do
            local dir = tostring(p):match("^(.*)/[^/]*$")
            if dir then
                local fp = dir .. "/CustomInfo.cfg"
                local f = io.open(fp, "r")
                if f then f:close(); return fp end
            end
        end

        local p0 = paths[1]
        if p0 then
            local dir = tostring(p0):match("^(.*)/[^/]*$")
            if dir then return dir .. "/CustomInfo.cfg" end
        end
        return nil
    end

    local function CI_LoadText()
        if M._textCache then return M._textCache end
        M._textCache = {}
        local fp = CI_TextFilePath()
        if fp then
            local f = io.open(fp, "r")
            if f then
                for line in f:lines() do
                    local k, v = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
                    if k and v then M._textCache[k] = v end
                end
                f:close()
            end
        end
        return M._textCache
    end

    local function CI_SaveText()
        local fp = CI_TextFilePath()
        if not fp then return false end
        local f = io.open(fp, "w")
        if not f then return false end
        for k, v in pairs(M._textCache or {}) do
            f:write(tostring(k) .. " = " .. tostring(v) .. "\n")
        end
        f:close()
        return true
    end

    function M.GetText(key)
        return CI_LoadText()[key] or ""
    end

    function M.SetText(key, text)
        CI_LoadText()
        M._textCache[key] = tostring(text or "")
        CI_SaveText()
    end

    function M.PatchTextInputPopup()
        if M._textPopupPatched then return end
        local ok, PopupClass = pcall(require, "client.slua.umg.setting.Setting_Cloud_Search_Popups_UIBP")
        if not ok or not PopupClass then return end

        function M._bindPopupClose(ui)
            pcall(function()
                local comp = ui and ui.Common_Popup_Small_UIBP
                if not (comp and comp.UIRoot and comp.UIRoot.close) then return end
                if not comp.AddControlEventByControl then return end
                if M._closeBoundFor == ui then return end
                M._closeBoundFor = ui
                comp:AddControlEventByControl(comp.UIRoot.close, "OnClicked", function()
                    pcall(function()
                        if _G.MS_CONFIG_VIP_Config then
                            _G.MS_CONFIG_VIP_Config._numInput = nil
                            _G.MS_CONFIG_VIP_Config._skinPopupSetupToken = nil
                            _G.MS_CONFIG_VIP_Config._releaseSkinPopupOpeningLock()
                        end
                    end)
                    pcall(function()
                        UIManager.CloseUI(UIManager.UI_Config.setting_cloud_search_popups)
                    end)
                end, comp)
            end)
        end

        local origInit = PopupClass.OnInitialize
        PopupClass.OnInitialize = function(self)
            if origInit then origInit(self) end
            M._bindPopupClose(self)
        end

        local origPost = PopupClass.OnPostInitialize
        PopupClass.OnPostInitialize = function(self)
            if origPost then origPost(self) end
            M._bindPopupClose(self)
        end

        M._textPopupPatched = true
    end

    function M.ShowTextInputPopup(opts)
        M.PatchTextInputPopup()
        if _G.MS_CONFIG_VIP_Config and _G.MS_CONFIG_VIP_Config.ShowTextInputPopup then
            return _G.MS_CONFIG_VIP_Config.ShowTextInputPopup(opts)
        end
        return false
    end

    local function CI_Install(tag, installFn)
        local installed = false
        local function try()
            if installed then return true end
            local ok, ret = pcall(installFn)
            if ok and ret then installed = true end
            return installed
        end
        if not try() then
            local ticker = CI_GetTicker()
            if ticker and ticker.AddTimerLoop then
                ticker.AddTimerLoop(3, function() try() end, 100, 1)
            end
        end
    end

    local function CI_RefreshCollectUI()
        pcall(function()
            EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_MAIN_DATA)
        end)
        pcall(function()
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_SEASON_CHANGE)
        end)
    end

    CI_Install("ci_textPopup", function()
        M.PatchTextInputPopup()
        return M._textPopupPatched == true
    end)

    local function CI_GetDataMgr()
        if type(_G.DataMgr) == "table" then return _G.DataMgr end
        local ok, m = pcall(require, "client.logic.data.data_mgr")
        if ok and type(m) == "table" then return m end
        return nil
    end
    M.GetDataMgr = CI_GetDataMgr

    CI_Install("ci_nameProfile", function()
        if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then return false end
        local ok, lp = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.logic_profile)
        if not ok or type(lp) ~= "table" or type(lp.GetLocalProfile) ~= "function" then return false end
        if lp.__ciNameHooked then return true end
        local orig = lp.GetLocalProfile
        lp.GetLocalProfile = function(self, uid, ...)
            local profile = orig(self, uid, ...)
            if profile and type(profile) == "table" and CI_IsSelfUid(uid) then

                local tid = tonumber(MS_CONFIG_VIP_Config.Get("CI_TITLE_ID", 0)) or 0
                if tid > 0 and M.BuildTitleDet then
                    pcall(function()
                        profile.hsegment_title_det = M.BuildTitleDet(tid)
                    end)
                end

                local lv = tonumber(MS_CONFIG_VIP_Config.Get("CI_PLAYER_LEVEL", 0)) or 0
                if lv > 0 then
                    pcall(function() profile.level = lv end)
                end
            end
            return profile
        end
        lp.__ciNameHooked = true
        return true
    end)

    CI_Install("ci_goldName", function()
        if not (ModuleManager and ModuleManager.GetModule and ModuleManager.CommonModuleConfig) then return false end
        local ok, mgr = pcall(ModuleManager.GetModule, ModuleManager.CommonModuleConfig.NicknameColorManager)
        if not ok or type(mgr) ~= "table" or type(mgr.GetUserData) ~= "function" then return false end
        if mgr.__ciGoldNameHooked then return true end
        local orig = mgr.GetUserData
        mgr.GetUserData = function(self, UID, ...)
            if CfgOn("CI_GOLD_NAME") and CI_IsSelfUid(UID) then
                local plan = CfgNum("CI_GOLD_PLAN", 61910001)
                if plan > 0 then return plan end
            end
            return orig(self, UID, ...)
        end
        mgr.__ciGoldNameHooked = true
        return true
    end)

    CI_Install("ci_bg", function()
        if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then return false end
        local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.logic_roleInfo_background)
        if not ok or type(m) ~= "table" then return false end
        if type(m.GetSelfRoleInfoBGID) == "function" and not m.__ciBgHooked then
            local orig = m.GetSelfRoleInfoBGID
            m.GetSelfRoleInfoBGID = function(self, ...)
                local id = CfgNum("CI_BG_ID", 0)
                if id > 0 then return id end
                return orig(self, ...)
            end
            m.__ciBgHooked = true
        end
        if type(m.GetPlayerRoleInfoBGID) == "function" and not m.__ciBgHooked2 then
            local orig = m.GetPlayerRoleInfoBGID
            m.GetPlayerRoleInfoBGID = function(self, uid, ...)
                local id = CfgNum("CI_BG_ID", 0)
                if id > 0 and CI_IsSelfUid(uid) then return id end
                return orig(self, uid, ...)
            end
            m.__ciBgHooked2 = true
        end
        return m.__ciBgHooked == true
    end)

    CI_Install("ci_carte", function()
