    local function CI_ApplyAvatar()
        if not (DataMgr and DataMgr.roleData) then return end
        local rd = DataMgr.roleData
        local changed = false
        local frameId = CfgNum("CI_AVATARFRAME_ID", 0)
        local avatarId = CfgNum("CI_AVATAR_ID", 0)

        if frameId > 0 then
            local cur = tonumber(rd.cur_avatar_box_id) or 0
            if cur ~= frameId then
                local ok = pcall(function() DataMgr.UpdateAvatarBoxId(frameId) end)
                if not ok then pcall(function() rd.cur_avatar_box_id = frameId end) end
                changed = true
            end

            pcall(function()
                local af = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
                if af then
                    af.AvatarFrameList = af.AvatarFrameList or {}
                    af.AvatarFrameList[frameId] = af.AvatarFrameList[frameId] or { expire_time = 1 }
                    af.AvatarFrameList[frameId].expire_time = 1
                    af.HasGet = true
                    af._hasGotData = true
                end
            end)
        end

        if avatarId > 0 then
            local want = tostring(avatarId)
            if tostring(rd.headIconUrl) ~= want then
                local ok = pcall(function() DataMgr.UpdateHeadIconUrl(want) end)
                if not ok then pcall(function() rd.headIconUrl = want end) end
                changed = true
                pcall(function()
                    local big = require("client.slua.logic.roleInfo.logic_roleInfo_BigAvatar")
                    if big and big.RefreshBigImage then big.RefreshBigImage(want) end
                end)
            end
            pcall(function()
                local av = require("client.slua.logic.roleInfo.logic_roleInfo_Avatar")
                if av then
                    av.HeadportraitList = av.HeadportraitList or {}
                    if av.HeadportraitList[want] == nil then
                        av.HeadportraitList[want] = 1
                    end
                end
            end)
        end

        if changed then
            pcall(function()
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_HEAD_INFO, rd.headIconUrl)
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_USE_AVATAR)
                EventSystem:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
                EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_LOBBY_SOCIAL_UPDATE_HEAD_ICON)
            end)
        end
    end
    M.ApplyAvatar = CI_ApplyAvatar

    CI_RegisterLobbyTick(CI_ApplyAvatar)

    local function CI_RewriteCollectData(data)
        if not CfgOn("CI_COLLECT_EN") or type(data) ~= "table" then return end
        local score = CfgNum("CI_COLLECT_SCORE", 999999999)
        local level = CfgNum("CI_COLLECT_LEVEL", 100)
        if level < 1 then level = 1 end
        data.total_score = score
        data.cur_season_collect_score = score
        data.season_score = data.season_score or {}
        if DataMgr and DataMgr.season_id then
            data.season_score[DataMgr.season_id] = score
        end
        data.level_reward = data.level_reward or {}
        for lv = 1, level do
            if not data.level_reward[lv] then
                data.level_reward[lv] = { state = 1 }
            end
        end
    end
    M.RewriteCollectData = CI_RewriteCollectData

    CI_Install("ci_collect", function()
        if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then return false end
        local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.collect_module)
        if not ok or type(m) ~= "table" then return false end

        local function On() return CfgOn("CI_COLLECT_EN") end
        local function Level()
            local lv = CfgNum("CI_COLLECT_LEVEL", 100)
            if lv < 1 then lv = 1 end
            return lv
        end
        local function Score() return CfgNum("CI_COLLECT_SCORE", 999999999) end

        if type(m.OnGetMainData) == "function" and not m.__ci_fs_main then
            local orig = m.OnGetMainData
            m.__ci_fs_main = orig
            m.OnGetMainData = function(self, err_code, collect_data, param, ...)
                CI_RewriteCollectData(collect_data)
                return orig(self, err_code, collect_data, param, ...)
            end
        end

        if type(m.NotifyCollectData) == "function" and not m.__ci_fs_notify then
            local orig = m.NotifyCollectData
            m.__ci_fs_notify = orig
            m.NotifyCollectData = function(self, collect_data)
                CI_RewriteCollectData(collect_data)
                return orig(self, collect_data)
            end
        end

        if type(m.GetCollectTotalScore) == "function" and not m.__ci_fs_totalscore then
            local orig = m.GetCollectTotalScore
            m.__ci_fs_totalscore = orig
            m.GetCollectTotalScore = function(self)
                if not On() then return orig(self) end
                return Score(), Level()
            end
        end

        if type(m.GetLevelByScore) == "function" and not m.__ci_fs_lvscore then
            local orig = m.GetLevelByScore
            m.__ci_fs_lvscore = orig
            m.GetLevelByScore = function(self, score)
                if On() and score and score >= 0 then
                    local lv = Level()
                    return lv, lv, lv, 0, 0
                end
                return orig(self, score)
            end
        end

        if type(m.GetLevelDataByScore) == "function" and not m.__ci_fs_lvdata then
            local orig = m.GetLevelDataByScore
            m.__ci_fs_lvdata = orig
            m.GetLevelDataByScore = function(self, score, bSeason)
                if On() and score and score >= 0 then
                    local lv = Level()
                    return lv, "", lv
                end
                return orig(self, score, bSeason)
            end
        end

        if type(m.GetSeasonLevelByScore) == "function" and not m.__ci_fs_seasonlv then
            local orig = m.GetSeasonLevelByScore
            m.__ci_fs_seasonlv = orig
            m.GetSeasonLevelByScore = function(self, score, ...)
                if On() and score and score >= 0 then
                    return Level(), false, ""
                end
                return orig(self, score, ...)
            end
        end

        if type(m.GetCollectScoreByProfile) == "function" and not m.__ci_fs_proscore then
            local orig = m.GetCollectScoreByProfile
            m.__ci_fs_proscore = orig
            m.GetCollectScoreByProfile = function(self, profile, ...)
                if On() and profile and CI_IsSelfUid(profile.uid) then
                    return Score()
                end
                return orig(self, profile, ...)
            end
        end
        if type(m.GetCollectScoreByCollectData) == "function" and not m.__ci_fs_cdscore then
            local orig = m.GetCollectScoreByCollectData
            m.__ci_fs_cdscore = orig
            m.GetCollectScoreByCollectData = function(self, collect_data, uid, ...)
                if On() and (not uid or CI_IsSelfUid(uid)) then
                    return Score()
                end
                return orig(self, collect_data, uid, ...)
            end
        end

        if type(m.OnGetItemData) == "function" and not m.__ci_fs_item then
            local orig = m.OnGetItemData
            m.__ci_fs_item = orig
            m.OnGetItemData = function(self, uid, data)
                if On() and CI_IsSelfUid(uid) and type(data) == "table" then
                    local lv = Level()
                    data.item_detail = data.item_detail or {}
                    for i = 1, lv do
                        if not data.item_detail[i] then
                            data.item_detail[i] = { count = 1, expire_ts = 0 }
                        end
                    end
                end
                return orig(self, uid, data)
            end
        end
        return true
    end)

    do
        local function reapply()
            pcall(function()
                if not CfgOn("CI_COLLECT_EN") then return end
                if not (ModuleManager and ModuleManager.GetModule) then return end
                local m = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.collect_module)
                if type(m) == "table" and type(m.collect_data) == "table" then
                    if m.collect_data.total_score ~= CfgNum("CI_COLLECT_SCORE", 999999999) then
                        CI_RewriteCollectData(m.collect_data)
                        CI_RefreshCollectUI()
                    end

                    pcall(function()
                        local lv = CfgNum("CI_COLLECT_LEVEL", 100)
                        if lv < 1 then lv = 1 end
                        if m.__ciLastColLv ~= lv and type(m.SetOneLevel) == "function" then
                            local cc = require("GameLua.Mod.Lobby.Base.Collect.logic.collect_cfg")
                            if cc and cc.Sys2Index then
                                m:SetOneLevel(cc.Sys2Index.Level, lv)
                                m:SetOneLevel(cc.Sys2Index.Season, lv)
                                m.__ciLastColLv = lv
                            end
                        end
                    end)
                end
            end)
        end

        CI_RegisterLobbyTick(function() reapply() end)
    end

    local CI_MONEY_MAP = {
        [0]   = "CI_MONEY_GOLD",
        [1]   = "CI_MONEY_SILVER",
        [2]   = "CI_MONEY_UC",
        [6]   = "CI_MONEY_AG",
    }

    local function CI_MoneyOverride(money_type)
        local key = CI_MONEY_MAP[tonumber(money_type) or -1]
        if not key then return nil end
        local v = tonumber(MS_CONFIG_VIP_Config.Get(key, 0)) or 0
        if v > 0 then return v end
        return nil
    end
    M.MoneyOverride = CI_MoneyOverride

    local function CI_ApplyMoney()
        local dm = CI_GetDataMgr()
        if not dm then return end

        local function fire(ev, a, b)
            pcall(function()
                if EventSystem and EVENTTYPE_DATA_MGR and ev then
                    if b ~= nil then EventSystem:postEvent(EVENTTYPE_DATA_MGR, ev, a, b)
                    else EventSystem:postEvent(EVENTTYPE_DATA_MGR, ev, a) end
                end
            end)
        end
        local gold = CI_MoneyOverride(0)
        if gold and tonumber(dm.gold) ~= gold then
            pcall(function() dm.gold = gold end)
            fire(EVENTID_DATAMGR_GOLD_CHANGE, dm.gold)
        end
        local uc = CI_MoneyOverride(2)
        if uc and tonumber(dm.ticket) ~= uc then
            pcall(function() dm.ticket = uc end)
            fire(EVENTID_DATAMGR_TICKET_CHANGE, dm.ticket, { gen_ticket = dm.gen_ticket })
        end
        local silver = CI_MoneyOverride(1)
        if silver and tonumber(dm.diamond) ~= silver then
            pcall(function() dm.diamond = silver end)
            fire(EVENTID_DATAMGR_DIAMOND_CHANGE, dm.diamond)
        end
        local ag = CI_MoneyOverride(6)
        if ag and tonumber(dm.eternal_diamond) ~= ag then
            pcall(function() dm.eternal_diamond = ag end)
            fire(EVENTID_DATAMGR_ETERNAL_DIAMOND_CHANGE, dm.eternal_diamond)
        end
    end
    M.ApplyMoney = CI_ApplyMoney

    CI_Install("ci_money", function()
        local dm = CI_GetDataMgr()
        if not dm or type(dm.GetMoneyByType) ~= "function" then return false end
        if dm.__ciMoneyHooked then return true end
        local origGet = dm.GetMoneyByType
        dm.GetMoneyByType = function(money_type, ...)
            local v = CI_MoneyOverride(money_type)
            if v then return v end
            return origGet(money_type, ...)
        end
        if type(dm.IsMoneyEnough) == "function" then
            local origEnough = dm.IsMoneyEnough
            dm.IsMoneyEnough = function(money_type, need, ...)
                local v = CI_MoneyOverride(money_type)
                if v then return v >= (tonumber(need) or 0) end
                return origEnough(money_type, need, ...)
            end
        end
        dm.__ciMoneyHooked = true
        return true
    end)

    CI_RegisterLobbyTick(CI_ApplyMoney)

    local function CI_ApplyRank()
        local seg = tonumber(MS_CONFIG_VIP_Config.Get("CI_RANK_SEG", 0)) or 0
        local score = tonumber(MS_CONFIG_VIP_Config.Get("CI_RANK_SCORE", 0)) or 0
        local RS = _G.ClientRankSpoof
        if RS and type(RS.cfg) == "table" then
            if seg > 0 then
                RS.cfg.segment = seg
                _G.RankSpoof_Segment = seg
            end
            if score > 0 then
                RS.cfg.score = score
                _G.RankSpoof_Score = score
            end
            local rankNo = tonumber(MS_CONFIG_VIP_Config.Get("CI_RANK_NO", 0)) or 0
            if rankNo > 0 then
                RS.cfg.rankNo = rankNo
                _G.RankSpoof_Rank = rankNo
            end
        end

        if seg <= 0 and score <= 0 then return end
        local dm = CI_GetDataMgr()
        if not (dm and type(dm.roleData) == "table") then return end
        local rd = dm.roleData
        local effSeg = seg > 0 and seg or (_G.RankSpoof_Segment or 801)
        local effScore = score > 0 and score or (_G.RankSpoof_Score or 10800)
        pcall(function()
            if type(rd.rankdata) == "table" then
                for _, zData in pairs(rd.rankdata) do
                    if type(zData) == "table" then
                        if tonumber(zData.total_rank_rating) then zData.total_rank_rating = effScore end
                        if tonumber(zData.fpp_total_rank_rating) then zData.fpp_total_rank_rating = effScore end
                        for _, v in pairs(zData) do
                            if type(v) == "table" then
                                if tonumber(v.rank_rating) then v.rank_rating = effScore end
                                if tonumber(v.rating) then v.rating = effScore end
                                if tonumber(v.level) and seg > 0 then v.level = effSeg end
                                if tonumber(v.segment) and seg > 0 then v.segment = effSeg end
                            end
                        end
                    end
                end
            end
            if seg > 0 then
                if type(rd.segment) == "table" then
                    for k, v in pairs(rd.segment) do
                        if tonumber(v) then rd.segment[k] = effSeg end
                    end
                end
                if type(rd.allzoneSegment) == "table" then
                    for _, zoneTbl in pairs(rd.allzoneSegment) do
                        if type(zoneTbl) == "table" then
                            for i = 1, 6 do
                                if tonumber(zoneTbl[i]) then zoneTbl[i] = effSeg end
                            end
                        end
                    end
                end
            end
        end)
    end
    M.ApplyRank = CI_ApplyRank

    CI_RegisterLobbyTick(CI_ApplyRank)

    local function CI_PeakSeg() return tonumber(MS_CONFIG_VIP_Config.Get("CI_PEAK_SEG", 0)) or 0 end
    local function CI_PeakScore() return tonumber(MS_CONFIG_VIP_Config.Get("CI_PEAK_SCORE", 0)) or 0 end

    local function CI_ApplyPeak()
        local seg = CI_PeakSeg()
        local score = CI_PeakScore()
        if seg <= 0 and score <= 0 then return end
        local dm = CI_GetDataMgr()
        if not (dm and type(dm.roleData) == "table") then return end
        pcall(function()
            local info = dm.roleData.peakgame_rating_info
            if type(info) == "table" then
                for _, battle_info in pairs(info) do
                    if type(battle_info) == "table" then
                        for _, rating_info in pairs(battle_info) do
                            if type(rating_info) == "table" then
                                if seg > 0 then
                                    if tonumber(rating_info.segment_id) then rating_info.segment_id = seg end
                                    if tonumber(rating_info.max_segment_id) then rating_info.max_segment_id = seg end
                                end
                                if score > 0 and tonumber(rating_info.rating) then
                                    rating_info.rating = score
                                end
                            end
                        end
                    end
                end
            end
            if seg > 0 and tonumber(dm.roleData.peakgame_history_max_segment) then
                dm.roleData.peakgame_history_max_segment = seg
            end
            local hist = tonumber(MS_CONFIG_VIP_Config.Get("CI_PEAK_HIST", 0)) or 0
            if hist > 0 then
                dm.roleData.peakgame_history_max_segment = hist
            end
        end)
    end
    M.ApplyPeak = CI_ApplyPeak

    CI_Install("ci_peak", function()
        local ok, util = pcall(require, "client.logic.PeakGame.LogicPeakGameSegmentUtil")
        if not ok or type(util) ~= "table" then return false end
        if util.__ciPeakHooked then return true end

        local function hookSeg(name)
            if type(util[name]) ~= "function" then return end
            local orig = util[name]
            util[name] = function(...)
                local seg = CI_PeakSeg()
                if seg > 0 then return seg end
                return orig(...)
            end
        end
        local function hookScore(name)
            if type(util[name]) ~= "function" then return end
            local orig = util[name]
            util[name] = function(...)
                local score = CI_PeakScore()
                if score > 0 then return score end
                return orig(...)
            end
        end

        hookSeg("GetSelfAllZoneCurSeasonMaxSegmentId")
        hookSeg("GetSelfCurZonePeakGameSegmentId")
        hookSeg("GetSelfCurZoneCurSeasonMaxSegmentId")

        if type(util.GetSelfHistoryMaxSegmentId) == "function" then
            local orig = util.GetSelfHistoryMaxSegmentId
            util.GetSelfHistoryMaxSegmentId = function(...)
                local h = tonumber(MS_CONFIG_VIP_Config.Get("CI_PEAK_HIST", 0)) or 0
                if h > 0 then return h end
                local seg = CI_PeakSeg()
                if seg > 0 then return seg end
                return orig(...)
            end
        end

        hookScore("GetSelfCurZonePeakGameRating")
        hookScore("GetSelfPeakGameRatingWithZone")

        if type(util.GetSelfAllZoneCurSeasonMaxRatingInfo) == "function" then
            local orig = util.GetSelfAllZoneCurSeasonMaxRatingInfo
            util.GetSelfAllZoneCurSeasonMaxRatingInfo = function(...)
                local info = orig(...)
                local score = CI_PeakScore()
                local seg = CI_PeakSeg()
                if type(info) == "table" then
                    if score > 0 and tonumber(info.rating) then info.rating = score end
                    if seg > 0 then
                        if tonumber(info.segment_id) then info.segment_id = seg end
                        if tonumber(info.max_segment_id) then info.max_segment_id = seg end
                    end
                end
                return info
            end
        end

        util.__ciPeakHooked = true
        return true
    end)

    CI_RegisterLobbyTick(CI_ApplyPeak)

    local function CI_Num(key) return tonumber(MS_CONFIG_VIP_Config.Get(key, 0)) or 0 end

    local function CI_BuildTitleDet(tid)
        local det = {}
        for z = 1, 6 do
            det[z] = {}
            for m = 1, 6 do
                det[z][m] = { id = tid }
            end
        end
        return det
    end
    M.BuildTitleDet = CI_BuildTitleDet

    local function CI_ApplyMisc()
        local dm = CI_GetDataMgr()
        if dm and type(dm.roleData) == "table" then

            local lv = CI_Num("CI_PLAYER_LEVEL")
            if lv > 0 and tonumber(dm.roleData.level) ~= lv then
                pcall(function() dm.roleData.level = lv end)
            end

            local tid = CI_Num("CI_TITLE_ID")
            if tid > 0 then
                pcall(function()
                    local cur = dm.roleData.allzoneSegmentTitle
                    if type(cur) ~= "table" or type(cur[1]) ~= "table" or not cur[1][1] or cur[1][1].id ~= tid then
                        dm.roleData.allzoneSegmentTitle = CI_BuildTitleDet(tid)
                    end
                end)
            end
        end

        local rp = CI_Num("CI_RP_LEVEL")
        if rp > 0 and type(_G.UnknowPassSystem) == "table" then
            pcall(function()
                if tonumber(_G.UnknowPassSystem.Level) ~= rp then
                    _G.UnknowPassSystem.Level = rp
                end
                local score = rp * 100
                if (tonumber(_G.UnknowPassSystem.Score) or 0) < score then
                    _G.UnknowPassSystem.Score = score
                end
            end)
        end
    end
    M.ApplyMisc = CI_ApplyMisc

    local function CI_ApplyKD()
        local matches = CI_Num("CI_KD_MATCHES")
        local wins = CI_Num("CI_KD_WINS")
        local top10 = CI_Num("CI_KD_TOP10")
        local kills = CI_Num("CI_KD_KILLS")
        local kd = CI_Num("CI_KD_VALUE")
        if matches <= 0 and wins <= 0 and top10 <= 0 and kills <= 0 and kd <= 0 then return end
        local ok, RS = pcall(require, "client.logic.roleinfo.logic_roleinfo")
        if not ok or type(RS) ~= "table" then return end
        local function patchList(list)
            if type(list) ~= "table" then return end
            for _, info in pairs(list) do
                if type(info) == "table" then
                    if matches > 0 then info.role_allmatchnum = matches end
                    if wins > 0 then info.role_winnum = wins end
                    if top10 > 0 then info.role_toptennum = top10 end
                    if kills > 0 then info.role_killnum = kills end
                    if kd > 0 then
                        info.role_kd = kd
                        info.role_kd_v2 = kd
                    end
                end
            end
        end
        pcall(function()
            patchList(RS.CombatTotalInfoList)
            patchList(RS.FPPCombatTotalInfoList)
            patchList(RS.MatchCombatTotalInfoList)
            patchList(RS.CareerCombatTotalInfoList)
            patchList(RS.FPPMCombatTotalInfoList)
            patchList(RS.FPPCCombatTotalInfoList)
        end)
    end
    M.ApplyKD = CI_ApplyKD

