    local function CI_ApplyCareer()
        local lv = CI_Num("CI_CAREER_LEVEL")
        local pro = CI_Num("CI_CAREER_PRO")
        if lv <= 0 and pro <= 0 then return end
        local CS = _G.CareerSystem
        if not (CS and type(CS.svrData) == "table") then return end
        pcall(function()
            local changed = false
            if lv > 0 and tonumber(CS.svrData.level) ~= lv then CS.svrData.level = lv changed = true end
            if pro > 0 then
                if tonumber(CS.svrData.pro) ~= pro then CS.svrData.pro = pro changed = true end
                if tonumber(CS.svrData.pro_season) ~= pro then CS.svrData.pro_season = pro changed = true end
            end
            if changed and EventSystem and EVENTTYPE_CAREER and EVENTID_CAREER_DATA_CHANGE then
                EventSystem:postEvent(EVENTTYPE_CAREER, EVENTID_CAREER_DATA_CHANGE)
            end
        end)
    end
    M.ApplyCareer = CI_ApplyCareer

    CI_Install("ci_career", function()
        local CS = _G.CareerSystem
        if not (CS and type(CS.OnCareerAllDataRsp) == "function") then return false end
        if CS.__ciCareerHooked then return true end
        local orig = CS.OnCareerAllDataRsp
        CS.OnCareerAllDataRsp = function(data, ...)

            pcall(CI_ApplyCareer)
            return orig(data, ...)
        end
        CS.__ciCareerHooked = true
        return true
    end)

    CI_Install("ci_credit", function()
        local ok, m = pcall(require, "client.slua.logic.ReputationSystem.logic_reputation_system")
        if not ok or type(m) ~= "table" or type(m.GetCreditScore) ~= "function" then return false end
        if m.__ciCreditHooked then return true end
        local orig = m.GetCreditScore
        m.GetCreditScore = function(self, ...)
            local v = CI_Num("CI_CREDIT_SCORE")
            if v > 0 then return v end
            return orig(self, ...)
        end
        m.__ciCreditHooked = true
        return true
    end)

    local CI_FAKE_LOVER_UID = 599000001
    local function CI_ApplyLover()
        if not CfgOn("CI_LOVER_EN") then return end
        local rel = CI_Num("CI_LOVER_TYPE"); if rel <= 0 then rel = 2 end
        if rel < 1 or rel > 6 then rel = 2 end
        local inti = CI_Num("CI_LOVER_INTIMACY"); if inti <= 0 then inti = 99999 end
        local ok, m = pcall(function()
            return ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_friend_intimacy)
        end)
        if not ok or type(m) ~= "table" or type(m.resIntimacyInfoMap) ~= "table" then return end
        pcall(function()
            local myUid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
            if not myUid and TeamUpNewSystem and TeamUpNewSystem.GetSelfUID then
                myUid = tonumber(TeamUpNewSystem.GetSelfUID())
            end
            if not myUid then return end
            m.resIntimacyInfoMap[myUid] = m.resIntimacyInfoMap[myUid] or { list = {} }
            local lst = m.resIntimacyInfoMap[myUid].list or {}
            m.resIntimacyInfoMap[myUid].list = lst
            local cur = lst[CI_FAKE_LOVER_UID]
            if type(cur) ~= "table" or tonumber(cur.relation) ~= rel or tonumber(cur.intimacy) ~= inti then
                lst[CI_FAKE_LOVER_UID] = { state = 4, param = rel, relation = rel, intimacy = inti }
            end
        end)
    end
    M.ApplyLover = CI_ApplyLover

    CI_Install("ci_lover", function()
        local ok, m = pcall(function()
            return ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_friend_intimacy)
        end)
        if not ok or type(m) ~= "table" then return false end

        if type(m.proc_on_get_intimacy_relation_rsp) == "function" and not m.__ciLoverHooked then
            local orig = m.proc_on_get_intimacy_relation_rsp
            m.proc_on_get_intimacy_relation_rsp = function(...)
                local r = orig(...)
                pcall(CI_ApplyLover)
                return r
            end
            m.__ciLoverHooked = true
        end
        pcall(CI_ApplyLover)
        return true
    end)

    CI_Install("ci_kingFinal", function()
        local ok, SPDM = pcall(require, "Server.Data.ServerPlayerDataMgr")
        if not ok or type(SPDM) ~= "table" or type(SPDM.GetPlayerProgressFromServer) ~= "function" then return false end
        if SPDM.__ci_king_finial_hooked then return true end
        local ExtendAttribute = nil
        pcall(function() ExtendAttribute = require("Server.config.ExtendAttribute") end)
        local ATTR_KING  = (ExtendAttribute and ExtendAttribute.EliminationKingEffect) or 74
        local ATTR_FINAL = (ExtendAttribute and ExtendAttribute.FinalKillEffect) or 56
        local raw = SPDM.GetPlayerProgressFromServer
        SPDM.GetPlayerProgressFromServer = function(nUID, nTypeID)
            if CI_IsSelfUid(nUID) then
                if nTypeID == ATTR_KING and CfgOn("CI_KING_EN") then
                    local id = CfgNum("CI_KING_ID", 65011001)
                    if id > 0 then return id end
                end
                if nTypeID == ATTR_FINAL and CfgOn("CI_FINAL_EN") then
                    local id = CfgNum("CI_FINAL_ID", 66010001)
                    if id > 0 then return id end
                end
            end
            return raw(nUID, nTypeID)
        end
        SPDM.__ci_king_finial_hooked = true
        return true
    end)

    CI_Install("ci_kingFallback", function()
        local ok, CADU = pcall(require, "GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
        if not ok or type(CADU) ~= "table" or type(CADU.GetPlayerExtendAttributeAndTest) ~= "function" then return false end
        if CADU.__ci_king_hooked then return true end
        local ExtendAttribute = nil
        pcall(function() ExtendAttribute = require("Server.config.ExtendAttribute") end)
        local ATTR_KING = (ExtendAttribute and ExtendAttribute.EliminationKingEffect) or 74
        local raw = CADU.GetPlayerExtendAttributeAndTest
        CADU.GetPlayerExtendAttributeAndTest = function(self, UID, attr)
            if attr == ATTR_KING and CfgOn("CI_KING_EN") and CI_IsSelfUid(UID) then
                local id = CfgNum("CI_KING_ID", 65011001)
                if id > 0 then return id end
            end
            return raw(self, UID, attr)
        end
        CADU.__ci_king_hooked = true
        return true
    end)

    CI_Install("ci_finalFallback", function()
        local ok, FKES = pcall(require, "GameLua.Mod.Library.GamePlay.Subsystem.FinalKillEffectSubsystem")
        if not ok or type(FKES) ~= "table" or type(FKES.GetFinalKillEffectItemId) ~= "function" then return false end
        if FKES.__ci_final_kill_hooked then return true end
        local raw = FKES.GetFinalKillEffectItemId
        FKES.GetFinalKillEffectItemId = function(self, PlayerCharacter, TestItemId)
            local id = raw(self, PlayerCharacter, TestItemId)
            if CfgOn("CI_FINAL_EN") then
                local ok2, mine = pcall(function()
                    local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                    local pc = GameplayData.GetPlayerCharacter()
                    return pc and PlayerCharacter == pc
                end)
                if ok2 and mine then
                    local cid = CfgNum("CI_FINAL_ID", 66010001)
                    if cid > 0 then return cid end
                end
            end
            return id
        end
        FKES.__ci_final_kill_hooked = true
        return true
    end)

    local function CI_ApplyKingLobby()
        if not CfgOn("CI_KING_EN") then return end
        local kid = CfgNum("CI_KING_ID", 65011001)
        if kid <= 0 then return end
        pcall(function()
            local LogicEKE = require("client.logic.kill_features.LogicEliminationKingEffect")
            if not LogicEKE then return end
            local inst = LogicEKE
            if LogicEKE.GetInstance then
                local okI, ret = pcall(function() return LogicEKE:GetInstance() end)
                if okI and ret then inst = ret end
            end
            if not inst then return end
            inst.elimi_king_data = inst.elimi_king_data or {}
            inst.elimi_king_data.all_effect = inst.elimi_king_data.all_effect or {}
            inst.elimi_king_data.all_effect[kid] = 1
            inst.elimi_king_data.equip_effect = kid
            if EventSystem and EventSystem.postEvent
                and EVENTTYPE_ELIMINATION_KING_EFFECTS and EVENTID_ELIMINATION_KING_EFFECTS_INFO_RSP then
                EventSystem:postEvent(EVENTTYPE_ELIMINATION_KING_EFFECTS, EVENTID_ELIMINATION_KING_EFFECTS_INFO_RSP)
                if EVENTID_ELIMINATION_KING_EFFECTS_EQUIP_UPDATE then
                    EventSystem:postEvent(EVENTTYPE_ELIMINATION_KING_EFFECTS, EVENTID_ELIMINATION_KING_EFFECTS_EQUIP_UPDATE)
                end
            end
        end)
    end
    M.ApplyKingLobby = CI_ApplyKingLobby

    local CI_emoteMap, CI_emoteMapKey = nil, nil
    local function CI_ResolveMotionId(id)

        local ok, bp = pcall(function()
            local cfg = CDataTable.GetTableData("Item", id)
            if cfg and cfg.BPID and cfg.BPID > 0 then return cfg.BPID end
            return nil
        end)
        if ok and bp then return bp end
        return id
    end
    local function CI_GetEmoteMap()
        local f1, t1 = CfgNum("CI_EMOTE_FROM1", 0), CfgNum("CI_EMOTE_TO1", 0)
        local f2, t2 = CfgNum("CI_EMOTE_FROM2", 0), CfgNum("CI_EMOTE_TO2", 0)
        local f3, t3 = CfgNum("CI_EMOTE_FROM3", 0), CfgNum("CI_EMOTE_TO3", 0)
        local key = f1 .. "_" .. t1 .. "_" .. f2 .. "_" .. t2 .. "_" .. f3 .. "_" .. t3
        if CI_emoteMap and CI_emoteMapKey == key then return CI_emoteMap end
        local map = {}
        local pairs_ = { { f1, t1 }, { f2, t2 }, { f3, t3 } }
        for _, pr in ipairs(pairs_) do
            local from, to = pr[1], pr[2]
            if from > 0 and to > 0 then
                local toMotion = CI_ResolveMotionId(to)
                map[from] = toMotion
                map[CI_ResolveMotionId(from)] = toMotion
            end
        end
        CI_emoteMap, CI_emoteMapKey = map, key
        return map
    end

    CI_Install("ci_emote", function()
        local ok, LAM = pcall(require, "client.logic.avatar.LobbyAvatarManager")
        if not ok or type(LAM) ~= "table" or type(LAM.PlayEmoteAction) ~= "function" then return false end
        if LAM.__ciEmoteHooked then return true end
        local raw = LAM.PlayEmoteAction
        LAM.PlayEmoteAction = function(uid, emoteId, sex, randSoundId, fromWhereType, extraInfo)
            if emoteId and CfgOn("CI_EMOTE_EN") and CI_IsSelfUid(uid) then
                local rep = CI_GetEmoteMap()[tonumber(emoteId) or 0]
                if rep then emoteId = rep end
            end
            return raw(uid, emoteId, sex, randSoundId, fromWhereType, extraInfo)
        end
        LAM.__ciEmoteHooked = true
        return true
    end)

    CI_RegisterLobbyTick(CI_ApplyMisc)
    CI_RegisterLobbyTick(CI_ApplyKD)
    CI_RegisterLobbyTick(CI_ApplyCareer)
    CI_RegisterLobbyTick(CI_ApplyLover)
    CI_RegisterLobbyTick(CI_ApplyKingLobby)

    function M.Refresh()
        pcall(CI_ApplyAvatar)
        pcall(CI_RefreshCollectUI)
        pcall(CI_ApplyRank)
        pcall(CI_ApplyMoney)
        pcall(CI_ApplyPeak)
        pcall(CI_ApplyMisc)
        pcall(CI_ApplyKD)
        pcall(CI_ApplyCareer)
        pcall(CI_ApplyLover)
        pcall(CI_ApplyKingLobby)
        pcall(function()

            if EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_SEASON_CHANGE then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_SEASON_CHANGE)
            end
            if EventSystem and EVENTTYPE_RANK then
                EventSystem:postEvent(EVENTTYPE_RANK, 0)
            end
            if EventSystem and EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_UPDATE_ROLEINFO then
                EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_ROLEINFO)
            end
        end)
    end
end

end
end
pcall(__LobbyModsMain)

